Ceviri.ekle("fa","olay",{
"OLAYLAR_EK5:1373-01-01:0":{"b": ["باختر فیلیپوپولیس: پیوستن تاتارپازارجیق و ایهتیمان", "1664d0e1"], "d": ["پس از گرفته شدن فیلیپوپولیس در 1372، تاتارپازارجیق در سر بالای دره مریچ و ایهتیمان که گذرگاه گشوده به صوفیه را در اختیار داشت، به اداره عثمانی پیوستند. این خط که پس از نبرد چیرمن در دست بیگ‌های محلی دست‌نشانده بود، زیر اداره مستقیم درآمد و گذرگاه فیلیپوپولیس-صوفیه پیوسته شد. این پیشروی مقدمه راهی است که دوازده سال بعد به فتح صوفیه انجامید.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["شورش ساوجی بیگ — قیام مشترک شاهزاده و ولیعهد بیزانس", "75198c33"], "d": ["ساوجی بیگ، پسر مراد یکم، و آندرونیکوس پالایولوگوس، پسر امپراتور بیزانس یوحنای پنجم، در آغاز مه 1373 همزمان در بورسا و قسطنطنیه علیه پدران خود برخاستند. این ائتلاف که ولیعهدان دو دودمان را یکی کرد زود سرکوب شد؛ ساوجی بیگ دستگیر، میل در چشمانش کشیده و اعدام شد. تاریخ 787 (1385) که روایت عثمانی برای شورش می‌دهد نادرست است؛ رویداد درست پس از سال‌هایی است که بیزانس دست‌نشانده عثمانی شد و نشان می‌دهد دو دربار تا چه اندازه درهم تنیده بودند.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["دره‌های استروما و مستا: پیوستن کوستندیل، پتریچ، نوروکوپ و دراما", "8c0980c4"], "d": ["دره‌های استروما و مستا که در دست بیگ‌های محلی صرب و بلغار بود و پس از پیروزی چیرمن به عثمانی باج می‌دادند، با پیشروی بیگ‌های مرزی زیر اداره مستقیم عثمانی درآمد. با پیوستن کوستندیل، پتریچ، نوروکوپ و دراما نیمه شرقی مقدونیه گشوده شد و سالونیک و سرز در حلقه محاصره افتادند. گسترش روم‌ایلی به سوی جنوب‌باختر بر نقشه، نتیجه این لشکرکشی است.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["پایان بیگ‌نشین ارتنا و تأسیس دولت قاضی برهان‌الدین", "60dcaf57"], "d": ["ارتنیان که در ۱۳۳۵ از والی‌گری ایلخانی پدید آمدند و چهل و شش سال بر آناتولی مرکزی با مراکز سیواس و قیصریه فرمان راندند، بر اثر رقابت‌های درونِ دربار از هم پاشیدند. قاضی برهان‌الدین که در مه ۱۳۷۸ وزیر شده بود، پس از کنار زدن رقبایش قلیچ‌ارسلان و حاجی شادگلدی، در پاییز ۱۳۸۱ سلطنت خود را اعلام کرد، بیگ‌نشین را پایان داد و دولتی را که به نام او شناخته می‌شود بنیان نهاد. بدین‌سان همسایهٔ شرقی عثمانی دست‌به‌دست شد؛ خط سیواس-قیصریه پس از آن هفده سال در دست قاضی برهان‌الدین ماند.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["تیمور هرات را گرفت: پایان خاندان کرت و گذشتن خراسان به تیموریان", "15f6019e"], "d": ["خراسان در 1380 با کشمکش سربداران، کرت‌ها و مظفریان پاره‌پاره شده بود. تیمور پس از فرستادن پسرش میران‌شاه به منطقه، خود بر هرات لشکر کشید و پس از مدتی محاصره شهر را از ملک کرت غیاث‌الدین پیر علی تحویل گرفت. شورشی که پس از رفتنش درگرفت به دست میران‌شاه با خون سرکوب شد و خاندان کرت که از 1255 در هرات حکم می‌راندند پایان یافت. سراسر خراسان از مشهد تا نیشابور در این تاریخ زیر اداره تیموری درآمد.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["پیشروی به درون مقدونیه: فتح مناستیر و اوهری", "63bb7838"], "d": ["مناستیر بر راه اگناتیا و اوهری در کنار دریاچه، هنگام یورش‌ها به سوی آلبانی به اداره عثمانی درآمدند. هر دو از نقاط کلیدی راه رسیده به آدریاتیک بودند؛ اوهری افزون بر این کهن‌ترین مرکز اسقف‌نشین ارتدوکس بالکان بود. دایرة‌المعارف ترکیه دیانت (TDV) یادآور می‌شود که برای تاریخ فتح اوهری آگاهی قطعی در دست نیست و دو تاریخ 787 (1385) و 797 (1395)، پس از مرگ مارکو کرالیویچ، پیشنهاد شده است؛ در اینجا 1385 مبنا گرفته شد. مناستیر در سده‌های بعد یکی از مهم‌ترین مراکز نظامی روم‌ایلی خواهد شد.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["نبرد ساوره — گشوده شدن دروازه‌های آلبانی", "dda6671b"], "d": ["به درخواست یاری کارلو توپیا، بیگ آلبانیایی که در برابر دودمان بالشا در تنگنا بود، نیروهای عثمانی در دشت ساوره سپاه بالشای دوم را درهم شکستند؛ بالشا در میدان جنگ جان باخت. این نبرد که به دعوت یک بیگ محلی درگرفت، نخستین نفوذ پایدار را در سرزمین‌های آلبانی تا سواحل آدریاتیک برای عثمانی‌ها فراهم کرد. این سیاست که درگیری بیگ‌های منطقه با یکدیگر را به فرصت بدل می‌کرد، در سده پیش رو شیوه ثابت فتوحات بالکان می‌شد.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["«لشکرکشی سه‌ساله» تیمور: گرفتن آذربایجان و شمال ایران", "2a98ec51"], "d": ["تیمور که در لشکرکشی‌های خراسان پراکندگی ایران را از نزدیک دیده بود، در 788 (1386) به غرب لشکر کشید. در عملیات 1386-1388 که «لشکرکشی سه‌ساله» نام گرفت، از مازندران، لرستان و گرجستان به آذربایجان گذشت و به قره‌باغ رسید؛ تبریز، اردبیل، ارومیه و نخجوان زیر اداره تیموری درآمد. گرفتن شمال ایران و آذربایجان، همچون روزگاری میان الوس جوچی و ایلخانان، آغاز کشمکشی دراز با اردوی زرین نیز بود.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["نبرد فرنگ‌یازیسی و محاصره قونیه — نخستین لشکرکشی قرامان", "af4e5d77"], "d": ["مراد یکم شخصاً علیه علاءالدین علی بیگ قرامان‌اوغلو که با وجود دامادی‌اش از گسترش عثمانی در غرب آناتولی ناخشنود بود لشکر کشید؛ در نبردی که در جایی به نام فرنگ‌یازیسی روی داد، سپاه آموزش‌دیده و کارآزموده عثمانی نیروهای قرامانی را شکست داد. سپس قلعه قونیه محاصره شد، اما با بخشوده شدن علاءالدین بیگ بیگ‌نشین یکسره برچیده نشد. این لشکرکشی آغاز تسویه‌حسابی دراز میان عثمانی و قرامان است که یک سده خواهد کشید و تنها با الحاق قطعی 1468 پایان می‌یابد.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["موش از اداره قره‌قویونلو به اداره تیمور درآمد (789/1387)", "ed2e7a11"], "d": ["موش که پس از دورهٔ مغول به اداره قره‌قویونلو درآمده بود، در 789 (1387) به اداره تیمور که صاحب سرزمین‌های قره‌قویونلو بود درآمد. در اطلس موش در این سال از قره‌قویونلو به تیموری نوشته شده است.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["بنیان‌گذاری کشتی‌سازی گلیبولو — زایش ناوگان عثمانی", "47546241"], "d": ["نخستین کشتی‌سازی سازمان‌یافته دولت عثمانی در 1390 به دست بایزید یلدریم در گلیبولو، در جای کشتی‌سازی برجامانده از بیزانس، بنیان گرفت. عثمانی که میراث دریانوردی بیگ‌نشین‌های غرب آناتولی را به ارث برده بود، بدین‌سان نخستین بار به نیرویی دریایی بدل شد که کشتی خود را خود می‌ساخت. این کشتی‌سازی که در نقطه کلیدی تنگه چاناق‌قلعه جای داشت، از محاصره قسطنطنیه تا لشکرکشی‌های اژه، یک سده و نیم پایگاه اصلی ناوگان عثمانی بود.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["حمید‌ایلی به عثمانی پیوست: اسپارتا، بوردور، اولوبورلو، اغیردیر", "e3da7de5"], "d": ["بایزید یلدریم پس از حمله علاءالدین بیگ قرامان‌اوغلو به حمید‌ایلی و شکایت مردم، به لشکرکشی برخاست و همه سرزمین‌های باقی‌مانده حمیدوغولاری را گرفت و اداره آن را به پسرش عیسی چلبی سپرد.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["پایان خاندان مظفری: شکست شاه منصور در برابر شیراز", "5fd14eb8"], "d": ["شاه منصور، واپسین فرمانروای نیرومند مظفریان که از 1318 در یزد، فارس، اصفهان و کرمان حکم می‌راندند، با خویشانش متحد شد و علیه تیمور به حرکت درآمد. در نبرد نزدیک شیراز با گذشتن یکی از امیرانش به سوی طرف مقابل بیشتر نیروهایش را از دست داد، شکست خورد و کشته شد. با آنکه تیمور پس از آن همهٔ اعضای خاندان را نیز کشت، سلطهٔ مظفری پایان یافت و فارس و کرمان به اداره تیموری پیوست.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["پیوستن آماسیه به سرزمین‌های عثمانی", "fe2860cf"], "d": ["امیر آماسیه، که در جریان لشکرکشی یلدرم بایزید به آناتولی میانه در محاصره بود، شهر را به عثمانیان تسلیم کرد و بایزید در ۱۳۹۳ وارد شهر شد. سلطان اداره آنجا را به پسرش محمد چلبی واگذاشت؛ آماسیه از آن پس به‌عنوان سنجق شاهزادگان یکی از مهم‌ترین کانون‌های پرورش خاندان عثمانی شد. سایر سکونتگاه‌هایی که در همین تاریخ از دست رفتند: لادیک (آماسیه)، مرزیفون، عثمانجیق، چوروم. این گزینش در دوران فترت پسین سرنوشت‌ساز می‌شد و چلبی محمد مبارزه برای یکپارچه‌سازی دوباره دولت را از همین پایگاه آماسیه پیش می‌برد.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["تیمور بغداد را گرفت — جلایریان به آناتولی گریختند", "4d5602b3"], "d": ["تیمور پس از محاصره‌ای دراز بغداد را گرفت؛ سلطان احمد جلایری، حاکم شهر، به غرب گریخت و نخست به ممالیک و سپس به دربار عثمانی پناه برد. گسترش تیمور به سوی غرب بدین‌سان نخستین بار با حوزهٔ نفوذ عثمانی تماس مستقیم یافت. نخستین حلقهٔ دشمنی میان دو فرمانروا از اینجا آغاز می‌شود.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["گرفتن وارنا در ساحل دریای سیاه", "a84b2abf"], "d": ["هنگامی که سرزمین‌های تزارنشین بلغارستان میان دانوب و دریای سیاه تنگ‌تر می‌شد، وارنا، بزرگ‌ترین بندر ساحلی، به اداره عثمانی درآمد. گرفتن این بندر راه پیشروی به سوی دوبروجه را گشود و نخستین اسکله بزرگ عثمانی را در ساحل باختری دریای سیاه فراهم کرد. وارنا پنجاه و یک سال بعد صحنه پیروزی 1444 نیز خواهد بود که در آن سپاه صلیبی نابود شد.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["ناحیهٔ نوشهر و ارگوپ از قرامان‌اوغولاری به دست عثمانی افتاد", "06ff59e8"], "d": ["در لشکرکشی‌های یلدرم بایزید علیه قرامان‌اوغولاری، نوشهر (مشکره) و ناحیهٔ ارگوپ در 800/1398 به اداره عثمانی درآمد؛ در 1402 پس از نبرد آنکارا تیمور منطقه را به قرامان‌اوغولاری بازگرداند.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["فروپاشی دولت قاضی برهان‌الدین", "b13391e3"], "d": ["قاضی برهان‌الدین که به دست قره‌یولوق عثمان بیگ، فرمانروای آق‌قویونلو، اسیر افتاد، هرچند در برابر تسلیم سیواس پیشنهاد آزادی یافت، مردم شهر مقاومت کردند و سلطان در برابر باروها اعدام شد. بزرگان سیواس پسرش علاءالدین علی چلبی را بر تخت نشاندند، اما در برابر فشار آق‌قویونلو از بایزید یلدریم یاری خواستند؛ نیروهای عثمانی به فرماندهی سلیمان چلبی قره‌یولوق را شکست دادند و بر شهر چیره شدند. بدین‌سان دولت قاضی برهان‌الدین از صحنه تاریخ رفت و سیواس، توقات، نیکسار و کایسری به سرزمین‌های عثمانی پیوست. جاهای دیگری که در همین تاریخ پیوستند: کیرشهیر، چوروم.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["رودررویی با تیمور: بازگرداندن گریختگان رد شد", "33790bc8"], "d": ["با فشار تیمور، سلطان احمد جلایری و رهبر قره‌قویونلو قره یوسف به سرزمین عثمانی پناه بردند؛ تیمور بازگرداندن این دو گریخته را خواست و یلدیرم بایزید رد کرد. در پی آن نامه‌هایی با توهین‌های سنگین متقابل میان دو فرمانروا مبادله شد. زمینهٔ ایدئولوژیک جنگ پیش از حرکت یک سرباز با همین نامه‌نگاری‌ها بنا شد.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["دارالشفای یلدریم در بورسا — نخستین بیمارستان عثمانی", "5f0dc59a"], "d": ["بایزید یلدریم در سال‌هایی که مسجد جامع باشکوه بورسا (اولوجامی) را می‌ساخت، دارالشفایی هم برای شهر فراهم آورد؛ این حلقه‌ای بود که در برنامه گسترده خیرات او، شامل عمارت، مدرسه، کاروانسرا و پل، به پزشکی اختصاص یافت. این بنا که نخستین بیمارستان ساخته دولت بود، با کارکرد مکتب پزشکی پرورش‌دهنده پزشک نیز الگوی نهادهای بهداشتی عثمانی را تعیین کرد. اثری که تنها دو سال پیش از فاجعه آنکارا به پایان رسید، از واپسین حلقه‌های تصور یلدریم برای تبدیل بورسا به پایتخت امپراتوری است.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["تیمور سیواس را با خاک یکسان کرد", "f4d79de6"], "d": ["تیمور که به راهنمایی آق‌قویونلو قره‌یولوق عثمان بیگ و امیر ارزنجان مطهرتن بر سیواس لشکر کشید، شهر را هجده روز محاصره کرد و با وعدهٔ اینکه خون کسی ریخته نخواهد شد تحویل گرفت، سپس قتل‌عام بزرگی کرد؛ مدافعان را در خندق‌ها ریخت و زنده زیر خاک کرد. آثار مهم شهر، در رأس آنها دیوارها، تخریب شد و سیواس از نظر جمعیتی فرو ریخت. این نخستین ضربهٔ بزرگی است که تیمور دو سال پیش از نبرد آنکارا بر سرزمین عثمانی فرود آورد.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["یلدیرم بایزید ارزنجان و کماخ را بازپس گرفت", "7047ca08"], "d": ["یلدیرم بایزید که رفتن تیمور به لشکرکشی سوریه را فرصت شمرد، ارزنجان و کماخ را از دست مطهرتن، امیر ارزنجان که تابع تیمور بود، گرفت. این حرکت، با آنکه در ویرانی سیواس دخالت نکرده بود، به معنای به چالش کشیدن مستقیم حوزهٔ نفوذ تیمور در آناتولی شرقی بود. رابطهٔ دو فرمانروا از این پس ترمیم‌ناپذیر شد.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["اولتیماتوم تیمور از تبریز — چهار شرط", "3e1ac50e"], "d": ["تیمور با فرستاده‌ای از تبریز چهار شرط اعلام کرد: بازگرداندن کماخ به مطهرتن، بازگرداندن سرزمین‌هایی که از بیگ‌های آناتولی گرفته شده به صاحبانشان، فرستادن یک شاهزاده عثمانی به گروگان و پذیرفتن کلاه و کمربند به نشانهٔ تبعیت، و تسلیم قره یوسف. بایزید هیچ‌یک را نپذیرفت؛ به‌رغم اصرار دولتمردان و میانجی‌گری مطهرتن مذاکرات فروپاشید. تیمور مصمم بود پیش از رفتن به لشکرکشی چین، مسئلهٔ آناتولی را قطعاً ببندد.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["صاروخان‌اوغلوها دوباره برپا شدند — مانیسا از عثمانی بیرون رفت", "ac747b05"], "d": ["سه هفته پس از شکست آنکارا با پشتیبانی تیمور اورخان بیگ بر امارت نشست و ایالت صاروخان دوباره مستقل شد. منطقهٔ مرکزیت مانیسا، دوازده سال پس از الحاق عثمانی در 1390، از نقشه بیرون رفت. این از نخستین اجراهای قطعاً تاریخ‌دار سیاست زنده‌کردن امارت‌ها به دست تیمور است.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["امیر سلیمان با خزانهٔ دولت به روم‌ایلی گریخت", "0a2b7363"], "d": ["امیر سلیمان که خزانهٔ دولت، آرشیوها، خانواده و برادرانش را در بورسا با خود برده بود، از گملیک با کشتی به گوزل‌جه‌حصار (آناتولی حصاری) گذشت، از آنجا به گلیبولو رسید و در ادرنه فرمانروایی خود را اعلام کرد. بردن آرشیو و خزانهٔ دولت به روم‌ایلی آغاز لغزیدن مرکز ثقل عثمانی به بالکان برای یک نسل است. در نقشه روم‌ایلی از این تاریخ با رنگ خاص امیر سلیمان ترسیم می‌شود.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["تیمور بیگ‌نشین‌های آناتولی را از نو برپا کرد — یگانگی ترکان فروپاشید", "15187774"], "d": ["تیمور پس از پیروزی آنکارا بیگ‌هایی را که همراهش بودند به سرزمین‌های پیشین خود بازگرداند. به قراماناوغلو محمد و علی بیگ ولایت قرمان با قیصریه، کیرشهر، سیواری‌حصار و بیشهر؛ به گرمیان‌اوغلو یعقوب بیگ دوم کوتاهیه و ولایت گرمیان؛ به چندارداوغلو اسفندیار بیگ، افزون بر خط قسطمونی-سینوپ، چانکیری و کالجیک داده شد. ولایت‌های آیدین، منتشه و تکه نیز به دودمان‌های پیشین بازگشت. یگانگی ترکان آناتولی که یلدرم بایزید در ده سال برپا کرده بود در یک تابستان فروپاشید؛ بر نقشه این بیگ‌نشین‌ها دوباره به رنگ خود پدیدار می‌شوند. سایر سکونتگاه‌هایی که در همین روند دست‌به‌دست شدند: آق‌سرای، دنیزلی، ارگلی (قونیه)، ارمنک، ایلغین، قاراپینار، قیصریه، قونیه، کیرشهر، کوتاهیه، سیواری‌حصار، سوکه.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["تیمور ازمیر را از شوالیه‌های سن ژان گرفت", "66dd1dd4"], "d": ["تیمور که از کوتاهیه، دنیزلی، آیدین، آیاسولوک و تیره به غرب فرود آمد، ازمیر ساحلی را که از 1344 در دست مسیحیان بود محاصره و تصرف کرد. تیمور این قلعه را که یلدیرم بایزید سال‌ها نتوانسته بود بگیرد در مدتی کوتاه گرفت و پس از تصرف قلعه‌های پیرامون ایالت آیدین را به صاحبان پیشین سپرد و به شرق بازگشت. شهر از آن پس به اداره آیدین‌اوغلو جنید بیگ درآمد.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["عیسی چلبی بورسا را گرفت — سهم آناتولی پدید آمد", "955128c1"], "d": ["عیسی چلبی که پس از شکست آنکارا به سوی قره‌سی عقب نشسته بود، هنگامی که تیمور در ازمیر بود بورسا را گرفت. او در پایتخت پیشین که سربازان تیمور آن را غارت و سوزانده بودند فرمانروایی خود را اعلام کرد و به نام خود سکه زد؛ در ژانویه 1403 در آناتولی با عنوان «فرمانروای ترکان» شناخته می‌شد. در نقشه این سهم که در امتداد ساحل آسیایی مرمره کشیده است به رنگ خاص عیسی چلبی پدیدار می‌شود.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["عقب‌نشینی تیمور از آناتولی", "93a98839"], "d": ["تیمور با دریافت خبر درگذشت یلدیرم بایزید در آق‌شهر، کار خود را در آناتولی تمام‌شده شمرد و به شرق روی آورد. پشت سر او امارت‌هایی که اعلام وفاداری کرده بودند و شاهزادگان عثمانی که با هم افتاده بودند ماندند؛ برخی شهرها چون سیواس در دست امیرانی مانند مزید بیگ که تابع تیمور بودند رها شد. تیمور دیگر به آناتولی بازنگشت، اما این نظم پاره‌پاره‌ای که او ساخت ده سال ادامه یافت.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["امیر سلیمان به آناتولی گذشت: بورسا به دست او افتاد", "9b27aa5f"], "d": ["امیر سلیمان با شنیدن شکست عیسی چلبی همراه چاندارلی علی پاشا با سپاهی نیرومند به آناتولی گذشت و بورسا را گرفت؛ اسناد مارس ۱۴۰۴ نشان می‌دهد کاراده‌نیز ارگلی نیز زیر اداره او بود. چلبی محمد در برابر سلیمان که در زمانی کوتاه هم بر روم‌ایلی و هم بر بخش بزرگ آناتولی چیره شد نتوانست پایداری کند. سایر سکونتگاه‌هایی که در همین روند از چلبی محمد به امیر سلیمان رسید: آق‌یازی، آناطولی‌حصار، ابسو (Hypsu)، آدرانوس (ارهانلی)، آق‌حصار (پاموکووا)، آرموتلو، قلعه آیدوس، آیوالیک، بالیک‌اسیر، بهرام‌کالی (Assos)، برگامه، بیکوز، بیگا. بر نقشه از این تاریخ تا بازپس‌گیری بورسا به دست چلبی محمد (۱۴۱۰) دو ساحل به یک رنگ، در سهم امیر سلیمان، دیده می‌شود.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["نبرد دشت ینی‌شهر — چلبی محمد به آماسیه عقب نشست", "f1568288"], "d": ["چلبی محمد که بورسا و آنکارا را از دست داده بود، در دشت ینی‌شهر از امیر سلیمان شکست خورد و همهٔ دستاوردهایش در آناتولی غربی را از دست داد و به پایگاه توقات-آماسیه عقب نشست. پس از این شکست از درگیری مستقیم پرهیز کرد و به استوار ساختن اقتدارش در درون آناتولی روی آورد. درازترین مرحلهٔ خاموش فترت این‌گونه آغاز شد.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["امیر سلیمان آنکارا را از چلبی محمد گرفت", "d6a2acd6"], "d": ["پس از عقب‌نشینی تیمور از آناتولی، امیر سلیمان در 1406 آنکارا را که در دست چلبی محمد مانده بود محاصره کرد. یعقوب بیگ، فرمانده قلعه، مدتی پایداری کرد، اما با نیرنگ صدراعظم چاندارلی علی‌پاشا قلعه را به سلیمان تسلیم کرد. چلبی محمد در پی این رویداد با قرامان‌اوغلو محمد بیگ پیمان بست و علیه سلیمان وارد عمل شد.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["چلبی محمد سیواس را از مزید بیگ تیموری بازپس گرفت", "90079b0c"], "d": ["پس از یورش تیمور، اداره سیواس به مزید بیگ، تابع تیمور، سپرده شده بود. چلبی محمد از آماسیه فرمانده خود بایزید پاشا را برای گرفتن شهر فرستاد و پس از مقاومتی سخت، سیواس برای بار دوم به دست دودمان عثمانی افتاد. بدین‌سان سهم محمد، شش سال پس از نبرد آنکارا، در شرق به مرز پیشین خود رسید.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["پایان دودمان ارتقی: تسلیم ماردین به قره‌قویونلو", "15b06f33"], "d": ["ارتقیان که از 1106 در ماردین فرمان می‌راندند و دیرپاترین شاخه این دودمان بودند، در برابر فشار آق‌قویونلو تاب نیاوردند. ملک احمد که دریافت نمی‌تواند شهر را پاس دارد، با قره‌یوسف، فرمانروای قره‌قویونلو، توافق کرد و ماردین را به او تسلیم نمود. فرمانروایی ارتقی که از سه سده فراتر رفته بود بدین‌سان پایان یافت؛ ماردین و پیرامونش تا یک سده بعد که به عثمانی رسید، صحنه کشمکش قره‌قویونلو و آق‌قویونلو بود.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["نبرد یامبولی — موسی چلبی وارد ادرنه شد", "8f978408"], "d": ["موسی چلبی که از راه افلاق به روم‌ایلی گذشته بود، با پشتیبانی افلاق و صرب‌ها در یامبولی نیروهای امیر سلیمان را درهم شکست و وارد ادرنه شد. در دوران فترت، روم‌ایلی نخستین بار از دست امیر سلیمان بیرون رفت. اما فرمانروایی او پایدار نبود؛ چهار ماه بعد در کوسمیدیون شکست خورد و به درون بالکان عقب نشست.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["نبرد اینه‌گوز — نخستین شکست چلبی محمد در روم‌ایلی", "3c35cd43"], "d": ["چلبی محمد که با کشتی‌های بیزانس به روم‌ایلی گذشته بود، در اینه‌گوز با موسی چلبی جنگید؛ موسی با هفت هزار ینی‌چری زیر فرمان خود محمد را شکست داد و محمد ناگزیر به آناتولی بازگشت. این شکست او را به راهبردی کشاند که به جای جنگ مستقیم، بیگ‌های مرزی روم‌ایلی و دسپوتی صربستان را به سوی خود بکشد. زمینه پیروزی چامورلو، نه ماه بعد، با همین دیپلماسی فراهم شد.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["محاصره قونیه و پیمان با قرامان‌اوغولاری — حمید‌ایلی، سعید‌ایلی، بیشهری، سیدی‌شهری و آق‌شهر بازگرفته شد", "0996257e"], "d": ["چلبی محمد علیه قرامان‌اوغولاری که در دوران فترت به سرزمین‌های عثمانی حمله کرده و بورسا را محاصره و آتش زده بودند، لشکرکشی بزرگی سامان داد و در محرم 818 قونیه را محاصره کرد. محمد بیگ دوم قرامان‌اوغلو ناگزیر درخواست صلح کرد؛ در نتیجه پیمان حمید‌ایلی (پیرامون اسپارتا) و سعید‌ایلی دوباره به سرزمین‌های عثمانی پیوست، بیشهری، سیدی‌شهری و آق‌شهر نیز بازگردانده شد؛ سیواری‌حصار که تیمور در 1402 به قرامان‌اوغولاری داده بود نیز به عثمانی‌ها بازگشت. این لشکرکشی که در آن وصله‌کاری یگانگی آناتولی فروپاشیده با نبرد آنکارا آغاز شد، از دلایل عینی «بنیان‌گذار دوم» شمرده شدن چلبی محمد است.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["گرفتن ازمیر از جنید بیگ آیدین‌اوغلو", "2377ca51"], "d": ["ازمیر، مرکز جنید بیگ آیدین‌اوغلو که در دوران فترت پیوسته میان شاهزادگان جانب عوض می‌کرد، پس از ده روز محاصره به دست چلبی محمد گرفته شد؛ جنید بخشوده شد و به بیگ‌نشینی سنجق نیکوپولی فرستاده شد. شهری که تیمور در 1402 به آیدین‌اوغلوها بازگردانده بود، بدین‌سان پس از سیزده سال به عثمانی بازگشت. جنید در 1422 شهر را دوباره به چنگ خواهد آورد و این مسئله تنها در 1424-1426 به دست مراد دوم پایان خواهد یافت.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["اعدام تورلاک کمال — ساروخان برای همیشه از آنِ عثمانی", "8a09dbf1"], "d": ["تورلاک کمال که شاخه غرب آناتولی جنبش شیخ بدرالدین را رهبری می‌کرد، در پیرامون مانیسا شکست خورد و اعدام شد. پس از این تاریخ، ناحیه ساروخان برای همیشه به زیر فرمان عثمانی درآمد و بیگ‌نشینی که تیمور در 1402 زنده کرده بود از میان رفت. بدین‌سان واپسین بازمانده‌های سیاسی دوران فترت در غرب آناتولی پاک شد.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["فتح والونا، برات و کانینا", "1e1949b8"], "d": ["عثمانی‌ها در 1417 والونا را در ساحل آدریاتیک، همراه با شهر برات در درون کشور و قلعه کانینا، زیر فرمانروایی خود گرفتند. یک سال بعد کوشش ونیز برای بازپس‌گیری شهر ناکام ماند و با برپایی تشکیلات سنجق در آنجا اقتدار عثمانی پایدار شد. گرفتن والونا عثمانی را نخستین بار در آدریاتیک صاحب بندری مستقیم کرد و در برابر ایتالیا سکوی پرشی فراسوی دریا برایش فراهم آورد.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["بازپس‌گیری آناتولی میانه: کایسری و کیرشهیر", "204eacb3"], "d": ["شهرهای آناتولی میانه که در دوران فترت به دست قرامان‌اوغولاری افتاده بود، در لشکرکشی‌های چلبی محمد برای سامان‌دهی دوباره دولت به اداره عثمانی بازگشت. با پیوستن کایسری و کیرشهیر، حوضه قزل‌ایرماق که در نبرد آنکارا از دست رفته بود تا حد زیادی بازگرفته شد. این پیشروی ادامه سیاست روی‌آوری به شرق است که با محاصره قونیه چهار سال پیش آغاز شده بود.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["ممالیک کایسری را به ناصرالدین محمد دولکادیرلی دادند", "aad4b00c"], "d": ["سپاه ممالیک که علیه قرامان‌اوغلو محمد بیگ لشکر کشیده بود، کایسری را اشغال کرد؛ فرمانده ممالیک شهر و پیرامون آن را به ناصرالدین محمد دولکادیرلی واگذاشت و به سرزمین خود بازگشت.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["درگذشت محمد یکم و جلوس مراد دوم", "98acac77"], "d": ["محمد یکم که دورهٔ فترت را پایان داد و قلمرو عثمانی را دوباره در یک دست گرد آورد، در 25 ژوئن 1421 در ادرنه درگذشت و پسرش مراد در بورسا بر تخت نشست. بر پایهٔ ترتیبی که پیش از مرگ او با بیزانس داده شده بود، پسران کوچکش به‌عنوان گروگان نزد امپراتور فرستاده می‌شدند و امپراتور نیز مدعی تاج‌وتخت، مصطفی چلبی، را که در دست داشت آزاد نمی‌کرد؛ مراد دوم از فرستادن برادرانش نزد امپراتور سر باز زد.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["برچیده شدن قطعی تکه‌اوغولاری: گرفتن آنتالیا", "e65565b2"], "d": ["بیگ‌نشینی تکه‌اوغولاری که پس از نبرد آنکارا با زنده کردن تیمور دوباره بنیان گرفته بود، با محاصره آنتالیا به دست نیروهای عثمانی به فرماندهی حمزه بیگ پایان یافت؛ عثمان چلبی، واپسین مرد مهم بیگ‌نشین، از میان برداشته شد. بدین‌سان ایالت تکه در ساحل مدیترانه پس از بیست و یک سال جدایی برای همیشه به عثمانی پیوست. این بیگ‌نشین از 1321 به‌عنوان شاخه‌ای جداشده از حمیدوغولاری در آنتالیا فرمان می‌راند.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["لشکرکشی تورهان بیگ به موره و ویرانی دیوار هگزامیلیون", "c6c2706d"], "d": ["چون بیزانس مدعی رقیب تاج‌وتخت، مصطفی چلبی، را پشتیبانی کرد، مراد دوم تورهان بیگ را به موره فرستاد. تورهان بیگ دیوار هگزامیلیون را که گردنه کورنت را سراسر می‌بست ویران کرد و به شبه‌جزیره درآمد و خرابی بزرگی به بار آورد. صلح به این شرط برقرار شد که دیوار دیگر بازسازی نشود و باج سالانه پرداخت گردد؛ دسپوتی موره بدین‌سان از نظر نظامی بی‌دفاع ماند و زمینه فتح نهایی 1460 سی و هفت سال پیشتر فراهم شد.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["درآمدن صومعه‌های آتوس (آینا‌روز) به حمایت عثمانی", "562de5ea"], "d": ["در سال‌هایی که سالونیک در محاصره بود، جمهوری صومعه‌های آتوس در انگشت شرقی خالکیدیکی به مراد دوم روی آورد، حمایت خواست و فرمانروایی عثمانی را پذیرفت. حقوق مالکیت و عبادت راهبان تضمین شد؛ صومعه‌ها در برابر مالیات در امور درونی خود آزاد ماندند. این نظم دیرپاترین نمونه رابطه حمایتی عثمانی با نهادهای ارتدوکس شد و پنج سده ادامه یافت.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["الحاق بیگ‌نشین تاج‌الدین‌اوغولاری: نیکسار", "370ffd47"], "d": ["به فشار یورگوچ پاشا، بیلربیگی آماسیه، حسام‌الدین حسن بیگ تاج‌الدین‌اوغلو کلیدهای سرزمین خود را که مرکزش نیکسار بود در سال 830 (1427) تسلیم کرد و در روم‌ایلی سنجقی به او داده شد. بیگ‌نشینی که در نیمه دوم سده چهاردهم بنیان گرفته بود و مرزهایش گاه تا کلکیت، آماسیه، سامسون، اردو و گیرسون می‌رسید، بدین‌سان پایان یافت. در همان سال زمین‌های متعلق به حاجی‌امیراوغولاری نیز تحریر و به سنجق جانیک پیوسته شد؛ دوران بیگ‌نشین‌ها در دریای سیاه میانه بسته شد.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["واگذاری بلگراد به مجارستان — پیمان تاتا", "62481183"], "d": ["با مرگ استفان لازارویچ، دسپوت صرب، بنا بر پیمان تاتا که میان سیگیسموند، پادشاه مجارستان، و وارث او گئورگ برانکوویچ امضا شد، قلعه بلگراد به مجارستان واگذار گشت. قلعه که در نقطه پیوستن دانوب و ساوا ایستاده بود تا آن روز در دست دسپوتی صرب بود و برای عثمانی قفل دروازه گشوده به اروپای میانه بود. این واگذاری بلگراد را یک سده سخت‌ترین مانع بر راه پیشروی عثمانی کرد: محاصره‌های 1440 و 1456 ناکام خواهد ماند و قلعه تنها در 1521 فرو خواهد افتاد.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["ماردین از نگهبان قره‌قویونلو به قره‌یولوق عثمان بیگ آق‌قویونلو رسید", "d82bc97f"], "d": ["ماردین را که قره‌یوسف در 1409 گرفته بود، قره‌قویونلوها با والیان اداره کردند؛ امیر ناصر که نگهبان شهر بود، آن را در 835 (1432) به قره‌یولوق عثمان بیگ آق‌قویونلو تسلیم کرد. اداره آق‌قویونلو تا آغاز سده شانزدهم ادامه یافت.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["قرامان‌اوغولاری کایسری را از دولکادیرلی‌ها گرفتند", "2b09e8e8"], "d": ["بیگ قرامان با پیروزی بر دولکادیرلی‌ها کایسری، اورگوپ، قره‌حصار دوه‌لی و اوچ‌حصار را به سرزمین خود افزود.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["رویداد بوچوک‌تپه — نخستین شورش ینی‌چریان و بازگشت مراد دوم به تخت", "6388dda1"], "d": ["رویداد بوچوک‌تپه که در ادرنه درگرفت و نخستین شورش ینی‌چریان در تاریخ است، با خواست افزودن نیم آقچه به «اولوفه» (مواجب) آنان آغاز شد و به برکناری محمد دوم جوان انجامید. مراد دوم در 8 صفر 850 با شتاب از مانیسا راه افتاد و سلطنت دوم خود را آغاز کرد. این رویداد نخستین نشانه بود که اوجاق قاپی‌قولو اکنون نیرویی دارای سخن بر تخت شده است و احتیاط فاتح در برابر ینی‌چریان را که تا پایان عمر ادامه یافت شکل داد.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["پیوستن ساحل اپیروس: آرتا و پروزه", "796f7ecf"], "d": ["نوزده سال پس از تسلیم یانینا در 1430، آرتا و پروزه در بخش ساحلی دسپوتی اپیروس نیز به اداره عثمانی درآمدند. بدین‌سان خلیج آمبراکیا که به دریای ایونی باز می‌شود زیر نظارت درآمد و پیوند دریایی یانینا کامل شد. پروزه نقطه کلیدی همان خلیجی است که نود سال بعد نام خود را به پیروزی تاریخی بارباروس خواهد داد.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["درگذشت مراد دوم و دومین جلوس محمد دوم", "8f8256ad"], "d": ["مراد دوم پس از جشن عروسی پسرش بیمار شد و در 1 محرم 855 (3 فوریه 1451) در ادرنه درگذشت. محمد دوم نوزده‌ساله در 16 محرم 855 (18 فوریه 1451) برای بار دوم بر تخت عثمانی نشست — این بار برای همیشه. بازگشت این فرمانروای جوان که پنج سال پیش در بوچوک‌تپه از تخت برکنار شده بود، آغاز سلطنتی است که دو سال بعد با فتح قسطنطنیه تاج خواهد گرفت و بیگ‌نشین عثمانی را به امپراتوری جهانی بدل خواهد کرد.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["نخستین محاصره مشترک کفه به دست نیروهای عثمانی و کریمه", "e346d163"], "d": ["حاجی گرای، خان کریمه، که در ژوئن 1454 با سلطان محمد فاتح توافق کرد، با 7000 سوار کفه را از خشکی محاصره کرد؛ ناوگانی عثمانی شامل پنجاه تا شصت گالی نیز در دریا موضع گرفت. کفه جنوایی با پرداخت باج محاصره را برچید و فتح قطعی به بیست و یک سال بعد، 1475، موکول شد. این نخستین عملیات مشترک، نخستین نمونه همکاری نظامی عثمانی و کریمه بود که بعدها در فتح قطعی کفه تکرار خواهد شد.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["گرفتن جزایر اژه شمالی: بوزجاآدا، ایمروز و تاسوس", "76575895"], "d": ["سلطان محمد فاتح بی‌درنگ پس از فتح قسطنطنیه برای ایمن کردن راه دریایی پایتخت نو به جزایر دهانه اژه تنگه چاناق‌قلعه روی آورد؛ بوزجاآدا و ایمروز از بیزانس و تاسوس از خاندان گاتیلوزیو جنوایی‌تبار گرفته شد. این جزایر که دو کرانه تنگه را قفل می‌کردند، از آن پس نخستین حلقه خط آذوقه و دفاع استانبول شدند. با دخالت ناوگان‌های پاپ و ونیز فرمانروایی مدتی دست‌به‌دست شد و تنها در 1459 قطعی گشت.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["فتح کوزوو: گرفتن پریشتینا و یگی‌پازار", "d7ed2345"], "d": ["سپاه عثمانی که بر دسپوتی صربستان لشکر کشیده بود، پریشتینا را در دشت کوزوو و یگی‌پازار، مرکز منطقه راشکا، را گرفت؛ در همان لشکرکشی نووابردا که به معادن نقره مشهور بود نیز گرفته شد. بدین‌سان نیمه جنوبی صربستان مستقیماً به اداره عثمانی پیوست و مرکز دسپوتی در سمندره از سرزمین‌هایش جدا شد. این فتح گام تعیین‌کننده راهی بود که چهار سال بعد به الحاق کامل صربستان انجامید.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["ایپک (پچ) به اداره عثمانی درآمد — از مراکز سنجق دوکاکین", "19511588"], "d": ["در 1455، بی‌درنگ پس از لشکرکشی سلطان محمد فاتح به صربستان، ایپک، مرکز پاتریارکی صرب، به اداره عثمانی درآمد؛ در منابع عثمانی دربارهٔ این گذار سندی نیست. شهرک با گذر زمان به شهرکی کوچک و مسلمان‌نشین بدل شد و در سنجق دوکاکین یکی از اقامتگاه‌های سنجق‌بیگی شد.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["فتح ائنز و سموتراکی — تکمیل ساحل تراکیه غربی", "106e723b"], "d": ["ائنز در جایی که رود مریچ به دریا می‌ریزد، از خاندان گاتیلوزیو جنوایی‌تبار که هشتاد سال آنجا را در دست داشتند گرفته شد؛ جزیره سموتراکی وابسته به آن نیز در همان لشکرکشی گرفته شد. با سقوط ائنز، نوار ساحلی تراکیه غربی از سالونیک تا گلیبولو یکسره خاک عثمانی شد. در دست خاندان گاتیلوزیو تنها میتیلینی ماند که آن نیز شش سال بعد گرفته خواهد شد.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["ناکامی محاصره بلگراد", "3d53a604"], "d": ["سلطان محمد فاتح پس از فتح قسطنطنیه بلگراد، قفل اروپای میانه، را محاصره کرد؛ اما نیروی کمکی که یانوش هونیادی از دانوب آورد و داوطلبانی که کاپیسترانو، واعظ صلیبی، گرد آورد از سقوط قلعه جلوگیری کرد. پادشاه با وجود دلاوری شخصی‌اش در پای محاصره زخمی شد و ناگزیر عقب نشست. این ناکامی مرز مجارستان را شصت و پنج سال بر پیشروی عثمانی بست؛ بلگراد تنها در 1521 به دست سلیمان قانونی گرفته خواهد شد.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["فتح موره شمالی: پاتراس (بالیابادرا)", "c08a8509"], "d": ["نیروهای سلطان محمد فاتح که همزمان با الحاق صربستان به دسپوتی موره روی آوردند، بالیابادرا را در شمال‌باختر شبه‌جزیره گرفتند. این بندر که دهانه خلیج کورنت را در دست دارد، قفل ورود زمینی به موره است؛ گرفتن آن زمینه فتح نهایی دو سال بعد را فراهم کرد. شهر واپسین اسکله بزرگی بود که دسپوت‌های بیزانس از آنجا با جهان لاتین پیوند می‌یافتند.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["گرفتن ساحل باختری دریای سیاه: آماسره", "f43608fc"], "d": ["آماسره، مستعمره مستحکم جنوا در دریای سیاه باختری، با فشار مشترک نیروی دریایی و زمینی سلطان محمد فاتح بی‌مقاومت تسلیم شد. این بندر در ساحل بارتین-زونگولداک مانند یک جیب لاتین میان چاندارولاری و سرزمین‌های عثمانی بود؛ با گرفتنش ساحل یکپارچه شد. سقوط آماسره نخستین گام لشکرکشی بزرگ دریای سیاه است که دو سال بعد (1461) به سینوپ و طرابزون روی خواهد آورد.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["فتح جزیره میتیلینی", "fe17aeba"], "d": ["سپاه عثمانی به فرماندهی سلطان محمد فاتح در ذی‌الحجه 866 میتیلینی را پس از محاصره‌ای کوتاه اما سخت از خاندان گاتیلوزیو جنوایی‌تبار گرفت و ضمیمه کرد. سقوط بزرگ‌ترین جزیره اژه شمالی واپسین پایگاه مهم جنوایی‌ها را در منطقه نیز برچید. این جزیره به سبب نزدیکی به ساحل آناتولی از آن پس برای ناوگان عثمانی پاسگاه پیشرو شد و همچنین به‌عنوان زادگاه برادران بارباروس به تاریخ دریانوردی راه یافت.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["آغاز جنگ شانزده‌ساله عثمانی و ونیز", "563ddb68"], "d": ["ونیزی‌ها برای بازداشتن پیشروی عثمانی در موره و اژه، با فرمانروایان قرامان و آق‌قویونلو متحد شدند و جنگ را در 1463 آغاز کردند. این راهبرد محاصره که با اوزون حسن در شرق، ونیز در غرب و قرامان در میان شکل گرفته بود، فاتح را واداشت که همزمان در چند جبهه بجنگد. نبرد شانزده‌ساله که همه عملیات بزرگ دوران، از اوتلوک‌بلی تا لشکرکشی‌های آلبانی را دربر گرفت، تنها با پیمان استانبول 1479 پایان خواهد یافت.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["فتح بخش بزرگ هرزگوین: تربینیه و موستار", "f54c0100"], "d": ["سرزمین‌های دوک هرزگوین، استیپان ووکچیچ-کوساچا، که ادارهٔ جداگانه‌ای از بوسنی برپا کرده بود، سه سال پس از فروپاشی پادشاهی بوسنی تا حد زیادی به اداره عثمانی گذشت: تربینیه در جنوب در 1466 «همراه با تقریباً سراسر ناحیه هرزگوین» گرفته شد. موستار که پیرامون دو قلعه کوچک پل نرتوا شکل گرفته بود نیز باید اندکی پیش از فتح بلاگای، مرکز هرزگوین، در 1466-1468 گرفته شده باشد؛ در دفتر تحریر اجمالی بوسنی به سال‌های 1468-1469 با نام «کوپرولو حصار» ثبت است. فتح هرزگوین با قلعه‌های باقی‌مانده دوک‌نشین در 1483 تمام شد.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["لشکرکشی دوم آلبانی — یورش شخصی فاتح بر اسکندر بیگ", "9cdd2bfa"], "d": ["سلطان محمد فاتح برای درهم شکستن مقاومت بیش از ربع سده اسکندر بیگ، در 1466-1467 لشکرکشی‌های بزرگی سامان داد که شخصاً فرماندهی می‌کرد. سپاه عثمانی آق‌حصار را محاصره کرد و برای نظارت بر منطقه قلعه ایلبسان (الباسان) را ساخت. این لشکرکشی کمر مقاومت آلبانیایی را شکست، اما نتوانست قلعه را فرو اندازد؛ فرمانبری کامل منطقه تا ده سال پس از مرگ اسکندر بیگ طول می‌کشید.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["پیش‌قراولان آق‌قویونلو قلعهٔ بینگول را از قره‌قویونلوها گرفتند", "51b94cbc"], "d": ["در هفته‌های پایانی لشکرکشی جهانشاه علیه اوزون حسن، پیش‌قراولان آق‌قویونلو قلعهٔ بینگول را تصرف کردند؛ با کشته شدن جهانشاه در 10 نوامبر 1467 سلطهٔ قره‌قویونلو در منطقه پایان یافت.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["فروپاشی دولت قره‌قویونلو: کشته شدن جهانشاه", "30bc6358"], "d": ["جهانشاه، فرمانروای قره‌قویونلو، هنگام بازگشت از لشکرکشی علیه اوزون حسن که زمستان سخت آن را ناکام گذاشته بود، مورد شبیخون قرار گرفت و میان بینگول و کیغی در حال گریز کشته شد. پس از این ضربه دولت سامان نیافت؛ واپسین فرمانروا حسنعلی در 1469 به دست اوغورلو محمد، پسر اوزون حسن، اسیر و کشته شد. فرمانروایی قره‌قویونلو که نزدیک به یک سده در آناتولی شرقی، آذربایجان و عراق ادامه داشت، بدین‌سان به آق‌قویونلوها رسید.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["مرگ اسکندر بیگ — خاموشی مقاومت آلبانیایی", "9158c35f"], "d": ["اسکندر بیگ که در دربار عثمانی پرورش یافته بود و در 1444 پس از شکست ایزلادی شورید و بیش از ربع سده در آلبانی ایستادگی کرد، در لژه که بدان پناه برده بود درگذشت. این مقاومت که در دوران مراد دوم و فاتح بارها سپاهیان عثمانی را سرگرم کرده بود، با مرگ او رهبری مرکزی خود را از دست داد. با فروپاشی جبهه آلبانی که پاپ و ونیز پشتیبان آن بودند، عثمانی‌ها در ده سال آق‌حصار و اشکودره را گرفتند و منطقه را برای همیشه به سرزمین خود افزودند.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["اداره عثمانی در قیصریه برقرار شد: گدیک احمد پاشا قرامان‌اوغولاری را پایان داد", "33cf35fc"], "d": ["با پایان دادن گدیک احمد پاشا به قرامان‌اوغولاری در 1474، قیصریه به اداره عثمانی درآمد؛ این شهر در سدهٔ 15 میان دولقادیروغولاری، رمضان‌اوغولاری و قرامان‌اوغولاری دست‌به‌دست شده بود. با اداره عثمانی قیصریه مرکز سنجق بیلربیگی قرامان شد.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["ساموس رها شد: مالکیت جنوایی (مائونا) پایان یافت", "5bdc380c"], "d": ["بر پایهٔ TDV جزیره پس از 1475 رها شد؛ در 1479 سلطان محمد فاتح جزیره را فتح کرد و قلعه‌ای ساخت.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["شکست راکووا (وسلوی) در مولداوی", "a1a74bf7"], "d": ["استفان بزرگ، وویودای مولداوی، نیروهای عثمانی به فرماندهی خادم سلیمان پاشا، بیلربیگی روم‌ایلی، را به زمین باتلاقی کشاند و به شکستی سنگین دچار کرد. این شکست که از سنگین‌ترین شکست‌های زمینی دوران فاتح بود در اروپا طنین بزرگی یافت و برای استفان در جهان صلیبی آوازه آورد. پادشاه سال بعد برای انتقام شخصاً لشکر خواهد کشید.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["پیروزی آق‌دره (والیا آلبا) — لشکرکشی مولداوی", "45a66791"], "d": ["سلطان محمد فاتح که برای انتقام شکست راکووا در یک سال پیش شخصاً لشکر کشیده بود، سپاه عثمانی را بر نیروهای مولداوی در جایی به نام آق‌دره به پیروزی بزرگی رساند و وارد سوچاوا، مرکز بیگ‌نشین، شد. اما قلعه‌ها گرفته نشد؛ به سبب کمبود آذوقه، طاعونی که در میان ینی‌چریان پیدا شد و تدارکات مجارها، سپاه ناگزیر عقب نشست. بستگی قطعی مولداوی تنها در سال‌های پس از آن و با گرفته شدن کیلیا و آق‌کرمان در 1484 تأمین خواهد شد.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["فتح آق‌حصار (کروویا) و تکمیل آلبانی", "559a79b4"], "d": ["ده سال پس از مرگ اسکندر بیگ، در 1478 با گرفتن آق‌حصار، دریواستو، لژه و ژابیاک فتح آلبانی تا حد زیادی تکمیل شد. سقوط قلعه کروویا که سال‌ها در برابر سپاهیان عثمانی ایستاده بود و نماد مقاومت اسکندر بیگ شمرده می‌شد، پایان ائتلاف ونیزی-آلبانیایی در منطقه را معنا می‌داد. اشکودره باقی‌مانده نیز با پیمان استانبول که سال بعد امضا می‌شد به عثمانی واگذار خواهد شد.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["پیوستن شبه‌جزیره تامان", "4ef917b8"], "d": ["پس از گرفته شدن کفه و کرچ در 1475، ناوگانی که سلطان محمد فاتح به سواحل قفقاز فرستاد، همراه با آناپا و کوپا ماتریگای جنوایی (تاماتارخان) در شبه‌جزیره تامان را گرفت. بدین‌سان هر دو کرانه تنگه زیر نظارت درآمد و ورود به دریای آزوف یکسره در دست عثمانی افتاد. تامان به‌عنوان دروازه گشوده به قفقاز شمالی به سنجق کفه پیوست.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["ورود ساموس به اداره عثمانی (فاتح)", "c877bc14"], "d": ["سلطان محمد فاتح ساموس را فتح کرد، قلعه‌ای ساخت و سرشماری را از نو سامان داد؛ قلعه به دست بایزید دوم در 1483 به دلایل سیاسی ویران شد.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["ناکامی محاصره رودس", "35a85c28"], "d": ["ناوگان 160‌پاره‌ای به فرماندهی مسیح پاشا به فرمان سلطان محمد فاتح در بهار 885 (1480) رودس را محاصره کرد و جزیره سه ماه در محاصره ماند. شوالیه‌های سن‌ژان به رهبری استاد اعظم پی‌یر دوبوسون با وجود تلفات سنگین سخت ایستادگی کردند؛ با دفع آخرین یورش بزرگ در 20 جمادی‌الاول 885 ناوگان در 3 اوت عقب نشست. پس از این ناکامی باروهای شهر از بنیاد نو شد و به نیرومندترین دژ اروپا بدل گردید و جزیره تنها در 1522 به دست سلیمان قانونی گرفته شد.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["ایکاریا به اداره شوالیه‌های سن ژان در رودس درآمد", "5cbc2669"], "d": ["ایکاریا، میان ساموس و خیوس، از 1481 تا 1521 در اداره شوالیه‌های سن ژان در رودس بود.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["نبرد ینی‌شهر — شکست جم سلطان", "c35abee2"], "d": ["دو برادری که پس از مرگ فاتح برای تخت وارد عمل شده بودند در دشت ینی‌شهر رودررو شدند و جم سلطان شکست قطعی خورد. شاهزاده‌ای که هجده روز در بورسا فرمان رانده و به نام خود خطبه خوانده بود، پس از شکست ناگزیر نخست به قونیه و از آنجا به سرزمین ممالیک پناه برد. ینی‌شهر دیرپاترین بحران دودمانی تاریخ عثمانی را آغاز کرد: مسئله جم چهارده سال سیاست خارجی عثمانی را در برابر اروپا فلج خواهد کرد.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["الحاق هرزگوین", "bf247891"], "d": ["پس از فتح بوسنی در 1463، سرزمین‌های دوک‌نشین هرزگوین که برجای مانده بود گام‌به‌گام به اداره عثمانی گذشت: تربینیه و موستار در 1466 گرفته شد، سنجق هرزگوین در 1470 تشکیل شد و واپسین سرزمین‌های دوک‌نشین در ساحل آدریاتیک نیز همراه با هرسگ‌نووی (هرتسگ نووی) در آغاز 1482 فتح و به سنجق افزوده شده بود. بدین‌سان منطقه کوهستانی پشت آدریاتیک یکسره از آنِ عثمانی شد و بوسنی و هرزگوین به یک جغرافیای اداری بدل گردید. پسر واپسین دوک که به دربار عثمانی درآمد، هرسک‌زاده احمد پاشاست که بعدها تا صدراعظمی بالا خواهد رفت.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["واگذاری زاکینتوس (زاکلیسه) به ونیز در برابر باج سالانه", "268a691a"], "d": ["زاکینتوس که در پایان دوران فاتح از خاندان توکو در میان جزایر ایونی گرفته شده بود، در جست‌وجوی آرامش در غرب از سوی پادشاه تازه که درگیر مسئله جم سلطان بود به ونیز واگذاشته شد. جزیره به اداره‌ای ونیزی سپرده شد که حاکمیت عثمانی را می‌شناخت و سالانه پانصد دوکا باج می‌پرداخت. بدین‌سان اداره مستقیم عثمانی در دریای ایونی تنها در آیامورا ماند.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["پناه بردن جم سلطان به رودس", "2228d6da"], "d": ["جم سلطان که کوشش برای محاصره قونیه نیز ناکام ماند، با حدود سی تن از مردانش از آناتولی گریخت و به رودس رسید و شوالیه‌های سن‌ژان با تشریفات از او پذیرایی کردند. اما میهمانی به زودی به اسارت بدل شد؛ شاهزاده نخست به فرانسه و سپس به پاپ سپرده شد و در دست سیاست اروپا به مهره‌ای بدل گشت. بایزید دوم ناگزیر در برابر نگه داشتن برادرش سالانه پول می‌پرداخت و اقدام‌های نظامی عثمانی علیه غرب تا مرگ جم متوقف ماند.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["آغاز جنگ عثمانی و ممالیک (جبهه چوکوروا)", "3fe3f0c7"], "d": ["کشمکش نفوذ بر دولکادیرلی‌ها و دشمنی‌ای که پناه بردن جم سلطان به سرزمین ممالیک برجا گذاشته بود، در 1485 جنگی را میان دو قدرت بزرگ سنی آغاز کرد که شش سال می‌کشید. در درگیری‌های پیرامون آدانه و طرسوس در چوکوروا، طرفین نتوانستند بر یکدیگر برتری یابند؛ سپاهیان عثمانی چند ضربه سنگین خوردند. این جنگ نخستین مرحله شکاف در روابط عثمانی و ممالیک است و آغاز روندی که سی سال بعد با لشکرکشی‌های مرج دابق و ریدانیه یاووز پایان خواهد یافت.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["صلح عثمانی و ممالیک — میانجی‌گری تونس", "60dd6719"], "d": ["در جنگ عثمانی و ممالیک که در 1485 آغاز شده بود، طرفین نتوانستند پیروزی قطعی به دست آورند؛ با میانجی‌گری عثمان حفصی، فرمانروای تونس، در 1491 توافق شد. پیمان مرزها را تا حد زیادی به حالت پیش از جنگ بازگرداند و تسویه‌حساب میان دو دولت اسلامی یک نسل به تأخیر افتاد. مبارزه فرساینده شش‌ساله از دلایل اصلی سیاست خارجی محتاط بایزید دوم و تمرکز او بر سامان‌دهی درونی به جای روی آوردن به شرق است.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["پذیرش یهودیان سفاردی رانده‌شده از اسپانیا در عثمانی", "5c2b5c24"], "d": ["پس از سقوط غرناطه، بخشی از یهودیانی که از ستم تفتیش عقاید در اسپانیا گریخته بودند به سرزمین‌های عثمانی پناه بردند و در شهرهای گوناگون جا داده شدند. این جماعت‌های سفاردی در اداره عثمانی به آزادی‌ای دست یافتند که تا آن روز ندیده بودند: سکونت در جای دلخواه، زیستن بر اساس باورشان، گشودن نهادهای آموزشی و ساختن کنیسه‌های نو. این مهاجرت که با دانش چاپ، پزشکی و مالی آنان اقتصاد سالونیک و استانبول را دگرگون کرد، پرگفتگوترین نمونه نظم مدارای عثمانی در اروپا شد.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["مرگ جم سلطان — پایان چهارده سال گروگانی", "f6588b70"], "d": ["جم سلطان که از پاپ به شارل هشتم، پادشاه فرانسه، سپرده شده بود، پس از آنکه در 27 ژانویه 1495 از رم راه افتاد، در جایی به نام کاستل کاپوآنا مرد؛ منابع یادآور می‌شوند که شاید محافل پاپی او را مسموم کرده بودند. مرگ شاهزاده‌ای که چهارده سال در دست دولت‌های اروپایی به‌عنوان برگ تهدید علیه عثمانی نگه داشته شده بود، سرانجام دست بایزید دوم را باز گذاشت. به‌راستی پادشاه از آن پس به ونیز اعلان جنگ خواهد کرد و ناوگانش را به نخستین پیروزی بزرگ خواهد رساند.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["پیروزی دریایی ساپینتسا (زونکیو) — نخستین موفقیت بزرگ ناوگان در مدیترانه", "9754aaef"], "d": ["بایزید دوم که با پایان یافتن مسئله جم دستش باز شده بود، در 1499 به ونیز اعلان جنگ کرد؛ ناوگان عثمانی در دریای ساپینتسا (زونکیو) ناوگان ونیز را شکست داد و نخستین پیروزی دریایی بزرگ را در مدیترانه به دست آورد. ناوگان با این پیروزی اعلام کرد که اکنون می‌تواند در دریا در برابر ونیز بایستد.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["از دست رفتن کفالونیا و ایتاکا", "60f0f687"], "d": ["ونیز که با گرفته شدن مودون و کورون لرزیده بود، با اسپانیا یکی شد و به ضدحمله دست زد و کفالونیا را که از 1479 در دست عثمانی بود محاصره کرد. پس از ایستادگی چهل و هفت‌روزه قلعه افتاد، جزیره همراه ایتاکا به ونیز رسید و سیصد سال به اداره عثمانی بازنگشت. این زیان توازنی پدید آورد که آنچه در موره به دست آمده بود در ایونی بازگردانده می‌شد.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["فروپاشی خان‌نشین اردوی زرین و برآمدن کریمه", "0d1dc515"], "d": ["واپسین فرمانروا شیخ احمد خان (1481-1502) نتوانست سرزمین خود را از بحرانی که در آن افتاده بود برهاند و خان‌نشین اردوی زرین در 1502 با ضربه منگلی‌گرای، خان کریمه، از صحنه تاریخ رفت. در پی کشمکش‌های تاج‌وتخت و تکه‌تکه شدن، در سرزمین‌های پیشین اردوی زرین خان‌نشین‌های کریمه، قازان، نوغای، آستراخان و سیبری پدید آمد. این پیروزی کریمه که زیر حمایت عثمانی بود نفوذ عثمانی را در شمال دریای سیاه بی‌چون‌وچرا کرد، اما خلأ پدیدآمده در منطقه را مسکو در سده بعد پر خواهد کرد.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["پایان جنگ عثمانی و ونیز و صلح", "125b1526"], "d": ["جنگی که در 1499 آغاز شد و با از دست رفتن ساپینتسا، لپانتو، مودون و کورون ونیز را به لرزه درآورد، در 1502 با صلح پایان یافت. ونیز با از دست دادن مهم‌ترین پایگاه‌هایش در موره، ناگزیر شد برتری عثمانی را بپذیرد و در برابر آن امتیازهای بازرگانی خود را در مدیترانه شرقی نگه دارد. سلطنت بایزید دوم که محتاط شمرده می‌شود، با این جنگ عثمانی را نخستین بار به جایگاه یک نیروی دریایی جدی در مدیترانه رساند.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["شورش شاه‌قولو — قیام قزلباش از ناحیه تکه تا سیواس", "3beadca7"], "d": ["شاه‌قولو بابا تکه‌لی که در 1510 با تأثیر تبلیغات صفوی در آناتولی شورش خود را آشکار کرد، در مارس 1511 بازار آنتالیا را زیر و رو کرده و در آوریل در کوتاهیه و پیرامون آن نیروهای عثمانی را شکست داده بود. در واپسین درگیری‌اش با صدراعظم خادم علی‌پاشا در نزدیکی سیواس هر دو سو تلفات سنگین دادند؛ هم صدراعظم و هم رهبر شورش کشته شدند. این قیام که اقتدار دولت را در آناتولی لرزاند، خلأ قدرت سال‌های پایانی بایزید دوم را آشکار کرد و نیرومندترین دستاویز یورش شاهزاده سلیم به تخت شد.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["کناره‌گیری بایزید دوم و جلوس یاووز سلطان سلیم", "c4cfab69"], "d": ["بایزید دوم با فشار شاهزاده سلیم که در کشمکش تاج‌وتخت با برادرانش پشتیبانی ینی‌چریان را پشت سر داشت، در 24 آوریل 1512 از تخت کناره گرفت و سلیم یکم همان روز به‌عنوان نهمین فرمانروای عثمانی بر تخت نشست. پادشاه سالخورده هنگام رفتن به دیمتوکا، زادگاهش، در راه، در روستای آبالار نزدیک چورلو، در 25 ربیع‌الاول 918 (10 ژوئن 1512) درگذشت. جای سلطنتی سی و یک‌ساله، محتاط و درون‌گرا را دوران یاووز گرفت که در هشت سال مرزهای امپراتوری را دو برابر خواهد کرد.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["فتح قلعه سین", "83271ea5"], "d": ["نیروهای آکنجی عثمانی در مرز بوسنی قلعه سین را که به درون دالماسیا کشیده می‌شد از پادشاهی مجارستان گرفتند. این حلقه‌ای آغازین از خط مرزی دالماسیا بود که نه سال بعد با فتح کنین و پیرامونش به دست غازی خسرو بیگ گسترش می‌یافت؛ قلعه در 1686 به ونیز از دست خواهد رفت.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["نبرد ینی‌شهر و برکنار شدن شاهزاده احمد", "e2ed15dd"], "d": ["یاووز سلطان سلیم برادر بزرگ‌تر خود شاهزاده احمد، نیرومندترین رقیب تخت، را در دشت ینی‌شهر نزدیک بورسا شکست داد و با اسیر کردنش از میان برداشت. بدین‌سان کشمکش برادران که از 1511 ادامه داشت بسته شد و شکاف درونی در آناتولی پایان یافت. سلیم با پشت‌گرمی آزادی روی آوردن به مسئله صفویان را به دست آورد.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["ورود یاووز سلطان سلیم به تبریز", "dad2e227"], "d": ["پس از پیروزی چالدران سپاه عثمانی وارد تبریز، پایتخت صفویان، شد و در شهر به نام پادشاه خطبه خوانده شد. سلیم یک هفته آنجا ماند و بخشی از هنرمندان و علمای تبریزی را به استانبول کوچاند؛ این انتقال بر هنر درباری عثمانی به‌شدت اثر خواهد گذاشت. هرچند با نزدیک شدن زمستان و نارضایتی ینی‌چریان شهر ترک شد، برتری صفویان در شرق شکسته شده بود. جاهایی که امروز بر نقشه به عثمانی می‌پیوندند به هم چسبیده نیستند و این درست است: تبریز اشغال نظامی نه‌روزه است؛ دشت ارزنجان در جریان لشکرکشی بی‌جنگ تسلیم شده و قلعه کماخ در میان آن تا 19 مه 1515 نزد صفویان پایداری کرده است؛ سعرد را خلیل بیگ، ملک حسن‌کیف، که در تبریز از زندان شاه اسماعیل رها شده بود، با فرمانبری از عثمانی از صفویان بازپس گرفته است — دیاربکر پیرامون آن تا 1515 و حسن‌کیف تا 1517 صفوی ماند.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["موش و بینگول (چاپاقچور) از صفویان به اداره عثمانی درآمد", "b0a53b5a"], "d": ["با گرفتن آناتولی شرقی از صفویان پس از چالدران، موش در 921/1515 به اداره عثمانی درآمد؛ چاپاقچور (بینگول) همسایه در همین فرایند به عثمانی پیوست.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["فتح قلعه کماخ از صفویان", "73fd8671"], "d": ["یاووز سلطان سلیم که پس از بازگشت از چالدران زمستان را در آماسیه گذراند، فتح قلعه مستحکم کماخ را که گذرگاه فرات را در دست داشت به بیقلی محمد پاشا سپرد. پس از محاصره‌ای که پادشاه شخصاً در آن شرکت کرد، قلعه از دست صفویان گرفته شد و دروازه آناتولی شرقی گشوده گشت. این فتح نخستین گام عینی در تبدیل پیروزی چالدران به دستاوردی سرزمینی پایدار است.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["پیروزی تورنا‌داغ — بیگ‌نشین دولکادیر تابع عثمانی شد", "fd879145"], "d": ["نیروهای عثمانی، بیگ دولکادیر علاءالدوله بوزقورت را که در جریان لشکرکشی چالدران موضعی دوپهلو گرفته بود، در جایی به نام اردکلی میان گوکسون و آندرین شکست دادند؛ علاءالدوله در این نبرد کشته شد. بیگ‌نشین در این تاریخ الحاق نشد: پس از علاءالدوله، شهسوارااوغلو علی بیگ از سوی یاووز سلطان سلیم بر سر دولکادیراوغولاری گماشته شد و سرزمین با مرکزیت مرعش-البستان همچون بیگ‌نشینی تابع عثمانی ادامه یافت. حائل کنار مرز ممالیک بدین‌سان زیر نظارت عثمانی درآمد و راه لشکرکشی مصر دو سال بعد گشوده شد؛ الحاق پس از کشته شدن علی بیگ انجام خواهد شد.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["فتح آمد (دیاربکر) و بنیان‌گذاری بیلربیگی دیاربکر", "a6867d5b"], "d": ["پس از آنکه ادریس بدلیسی بیگ‌های سنی کرد منطقه را به عثمانی پیوند داد، نیروهای صفوی تاب محاصره‌ای دراز را نیاوردند و کلیدهای آمد به بیقلی محمد پاشا تسلیم شد. شهر مرکز بیلربیگی نوبنیاد دیاربکر شد. بدین‌سان هسته اداری بین‌النهرین علیا به دست عثمانی افتاد.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["فتح خارپوت — گشوده شدن راه دیاربکر", "564eb269"], "d": ["حسرو پاشا، بیلربیگی قرامان، که برای رهانیدن دیاربکر گرفته‌شده پس از چالدران از محاصره صفوی راه افتاده بود، قلعه خارپوت را که پیرامونش را پیشتر چرکس حسین بیگ گرفته بود، پس از سه روز محاصره گرفت. راه شرق فرات تا دیاربکر بدین‌سان ایمن شد.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["نبرد کوچ‌حصار (قزل‌تپه) — شکست قره‌خان", "9ea9e843"], "d": ["سپاه عثمانی به فرماندهی بیقلی محمد پاشا، والی صفوی قره‌خان را در نزدیکی کوچ‌حصار، در جایی به نام قوروق در صحرای ده‌قارکین، در نبردی رویاروی که یک روز تمام کشید، شکست داد؛ سر بریده قره‌خان به اردوگاه پادشاه فرستاده شد. سپس نیروهای عثمانی هرچند وارد شهر ماردین شدند، چند روز ماندند و رفتند؛ قلعه ماردین که نگهبانان صفوی نگه داشته بودند تنها یک سال بعد تسلیم گرفته شد. این پیروزی مرز جنوبی یاووز را ایمن کرد و روی آوردن او به لشکرکشی مصر را ممکن ساخت. جاهای دیگری که در همین تاریخ پیوستند: پالو، چمیشگزک، سیورک.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["حرکت یاووز سلطان سلیم از استانبول برای لشکرکشی مصر", "ac258b4b"], "d": ["یاووز سلطان سلیم در ظاهر با تدارک لشکرکشی تازه‌ای به شرق علیه صفویان از استانبول حرکت کرد و از راه آق‌شهر رو به جنوب نهاد. تماس گرفتن سلطان ممالیک قانصوه غوری با شاه اسماعیل و تهدید جناح شرقی عثمانی، هدف را به‌زودی دگرگون خواهد کرد. این لشکرکشی آغاز عملیات بزرگی است که دو سال خواهد کشید و عثمانی را به امپراتوری خاورمیانه بدل خواهد کرد.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["گرفتن زبید: نخستین ورود دریانوردان عثمانی به دریای سرخ", "38740e0c"], "d": ["حسین بیگ و سلمان ریس، دریانوردان عثمانی‌تبار که در برابر فشار پرتغال در اقیانوس هند به درخواست سلطان ممالیک قانصوه غوری به دریای سرخ فرستاده شده بودند، با ناوگان خود زبید را گرفتند. این عملیات که هنوز در خدمت ممالیک انجام می‌شد، نخستین حضور بالفعل نیروی دریایی عثمانی در خط دریای سرخ-هند است. یک سال بعد که مصر به عثمانی گذشت، همین ناوگان مستقیماً به استانبول وابسته خواهد شد.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["اعلان رسمی هدف لشکرکشی: ممالیک و حلب", "689e310d"], "d": ["یاووز سلطان سلیم پس از آنکه قانصوه غوری با صفویان توافق کرد و سپاهش را به سوی حلب راند، هدف لشکرکشی را آشکارا سلطان ممالیک و حلب اعلام کرد. بدین‌سان رقابت پنهانی میان دو دولت سنی که سال‌ها ادامه داشت به جنگ آشکار بدل شد. این اعلان شمارش معکوس چهارهفته‌ای را به سوی مرج دابق آغاز کرده است.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["ناکامی محاصره عدن: نخستین کوشش دریای سرخ علیه پرتغال", "8ffd46f2"], "d": ["سلمان ریس و حسین بیگ برای گرفتن عدن، دروازه دریای سرخ که به اقیانوس هند باز می‌شود، هشت روز محاصره کردند، اما در برابر استحکامات نیرومند شهر ناگزیر عقب نشستند. گرفته نشدن عدن راهبرد جنوبی علیه پرتغال را سال‌ها مختل خواهد کرد. این کوشش نخستین آزمون عثمانی در سیاست اقیانوسی است.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["پیوستن بیگ‌نشین رمضان‌اوغولاری به عثمانی", "cfaa3754"], "d": ["پس از پیروزی مرج دابق و در جریان واگذاری‌ها، بیگ‌نشین رمضان‌اوغولاری با مرکزیت آدانه به محمود بیگ داده شد و زیر فرمانروایی عثمانی درآمد. این بیگ‌نشین که از فرمانبری ممالیک بیرون آمده بود، به‌جای برچیده شدن با وضعیت «اوجاقلیق» به خاندان واگذار شد؛ رمضان‌اوغولاری اداره چوکوروا را با عنوان سنجق‌بیگی عثمانی ادامه دادند. این نظم ممتاز تا 1608، سالی که پیر منصور بیگ‌نشین را رها کرد، ادامه یافت. جاهای دیگری که در همین تاریخ پیوستند: ملاطیه، طرسوس، موصل، عینتاب.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["درآمدن حلب، رقه و دیرالزور به فرمانروایی عثمانی", "2088eb6a"], "d": ["چهار روز پس از مرج دابق یاووز سلطان سلیم بی‌آنکه با مقاومتی روبه‌رو شود وارد حلب شد و در مساجد شهر به نام او خطبه خوانده شد. این‌که حلب، پایتخت بازرگانی و اداری سوریه، چنین زود فرو افتاد نشان می‌دهد اقتدار ممالیک در منطقه فروپاشیده بود. گرفتن شهر راه دمشق و از آنجا مصر را در دم گشود. جاهای دیگری که در همین تاریخ پیوستند: انطاکیه، رقه، دیرالزور.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["دیدار با خلیفه عباسی متوکل سوم در گوک‌میدان حلب", "22979f42"], "d": ["متوکل سوم، خلیفه عباسی قاهره، که در مرج دابق همراه سپاه ممالیک اسیر شده بود، در گوک‌میدان حلب به حضور پادشاه آورده شد و یاووز سلطان سلیم احترام بسیار به او نمود. خلافت قاهره که از 1261 در سایه سلاطین ممالیک مقامی نمادین بود، با این دیدار عملاً زیر حمایت عثمانی رفت. خلیفه بعدها همراه پادشاه به استانبول برده خواهد شد.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["درآمدن طرابلس شام و حماه به اداره عثمانی", "a1e19a79"], "d": ["پس از حلب و حماه، طرابلس شام در ساحل سوریه نیز بی‌مقاومت به اداره عثمانی درآمد. این شهر که از پررفت‌وآمدترین بنادر مدیترانه شرقی بود، دروازه گشوده شام به دریا و مرکز بازرگانی ابریشم و شکر بود. با گرفتن آن، نوار ساحلی بلاد شام یکسره دست‌به‌دست شد.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["درآمدن شام (دمشق) به فرمانروایی عثمانی", "2b844d91"], "d": ["یاووز سلطان سلیم که با تسلیم حماه و حمص پس از حلب راهش گشوده شده بود، در 27 سپتامبر به پای دمشق رسید؛ بی‌درنگ وارد شهر نشد و در بیرون، در جایی به نام مسطبه، خرگاه برپا کرد و در دوازدهمین روز ورودش با مراسم بزرگی درون شد. در دمشق مدتی دراز ماند، نظم اداری سوریه را برقرار ساخت و آرامگاه محیی‌الدین ابن عربی را ساخت. بدین‌سان همه بلاد شام از فرمانروایی ممالیک بیرون آمد. جاهای دیگری که در همین تاریخ پیوستند: بیروت.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["اعلام توم‌ان‌بای به‌عنوان سلطان ممالیک در قاهره", "6020d90d"], "d": ["پس از مرگ قانصوه غوری در مرج دابق، امیران ممالیک توم‌ان‌بای را که واپسین سلطان دولت خواهد بود بر تخت نشاندند. سلطان تازه که چرکس‌تبار بود دولتی را وارث شد که سوریه را از دست داده بود، خزانه‌اش تهی بود و سلاح گرم نداشت. با این همه، با برپا کردن خط دفاعی در پای قاهره واپسین مقاومت را در برابر پیشروی عثمانی سازمان خواهد داد.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["نبرد غزه (خان یونس): شکست جانبردی غزالی", "9f1eb8cb"], "d": ["یاووز سلطان سلیم صدراعظم خادم سنان پاشا را با نیروی پیشرو چهار هزار نفره به غزه فرستاد. جانبردی غزالی که توم‌ان‌بای او را به نایب‌السلطنگی شام گمارده بود، هرچند کوشید پیشروی عثمانی را در خط غزه-خان یونس بازدارد، به شکستی سنگین دچار شد و به مصر گریخت. با پراکنده شدن واپسین نیروی حائل ممالیک در فلسطین، راه صحرای سینا یکسره گشوده شد.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["شرق رود اردن: درآمدن عمان به اداره عثمانی", "9db62667"], "d": ["پس از نبرد غزه، هنگامی که نیروهای عثمانی برای لشکرکشی به مصر آماده شده و به جنوب فرود می‌آمدند، عمان در شرق رود اردن نیز به اداره عثمانی درآمد. شهرهای ساحلی و درونی فلسطین (یافا، نابلس، صیدا، عکا، قدس) پس از مرج دابق، در پاییز 1516 پیشتر دست‌به‌دست شده بودند. این شهرها چهار سده به‌عنوان سنجق‌های ایالت شام اداره شدند.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["ورود یاووز سلطان سلیم به قدس", "66d7bfad"], "d": ["یاووز سلطان سلیم پس از نبرد غزه همراه بزرگان دولت و سپاه به قدس آمد که پس از مرج دابق بی‌مقاومت به اداره عثمانی گذشته بود. پادشاه با دیدار از قبةالصخره و مسجدالاقصی منزلت مقدس شهر را تأیید کرد. قدس از این تاریخ تا دسامبر 1917، تمام چهار سده، در اداره عثمانی خواهد ماند.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["ورود یاووز سلطان سلیم به غزه و روی آوردنش به صحرای سینا", "2106bfc7"], "d": ["پس از شکست جانبردی غزالی در خان یونس (21 دسامبر 1516)، غزه در دست نیروی پیشرو بود. پادشاه در 2 ژانویه 1517 وارد غزه شد، با سنان پاشا که در رأس نیروی پیشرو بود دیدار کرد و سپاه آخرین تدارک‌های گذر به مصر را دید. در صحرای بی‌آب قطیه (سینا) که از غزه تا صالحیه کشیده می‌شود، هشت منزل راه پیموده و آب با شتر حمل خواهد شد. این گذر پرمخاطره‌ترین و از نظر پشتیبانی دشوارترین مرحله لشکرکشی است.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["گرفتن سوئز — دروازه گشوده به دریای سرخ", "05f3324e"], "d": ["پس از پیروزی ریدانیه و ورود سپاهیان عثمانی به قاهره، سوئز در شمالی‌ترین نقطه دریای سرخ نیز به اداره عثمانی درآمد. این کشتی‌سازی-بندر که ممالیک از آنجا ناوگان به اقیانوس هند می‌فرستادند، به پایگاه سیاست جنوبی علیه پرتغال بدل شد. سوئز دهانه شمالی راهی است که سه سده بعد کانال در آن گشوده خواهد شد.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["نخستین ورود نیروهای عثمانی به قاهره", "0a3f4f4d"], "d": ["روز پس از پیروزی ریدانیه به سپاهیان عثمانی اجازه ورود به قاهره داده شد و در 24 ژانویه نیروها در شهر جاگرفتند. اما این ورود به معنای کنترل کامل شهر نبود؛ توم‌ان‌بای به مصر علیا عقب نشسته بود و مقاومت ممالیک هنوز درهم نشکسته بود. فتح قاهره در یک روز نه، در جریانی خونین که چند هفته کشید به پایان خواهد رسید.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["شبیخون توم‌ان‌بای بر قاهره و سه روز نبرد خیابانی", "b83b6ce6"], "d": ["توم‌ان‌بای که به مصر علیا عقب نشسته بود، با حدود هفت هزار نفر همراهش در شب 27-28 ژانویه ناگهان وارد قاهره شد و در شهر مقاومت را آغاز کرد و نیروهای عثمانی را در وضعی بسیار دشوار گذاشت. در درگیری‌های سخت خیابانی که سه روز کشید، ممالیک بخش بزرگی از شهر را موقتاً در دست داشتند. مقاومت تنها با وارد عمل شدن توپخانه عثمانی و نیروهای کمکی درهم شکسته شد.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["درآمدن جانبردی غزالی به خدمت عثمانی", "a94ea459"], "d": ["جانبردی غزالی، امیر پیشین ممالیک که پس از ریدانیه به صالحیه عقب نشسته بود، به پادشاه رو آورد و زنهار خواست. یاووز سلطان سلیم که می‌اندیشید در برقراری آرامش در مصر و سوریه سودمند خواهد بود، او را به خدمت پذیرفت. این گزینش نخستین نمونه بزرگ سیاست عثمانی در وارد کردن کادرهای ممالیک به نظام به‌جای برچیدن آنان است.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["ورود باشکوه یاووز سلطان سلیم به قاهره و خواندن خطبه", "6d98080c"], "d": ["پس از سرکوب درگیری‌های خیابانی، پادشاه در 15 فوریه 1517 با مراسمی بسیار پرشکوه وارد قاهره شد و در مساجد به نام او خطبه خوانده شد. خوانده شدن خطبه در قاهره به نام سلطان عثمانی، اعلام پایان حقوقی فرمانروایی ممالیک است که از 1250 ادامه داشت. این تاریخ لحظه تکمیل نمادین فتح عملی مصر شمرده می‌شود.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["دستگیری توم‌ان‌بای، واپسین سلطان ممالیک، در ترّوجه", "7058e6ad"], "d": ["توم‌ان‌بای که پس از ترک قاهره در دلتای نیل پنهان شده بود، به دست بدویانی که پناهش داده بودند لو رفت و در ناحیه ترّوجه گرفتار شد. دستگیری او مرکز سازمان‌یافته مقاومت ممالیک را از میان برد. واپسین سلطان از آن پس چهارده روز در دست عثمانی نگه داشته خواهد شد.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["اعدام توم‌ان‌بای در باب‌زویله و پایان دولت ممالیک", "ad9820be"], "d": ["توم‌ان‌بای چهارده روز پس از دستگیری در باب‌زویله، دروازه نامدار قاهره، به دار آویخته شد؛ پیکرش بعدها در مدرسه‌ای که عمویش ساخته بود به خاک سپرده شد. بدین‌سان دولت ممالیک که از 1250 بر مصر و سوریه فرمان می‌راند رسماً از صحنه تاریخ رفت. با درهم شکستن مقاومت، شهرهای صعید (مصر علیا) مانند اسیوط و اسوان نیز به اداره عثمانی پیوست.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["حمله ناوگان پرتغال به جده و دفاع سلمان ریس", "52322cf5"], "d": ["ناوگان پرتغالی مرکب از حدود سی گالی و گالیون به جده حمله کرد؛ سلمان ریس دفاع شهر را رهبری کرد، از پیاده شدن دشمن جلوگیری نمود و چند کشتی پرتغالی را غرق کرد. این دفاع مانع افتادن بندر مکه و در نتیجه راه حج به دست یک دولت مسیحی شد. جده چند ماه بعد با بیعت حجاز رسماً در اداره عثمانی جای خواهد گرفت.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["تسلیم اسکندریه به ناوگان — تکمیل فتح مصر", "386878fe"], "d": ["درست چهار ماه پس از ریدانیه و سی و شش روز پس از اعدام توم‌ان‌بای، با رسیدن ناوگان عثمانی به فرماندهی جعفر بیگ به بندر، اسکندریه به اداره عثمانی گذشت؛ بنادر دلتا مانند رشید و دمیاط نیز در همین روند پیوسته شد. این‌که بندر بزرگ مصر بر مدیترانه ماه‌ها پس از سقوط قاهره و نه از خشکی بلکه از دریا تسلیم گرفته شد، آشکارا نشان می‌دهد فتح با یک نبرد بلکه منطقه‌به‌منطقه تکمیل شده است. اسکندریه از آن پس بندر حیاتی پیوند‌دهنده استانبول و قاهره خواهد شد. جاهای دیگری که در همین تاریخ پیوستند: رشید (روزتا).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["پیوستن حجاز بی‌جنگ: بیعت ابونمی، پسر شریف مکه", "c13b98c7"], "d": ["سلطان سلیم یاووز نخست اندیشیده بود برای گرفتن مکه و پیرامون آن سپاه بفرستد، اما با آگاهی از فرمانبری امیر مکه شریف برکات از این کار دست کشید. ابونمی، پسر دوازده‌ساله برکات، با هدایای پدر و کلیدهای مکه به قاهره آمد و به حضور پادشاه پذیرفته شد. بدین‌سان حجاز نه به‌عنوان پیامد خودکار ریدانیه، بلکه پنج ماه و نیم بعد و بی‌آنکه گلوله‌ای شلیک شود، با صلح و بیعت به عثمانی پیوست. سایر جاهایی که در همین تاریخ پیوستند: طائف. سایر سکونتگاه‌هایی که در همین تاریخ از دست رفتند: حرمه (خاور طائف)، رابغ، بدر.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["پذیرش عنوان «خادم الحرمین» و خطبه در مدینه", "63b32b59"], "d": ["یاووز سلطان سلیم پس از دومین پذیرش هیئت مکه، حمایت حرمین را رسماً برعهده گرفت و عنوان «خادم الحرمین الشریفین» را به کار برد. شریف برکات خلعتی را که برایش فرستاده شده بود پوشید و به نام پادشاه خطبه خواند؛ با رفتن هیئت مدینه نیز به استانبول، امارت برکات با برات تأیید شد. پادشاه با فرستادن دویست هزار سکه زر و آذوقه فراوان برای مردم حرمین، سنت صُرّه را که هر سال تکرار خواهد شد آغاز کرد. جاهای دیگری که در همین تاریخ پیوستند: ینبع، تبوک.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["درآمدن سلمان ریس به خدمت عثمانی و واگذاری سیاست دریای سرخ", "771da99a"], "d": ["سلمان ریس که جده را در برابر پرتغالی‌ها پاس داشته بود، به قاهره آمد و به حضور یاووز سلطان سلیم رسید؛ هرچند مدتی نگه داشته شد، در 1519 به استانبول فراخوانده شد و متعهد گردید برای مقابله با تهدید پرتغال سی گالی و چند کالیت آماده کند. این دیدار آغاز آن است که سیاست دریای سرخ و اقیانوس هند از میراث ممالیک گرفته و مستقیماً به استانبول پیوند داده شد. عثمانی اکنون افزون بر دولت مدیترانه‌ای بودن، نیرویی بود که سیاست اقیانوسی نیز دنبال می‌کرد.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["ترک قاهره به دست یاووز سلطان سلیم و بیلربیگی خایر بیگ", "8cd4fb23"], "d": ["یاووز سلطان سلیم که نزدیک به هشت ماه در مصر مانده و نظم اداری، مالی و نظامی را برپا کرده بود، از قاهره رفت؛ خایر بیگ، والی پیشین حلب که در مرج دابق جناح چپ را پس کشیده و شکست ممالیک را شتاب داده بود، به‌عنوان نخستین بیلربیگی عثمانی مصر اداره را از قلعةالجبل آغاز کرد. گزینش والی‌ای با پیشینه ممالیک سیاست گذار آگاهانه‌ای بود که اداره نو را برای مردم بومی بیگانه جلوه نمی‌داد. پادشاه در راه بازگشت واپسین خلیفه عباسی متوکل سوم و هنرمندان و عالمان برگزیده مصر را نیز با خود به استانبول برد.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["پایان خلافت عباسی قاهره — روایت «مراسم انتقال»", "1d357640"], "d": ["یاووز سلطان سلیم پس از تصرف مصر، واپسین خلیفه، متوکل علی‌الله سوم، را که در مرج دابق اسیر افتاده بود با خود به استانبول آورد؛ خلافت عباسی قاهره که از 1261 در سایه سلاطین ممالیک بی‌اختیار برجا مانده بود بدین‌سان پایان یافت. در برابر آن، روایت مشهور واگذاری خلافت به یاووز در مراسمی رسمی در ایاصوفیه نخستین بار در پایان سده هجدهم در اثر دوسون آمده و در هیچ‌یک از منابع روزگار یاووز یافت نمی‌شود. دایرة‌المعارف اسلام TDV چون منبع اصیلی که مراسم را مستند کند وجود ندارد روایت را ساختگی می‌شمارد؛ اما یادآور می‌شود که برای انتقال خلافت از نظر شرعی نیازی به چنین مراسمی نبوده است.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["ارزروم به اداره عثمانی پیوست — نفوذ صفوی در آناتولی شرقی شکسته شد", "78d1be02"], "d": ["هرچند پس از پیروزی چالدران (1514) نفوذ عثمانی در منطقه افزایش یافت، تصرف کامل ارزروم تا شکسته شدن نفوذ ایران به تأخیر افتاد؛ شهر تنها پس از لشکرکشی مصر در 1518-19 به اداره عثمانی پیوست. ارزروم در 1502 با برانداختن بیگ‌نشین آق‌قویونلو به دست شاه اسماعیل به فرمانروایی صفوی درآمده بود؛ این دوران شانزده‌ساله بدین‌سان بسته شد. در 1534 در لشکرکشی عراقین بیلربیگی ارزروم برپا خواهد شد. میان 1518-1519 اشکاله همراه با منطقه ارزروم به اداره عثمانی پیوست (روز تأیید نشده).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["آغاز شورش‌های جلالی: قیام شیخ جلال بوزوکلو", "99bd8a99"], "d": ["در ناحیه بوزوک کسی به نام شیخ جلال مهدویت خود را اعلام کرد و در پیرامون توقات شورید؛ شورش سرکوب شد، اما نامش یک سده بر همه جنبش‌های راهزنی و شورش در آناتولی نهاده شد. جلالی‌گری در پایان سده شانزدهم با از هم پاشیدن نظام تیمار و فشار جمعیتی درآمیخت و به درازمدت‌ترین مشکل امنیت داخلی امپراتوری بدل شد. شورش‌ها در آناتولی به کوچ‌های توده‌ای موسوم به «قاچگونلوق بزرگ» انجامید.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["پیوستن الجزایر به دولت عثمانی", "b8eba4c1"], "d": ["خیرالدین ریس که در شمال آفریقا در برابر فشار اسپانیا مقاومت می‌کرد، برای ایستادگی به استانبول روی آورد، الجزایر را به پادشاه عرضه کرد و خطبه به نام یاووز سلطان سلیم خوانده شد. بدین‌سان الجزایر رسماً به سرزمین‌های عثمانی پیوست و برای خیرالدین با عنوان بیلربیگی سپاه و توپ فرستاده شد. این پیوستن بنیاد سیادت دریایی عثمانی را در مدیترانه باختری نهاد که سده‌ها ادامه یافت. جاهای دیگری که در همین تاریخ پیوستند: قسنطینه، شرشال، مدیه (تیتری)، سطیف.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["درگذشت یاووز سلطان سلیم در چورلو", "9fe83744"], "d": ["سلیم یکم که در هشت سال خاک دولت را بیش از دو برابر کرده بود، در 18 ژوئیه 1520 برای لشکرکشی تازه‌ای از استانبول بیرون آمد؛ به سبب تومور بزرگی که بر پشتش پدید آمده بود از چورلو فراتر نتوانست رفت. با وجود دخالت پزشکان بیماری‌اش سخت‌تر شد و پس از دو ماه درمان بی‌امید، در 8-9 شوال 926 (21-22 سپتامبر 1520) همان‌جا درگذشت. او با چالدران، مرج دابق و ریدانیه ایران را متوقف کرده، دولت ممالیک را برچیده و خلافت و پشتیبانی حرمین را به عثمانی آورده بود. از خود تنها یک فرزند پسر بر جای گذاشت: سلیمان.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["درآمدن جزیره نیکاریا (ایکاریا) به اداره عثمانی", "6afa972b"], "d": ["نیکاریا میان ساموس و خیوس از 1481 تا 1521 زیر اداره شوالیه‌های سن‌ژان رودس بود؛ نخستین دوران عثمانی در جزیره در 1522 آغاز شد و تا 1822 ادامه یافت. در این دوران قائم‌مقام مسئول گرد آوردن و پرداخت مالیات‌ها بود؛ همچون دیگر جزایر اژه شورای محلی ریش‌سفیدان (دموگرونتیا) نیز به هستی خود ادامه داد و گاه با اداره عثمانی درگیر می‌شد.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["الحاق سرزمین دولکادیر — ایالت دولکادیر با مرکزیت مرعش", "595c3c30"], "d": ["سرزمین دولکادیر که پس از شکست تورنا‌داغ 1515 همچون بیگ‌نشینی تابع عثمانی ادامه داشت، پس از کشته شدن شهسوارااوغلو علی بیگ همراه فرزندانش در آرتوکووا مستقیماً به سرزمین‌های عثمانی پیوست و به ایالتی با مرکزیت مرعش بدل شد. ناحیه بوزوک بیگ‌نشین به‌عنوان سنجقی جداگانه به اداره عثمانی بسته شد. بدین‌سان دوران تقریباً دوسده‌ای دولکادیرلی در مرعش، البستان، گوکسون، گورون، زامانتی و درنده بسته شد؛ بیگ‌نشین حائل کنار مرز ممالیک یکسره از میان رفت.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["فتح کنین", "a46d3117"], "d": ["با یورش‌های غازی خسرو بیگ، سنجق‌بیگ بوسنی، در سال‌های 927-928 (1521-1522) رشته‌ای از قلعه‌های ونیز، با کنین، اسکرادین و اوستروویتسا در رأس، به اداره عثمانی گذشت؛ مرز به آن سوی رشته‌کوه دوم رانده شد. این زنجیره فتح بنیاد سنجق دالماسیا را نهاد که پانزده سال بعد با گرفته شدن کلیس تکمیل می‌شد.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["عقب‌نشینی شوالیه‌ها: واگذاری بدروم، استانکوی و دوازده جزیره", "ea01666e"], "d": ["بنا بر شرایط تسلیم رودس شوالیه‌های سن‌ژان نه تنها مرکز جزیره بلکه همه مواضعی را که دو سده در دست داشتند تخلیه کردند. قلعه بدروم (سن‌پیر) در ساحل آناتولی و جزایر اسپانکوی (کوس)، کالیمنوس و لروس بدین‌سان بی‌درگیری به اداره عثمانی رسید. با این واگذاری که دو هفته پس از سقوط رودس تکمیل شد، حضور لاتینی در گوشه جنوب‌خاوری اژه یکسره پایان یافت.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["شورش احمد پاشای خائن در مصر", "b18bb805"], "d": ["احمد پاشا که در انتظار صدراعظمی به والی‌گری مصر فرستاده شده بود، در قاهره خود را «الملک المنصور سلطان احمد» نامید و استقلال خود را اعلام کرد. شورش به‌زودی سرکوب و پاشا کشته شد، اما رویداد شکنندگی نظارت مرکز را در ثروتمندترین ایالت امپراتوری نشان داد. در پی آن ابراهیم پاشا به مصر رفت و قانون‌نامه معروف مصر را که اداره ایالت را از نو سامان می‌داد فراهم آورد.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["الحاق بوسنی شمالی: یایجه و بانالوکا", "8ec86cfa"], "d": ["پس از فروپاشی خط دفاعی مجار در پی موهاچ، غازی خسرو بیگ، سنجق‌بیگ بوسنی، به دره وربس لشکر کشید و واپسین قلعه‌های بوسنی را که در دست پادشاهی مجار مانده بود گرفت. با سقوط یایجه و بانالوکا ایالت بوسنی در شمال به رود ساوا رسید و جبهه کرواسی پدید آمد. بانالوکا زود به دومین مرکز ایالت بدل شد.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["گرفتن بودین و سپردن آن به زاپولیا", "fba4f89b"], "d": ["در راه لشکرکشی وین، سپاه عثمانی بودین را که به دست فردیناند افتاده بود محاصره کرد و بازپس گرفت و شهر را به یانوش سزاپولیای، پادشاه مجارستان زیر حمایت عثمانی، تسلیم کرد. بدین‌سان در رقابت هابسبورگ-عثمانی بر سر مجارستان الگوی پادشاهی دست‌نشانده حائل برپا شد. این نظم تا 1541 ادامه خواهد یافت و پس از مرگ زاپولیا بودین مستقیماً به ایالت عثمانی بدل خواهد شد.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["سلیمان قانونی به لشکرکشی آلمان برخاست — به میدان خواندن شارل پنجم", "7c3d7055"], "d": ["پس از نتیجه‌ندادن محاصره وین و محاصره دوباره بودین به دست فردیناند، پادشاه این بار برای کشاندن مستقیم امپراتور شارل پنجم به نبرد رویاروی از استانبول راه افتاد. سپاه در اوت با پایداری قلعه کوچک گونس معطل خواهد شد و چون امپراتور به جنگ بیرون نیامد، لشکرکشی به یورش‌ها محدود خواهد ماند. این لشکرکشی زمینه نخستین صلح سال بعد با هابسبورگ‌ها را فراهم کرد.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["لشکرکشی آلمان و محاصره گونس (کوشگ)", "8aec937a"], "d": ["قانونی برای وادار کردن شارل پنجم به نبرد رویاروی با سپاه خود به اتریش لشکر کشید؛ قلعه کوچک گونس بیست و پنج روز ایستادگی کرد و پیشروی سپاه را به تأخیر انداخت. چون امپراتور به جنگ بیرون نیامد، آکنجیان پیرامون وین را زدند و با پیشرفت فصل بازگشته شد. این لشکرکشی سود سرزمینی نداشت، اما هابسبورگ‌ها را به میز آورد و زمینه صلح سال بعد را فراهم ساخت.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["پیمان استانبول — نخستین صلح با هابسبورگ‌ها", "b085767a"], "d": ["پادشاه که فرستاده فردیناند، کورنلیوس، را پذیرفت به آتش‌بس رضایت داد و نخستین متن رسمی صلح میان عثمانی و اتریش پدید آمد. در این پیمان فردیناند در برابر سرزمین‌های مجارستان که در دست داشت پرداخت مالیات سالانه را پذیرفت و آرشیدوک اتریش در تشریفات همتای صدراعظم شمرده شد. این منزلت نابرابر بیان آشکار ادعای برتری دیپلماسی عثمانی در سده شانزدهم بود.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["گرفتن قارص و گشوده شدن مرز شمال‌خاوری", "742e3101"], "d": ["هنگامی که ستون پیشرو لشکرکشی عراقین از ارزروم به سوی خاور می‌رفت، قلعه قارص که در دست آتابگ‌نشین گرجی بود و از زمان تیمور ویران افتاده بود، بی‌مقاومت تسلیم گرفته شد. شهر چون گذرگاه میان قوس ارس و چیلدیر را در دست داشت کلید دروازه شمالی گشوده به ایران شمرده می‌شد. این دستاورد نخستین حلقه بیلربیگی قارص و خط قفقاز بود که سی سال بعد برپا می‌شد.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["نخستین ورود به تبریز — آغاز لشکرکشی عراقین", "cf7ed4e3"], "d": ["ابراهیم پاشا که با عنوان سردار اکرم پیشاپیش حرکت کرد، چون شاه طهماسب از نبرد رویاروی پرهیز کرد و به درون کشور عقب نشست، بی‌مقاومت وارد تبریز، پایتخت صفویان، شد. قانونی نیز در سپتامبر به شهر رسید؛ اما به سبب فشار زمستان و بسیار دراز شدن خط تدارکات، سپاه به سوی بغداد روی آورد و تبریز مدتی دراز نگه داشته نشد. شهری که پس از چالدران برای بار دوم گرفته شد، جایی شد که عثمانی در آن آموخت در شرق گرفتن آسان و نگه داشتن دشوار است.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["فتح تونس به دست بارباروس", "d8754216"], "d": ["قاپودان دریا بارباروس خیرالدین پاشا پس از زدن سواحل ایتالیا با ناوگانش به تونس روی آورد، مولای حسن، فرمانروای حفصی، را گریزاند و وارد شهر شد. گرفتن تونس به سبب جایگاهش که تنگه سیسیل را نظارت می‌کرد، توازن قدرت را در مدیترانه باختری ناگهان به سود عثمانی گرداند. اما این سیادت دیری نخواهد پایید و شارل پنجم سال بعد با ناوگانی بزرگ پاسخ خواهد داد.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["از دست رفتن تونس به شارل پنجم", "a691f0f8"], "d": ["شارل پنجم با لشکرکشی بزرگی که ناوگان‌های جنوا و پاپ پشتیبان آن بودند، پس از فروافتادن حلق‌الوادی تونس را گرفت و مولای حسن را زیر حمایت اسپانیا بر تخت بازگرداند. با استقرار پادگانی اسپانیایی در شهر، پیشروی عثمانی در مدیترانه میانه موقتاً متوقف شد. فتح قطعی تونس تنها چهل سال بعد، در 1574، ممکن خواهد شد.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["عملیات غازی خسرو بیگ در امتداد ساوا: بوسنی برود و یاسنوواتس", "3740ec83"], "d": ["پس از گرفته شدن یایجه و بانالوکا در 1528، قلعه‌های کنار رود ساوا مدتی دیگر در مرز کروات-اسلاوون وابسته به تاج هابسبورگ ماندند. غازی خسرو بیگ که در 1536 برای سومین بار سنجق‌بیگ بوسنی شد، همان سال هنگام گرفتن پوژگا و پیرامون آن، قلعه‌های برود و یاسنوواتس را در ساحل ساوا نیز به اداره عثمانی افزود. بدین‌سان مرز شمالی بوسنی به ساوا رسید؛ منطقه دو سال بعد با گرفته شدن دوبیتسا تکمیل شد.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["اعدام ابراهیم پاشای مقبول", "348aa7b8"], "d": ["ابراهیم پاشا که سیزده سال صدراعظم بود، نزدیک‌ترین دوست قانونی و عملاً مرد دوم دولت بود، در کاخی که برای افطار فراخوانده شده بود بی‌ذکر هیچ دلیلی خفه و اعدام شد. موضع او در لشکرکشی عراقین، به کار بردن عنوان «سرعسکر سلطان» و توازن‌های درون دربار در مرگ او مؤثر شمرده می‌شود. این اعدام نقطه عطفی است که نشان می‌دهد در اداره مرکزی عثمانی امنیت مطلق صدراعظمان وجود نداشت.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["فتح قلعه کلیس و بنیان‌گذاری سنجق دالماسیا", "6ffd4ebf"], "d": ["مراد بیگ، نومسلمان کروات‌تبار و کتخدای غازی خسرو بیگ، قلعه راهبردی کلیس را که درست در شمال اسپلیت است از ونیز گرفت. بی‌درنگ پس از فتح، کلیس مرکز سنجق و قضایی نو شد که پیرامون خود را دربرمی‌گرفت؛ مرزهای این سنجق تا حد زیادی چارچوب کرواسی عثمانی را ترسیم کرد. این فتح که پانزده سال پس از کنین آمد، اسکلت اداری درون دالماسیا را تکمیل کرد.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["محاصره کورفو و جنگ با ونیز", "11af95bd"], "d": ["پس از لشکرکشی پولیا (آپولیا) سپاه عثمانی در کورفو نیرو پیاده کرد و قلعه نیرومند ونیزی جزیره را محاصره نمود. به سبب سخت‌گذر بودن قلعه، تلفات سنگین و شرایط فصل، در 6 سپتامبر محاصره برداشته شد و سپاه عقب نشست. هرچند محاصره بی‌نتیجه ماند، جنگی که با ونیز آغاز شده بود با پیوستن شمار زیادی از جزایر اژه و آدریاتیک به عثمانی و با پیروزی پروزه در سال بعد به پایان رسید.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["لشکرکشی اژه بارباروس: گرفتن جزایری که ونیز مستقیماً اداره می‌کرد", "1b32ed96"], "d": ["ناوگانی که از محاصره کورفو بازمی‌گشت، با بهره‌گیری از اعلان جنگ به ونیز، جزایری را که در اژه نه به دوک‌نشین بلکه مستقیماً به ونیز بسته بود یکی‌یکی تسلیم گرفت. اِجینا پس از ایستادگی سخت گرفته شد، آستیپالیا که در دست خاندان کرینی بود و کارپاتوس و کاسوت تسلیم شدند، پاتموس که اداره‌اش با صومعه بود نیز حمایت عثمانی را پذیرفت. دوک‌نشین ناکسوس به باج بسته شد و برجا ماند؛ الحاق آن تا 1566 باید منتظر می‌ماند.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["لشکرکشی اژه شمالی بارباروس: گرفتن اسکیروس و اسپوراد شمالی", "20ab688e"], "d": ["در راه پروزه ناوگان جزایر اژه شمالی را که پس از فتح استانبول به ونیز پناه برده بودند یکی‌یکی تسلیم گرفت. اسکیروس در شمال اغریبوز و اسکیاتوس، اسکوپلوس و آلونیسوس که دهانه خلیج سالونیک را در دست داشتند بدین‌سان به اداره عثمانی درآمد. این جزایر واپسین خلأ اژه شمالی را بستند که با وجود گرفته شدن اغریبوز در 1470، شصت و هشت سال دیگر نیز در دست ونیز مانده بود.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["تصرف عدن و الحاق ساحل یمن", "e7d46d8f"], "d": ["ناوگانی که برای لشکرکشی هند از سوئز بیرون آمده بود، چون بی‌ایمن کردن دریای سرخ نمی‌شد به اقیانوس رفت، نخست به ساحل یمن روی آورد. خادم سلیمان پاشا در 3 اوت 1538 وارد بندر عدن شد؛ امیر بن داود، فرمانروای طاهری که به پرتغالی‌ها گرایش داشت، به درگاه قاپودان آورده و اعدام شد و پانصد نگهبان در شهر گذاشته شد. در همان لشکرکشی مخا و جزایر کمران و فراسان که بر تنگه فرمان می‌راندند نیز تسلیم گرفته شد و بنیاد بیلربیگی یمن نهاده شد. بدین‌سان دولت عثمانی نخستین بار صاحب همه ساحل شمالی باب‌المندب شد؛ صنعا و نواحی درونی نه سال دیگر باید منتظر می‌ماند.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["لشکرکشی مولداوی و الحاق منطقه بوجاک (بندر)", "90a88a56"], "d": ["در لشکرکشی علیه پترو ریرش، وویودای مولداوی که تعهدات خود را نسبت به عثمانی انجام نمی‌داد، سوچاوا گرفته شد و شهر یاش به دست سلیم گرای، خان کریمه، غارت شد. پادشاه استفان چکیرگه را به وویودایی گماشت و بندر را همراه با بوجاک (بسارابی جنوبی) مستقیماً به سرزمین‌های عثمانی افزود. این الحاق یکی از حلقه‌هایی شد که سواحل شمال‌باختری دریای سیاه را به دریای درونی عثمانی بدل کرد. مولداوی پیشتر وویودای‌نشینی تابع عثمانی بود؛ این لشکرکشی سرزمین را از دولت بیگانه نگرفت، تنها اداره درونی بندر و بوجاک را از وویودا گرفت و مستقیماً به پادشاه بست؛ باقی وویودایی منزلت تابع خود را ادامه داد. همین ساختار در 1484 در کیلیا و آق‌کرمان و در 1713 در خوتین نیز تکرار خواهد شد: قلعه‌های مرزی مستقیم، سرزمین‌های درونی تابع.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["تحویل گرفتن آنابولی (ناپلیون) با پیمان", "104d0937"], "d": ["جنگ ونیز که پس از پروزه سه سال کشید، با پذیرفتن جمهوری به رها کردن واپسین دو قلعه خود در موره پایان یافت. آنابولی و بنفشه که با محاصره گرفته نشده بود، افزون بر غرامت جنگی سیصد هزار دوکا بر سر میز به عثمانی واگذار شد. شبه‌جزیره موره بدین‌سان به‌گونه‌ای یکی شد که هیچ ردپای ونیزی برجا نماند.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["درآمدن سگدین به اداره عثمانی و تشکیل لوای سگدین", "019aa000"], "d": ["پس از آنکه اداره عثمانی در بودین در 1541 کاملاً برپا شد، بزرگان سگدین فرمانروایی فردیناند یکم را پذیرفتند و برای دفاع مسلحانه آماده شدند. بیلربیگی بودین کوچک بالی پاشا در آغاز 1543 سران شهر را نزد خود فراخواند و به دلیل خیانت اعدام کرد، سپس برای گرفتن شهر یگانی فرستاد. در این میان لوای سگدین تشکیل شد و نخستین سنجق‌بیگ آن درویش بیگ، پسر بالی پاشا، گماشته شد؛ لوا در آغاز میان دانوب و تیسا کشیده می‌شد.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["فتح والپو، شیکلوش و پچوی", "2ca030a3"], "d": ["نخستین هدف لشکرکشی مجارستان که دو سال پس از الحاق بودین انجام شد، ایمن کردن جناح جنوبی ایالت نو میان دراوا و دانوب بود. پس از گرفته شدن قلعه‌های والپو و شیکلوش، پچوی، مرکز بارانیا، تسلیم شد. شهر به پرجمعیت‌ترین و آبادترین مرکز مجارستان عثمانی بدل می‌شد و مورخ ابراهیم پچوی‌لی نام خود را از اینجا می‌گرفت.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["فتح استرگون و استولنی بلگراد", "efca9e05"], "d": ["در لشکرکشی مجارستان که قانونی شخصاً به آن رفت، پس از دو هفته و نیم محاصره، استرگون، مرکز دینی پادشاهی مجارستان و شهر اسقف اعظم، به اداره عثمانی درآمد. سپس استولنی بلگراد، شهر تاج‌گذاری پادشاهان مجارستان نیز گرفته شد و کمربند دفاعی ایالت بودین تکمیل گردید. استرگون تا 1595 همچون قلعه کلیدی خط دانوب در دست عثمانی خواهد ماند.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["کمربند دفاعی شمال و باختر بودین: واچ، هاتوان و شیمونتورنا", "733ee5ce"], "d": ["پس از گرفته شدن استرگون و استولنی بلگراد، بیلربیگی بودین برای تکمیل حلقه قلعه‌هایی که پایتخت را در میان می‌گرفت، بی‌لشکرکشی پادشاه وارد عمل شد. واچ در خمیدگی دانوب، هاتوان دروازه آلفولد و شیمونتورنا در خط شیو یک‌یک تسلیم گرفته شد. دستاوردهای این سال آرام بودین را از شهری مرزی به مرکز ایالتی بدل کرد که یک صد و چهل سال دوام خواهد آورد.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["الحاق بصره و رسیدن به خلیج بصره", "02f87c11"], "d": ["در جریان فتح بغداد (1534) راشد بن مغامس، فرمانروای بصره، فرمانبری خود را به قانونی اعلام کرده و در 1538 کلیدهای شهر را فرستاده بود. چون شیخ یحیی که جای او را گرفت در برابر عثمانی‌ها موضع گرفت، بیلربیگی بغداد عیاس پاشا از خشکی و سنجق‌بیگ موصل با 120 کشتی از فرات لشکر کشیدند؛ عیاس پاشا در 26 دسامبر 1545 وارد بصره شد و شهر مرکز بیلربیگی شد. این بندر در دهانه شط‌العرب دروازه‌ای بود که عثمانی از آنجا به خلیجی گشوده می‌شد که پرتغال از هرمز نظارتش می‌کرد؛ با پیمان آماسیه 1555 ایران نیز این وضع را شناخت.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["فتح صنعا و درون یمن", "d31ded85"], "d": ["پس از تعز صنعا نیز گرفته شد و همه کشور به بیلربیگی بسته شد. اما به سبب جغرافیای سخت و تفاوت مذهب این فرمانروایی هرگز آسوده نبود؛ یمن برای عثمانی به جبهه‌ای بدل شد که پیوسته سرباز می‌بلعید.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["فتح تعز", "d4509df9"], "d": ["در یمنی که نه سال پیش به ساحل بسنده شده بود، با نیرومندتر شدن امامان زیدی در درون کوهستانی، نیروهای اوزدمیر پاشا به فلات برآمدند و تعز را گرفتند.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["پیمان استانبول — صلح پنج‌ساله با هابسبورگ‌ها", "41f81773"], "d": ["میان عثمانی و هابسبورگ‌ها صلحی پنج‌ساله امضا شد؛ فردیناند پذیرفت برای سرزمین‌های مجارستان که در دست داشت سالانه 30.000 دوکا بپردازد. پیمان وضعیت عملی سه‌پاره بودن مجارستان را از نظر حقوقی ثبت کرد. ایمن شدن جبهه باختری بدین‌سان به قانونی امکان داد لشکرکشی‌های تازه‌ای علیه ایران سامان دهد.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["لشکرکشی دوم ایران و گرفته شدن دوباره تبریز", "e82365df"], "d": ["در لشکرکشی‌ای که با تشویق القاص میرزا، برادر شاه طهماسب که علیه او شورید و به استانبول پناه برده بود، انجام شد، سپاه برای بار دوم وارد تبریز شد. چون صفویان باز وارد نبرد رویاروی نشدند و با سوزاندن زمین عقب نشستند، تنها چند هفته در شهر ماندن ممکن شد. لشکرکشی ثابت کرد که تبریز را نمی‌توان نگه داشت و راهبرد عثمانی را به برپایی خط مرزی پایدار، یعنی استوار کردن وان، سوق داد.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["فتح وان و استوار شدن مرز شرقی", "fc8f930b"], "d": ["قلعه وان که هنگام بازگشت از تبریز محاصره شد، با موقعیتی که بر صخره‌ای در کرانه شرقی دریاچه برمی‌خاست بی‌چون‌وچرا قفل منطقه بود و پس از محاصره‌ای کوتاه تسلیم شد. شهر بی‌درنگ مرکز بیلربیگی شد؛ سنجق‌های ارجیش، عادلجواز و حکاری بدان بسته شد. برخلاف تبریز، وان نگه داشته شد و چهارصد سال پیشرفته‌ترین سنگر پایدار عثمانی در شرق ماند.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["الحاق لحسا و قطیف — ساحل عربی خلیج", "f6701e60"], "d": ["پس از گرفتن بصره، قطیف که در ساحل باختری خلیج به پاسگاه پیشرو پرتغال بدل شده بود گرفته شد و همراه با واحه‌های لحسا در درون، بیلربیگی نوینی برپا شد. این نقطه خاستگاه عملیات علیه بحرین و هرمز بود. دولت عثمانی بدین‌سان همزمان در هر دو کرانه دریای سرخ و خلیج بصره شبه‌جزیره عربستان صاحب سخن شد.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["از دست رفتن شهرزور — سهراب، بیگ اردلان، به صفویان گرایید", "5600efc9"], "d": ["ناحیه شهرزور که در جریان لشکرکشی عراقین (1535) اداره عثمانی را شناخته بود، زیر فرمان بیگه بیگ، امیر اردلان، بود که در قلعه زلم می‌نشست. با مرگ بیگه بیگ در 1550، برادرش سهراب قلعه زلم را گرفت و بر بیگ‌نشین چیره شد، به صفویان روی آورد و از فرمانبری عثمانی جدا شد؛ ناحیه شهرزور بدین‌سان از نفوذ عثمانی بیرون رفت. منطقه تنها در جریان لشکرکشی نخجوان، در 1554، با محاصره و گرفتن قلعه زلم بازیافته شد.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["گرفتن اردهان و حوضه چیلدیر", "14c9eb76"], "d": ["بیلربیگی ارزروم در جریان جنگ ادامه‌دار با صفویان به سرزمین‌های آتابگ‌های گرجی در قوس کورا روی آورد و اردهان و پیرامون چیلدیر را به اداره عثمانی بست. خط قارص-اردهان بدین‌سان یکی شد و فلات‌های گشوده به گرجستان در شمال‌خاوری زیر نظارت درآمد. نظم اداری قطعی منطقه بیست و هفت سال بعد با ایالت چیلدیر تکمیل می‌شد.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["عبور سوکولو محمد پاشا از دانوب — آغاز جنگ ارْدل", "38fde931"], "d": ["به سبب آشفتگی‌هایی که مارتینوزی راهب، سرپرست یانوش ژیگموند کوچک، پادشاه ارْدل، پدید آورد و واگذاری قلعه‌های بانات از سوی ارْدل به فردیناند، لشکرکشی تازه‌ای لازم دیده شد؛ فرماندهی به بیلربیگی روم‌ایلی سوکولو محمد پاشا سپرده شد. سپاه با وجود کوشش‌های مارتینوزی برای معطل کردن از دانوب گذشت، بچه، بچکرک، چانات و لیپا را گرفت؛ اما محاصره تمشوار در 16 نوامبر به سبب سرما برداشته شد. بدین‌سان جنگ تازه عثمانی و هابسبورگ در مجارستان گشوده شد.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["شهر لیپووا (Lippa) به دست سپاه اتریش کاستالدو افتاد — قلعه در 5 دسامبر تسلیم شد", "a0e1ff0d"], "d": ["لیپووا را که صوقوللو محمد پاشا در اکتبر 1551 گرفته بود، سپاه ژنرال کاستالدو در 4 نوامبر محاصره کرد؛ دو روز بعد شهر به دست اتریشی‌ها افتاد. اولاما پاشا با نگهبانی 5.000 نفره قلعه را نه روز دیگر دفاع کرد و در 5 دسامبر 1551 با توافق بیرون آمد. لیپووا تا سقوط تمشوار در 1552 در دست هابسبورگ ماند.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["نگه داشتن پالانکاهای بانات جنوبی به دست نیروهای فرستاده‌شده از تمشوار — ورشتس، هارام، کوه", "edca0921"], "d": ["پس از تسلیم تمشوار به سپاه عثمانی، یگان‌هایی که از سپاه محاصره جدا شدند به پالانکاهای کوچک بانات روی آوردند؛ بنا بر روایت بانلاکی، پالانکاهای Versec، Facset، Mehádia، Csákóvár، Haramvár و Keve به دست این نیروها نگه داشته شد. بدین‌سان هارام در ساحل دانوب نیز به دست عثمانی افتاد.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["فتح سولنوک و ناکامی محاصره اگری", "a7156e8f"], "d": ["پس از گرفته شدن تمشوار، دو سپاه عثمانی که یکی شده بودند سولنوک را در کنار تیسا با ترک قلعه به دست نگهبانان مزدور تقریباً بی‌درگیری گرفتند. سپس قلعه اگری که محاصره شد، در برابر ایستادگی سی و هشت‌روزه پادگان دو هزار نفره به فرماندهی ایشتوان دوبو گرفته نشد و سپاه با رسیدن زمستان عقب نشست. در یک لشکرکشی فرو افتادن آسان یک قلعه و ایستادن دیگری، نخستین نشانه آشکار بود که مرز در مجارستان دیگر خودبه‌خود به سود عثمانی پیش نمی‌رود.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["اتحاد عثمانی و فرانسه — درآمدن ناوگان فرانسه به فرمان عثمانی", "a8e01b22"], "d": ["با پیمانی به تاریخ 1 فوریه 1553 ناوگان فرانسه به فرمان ناوگان عثمانی داده شد؛ عملیات مشترک در مدیترانه باختری علیه اسپانیا پیش‌بینی گردید. پس از پیمان، تورگوت ریس در 15 ژوئن 1553 با چهل و پنج گالی برای پشتیبانی از فرانسه به لشکرکشی رفت. این نخستین پیمان اتحاد رسمی بود که زمینه بازرگانی کاپیتولاسیون‌های 1536 را به همکاری نظامی کشاند.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["اعدام شاهزاده مصطفی در اِرِگلی قونیه", "dec36858"], "d": ["شاهزاده مصطفی که برای پیوستن به سپاه گردآمده برای لشکرکشی نخجوان به خرگاه پدرش درآمد، هنگامی که می‌خواست به حضور برسد با جلادان روبه‌رو شد و خفه شده کشته گردید. قتل ولیعهدی که در سپاه محبوبیت بسیار داشت خشمی ژرف در میان ینی‌چریان برانگیخت و رستم پاشا از صدارت برکنار شد. این رویداد به‌عنوان یکی از بحث‌برانگیزترین گسست‌های سیاست شاهزادگان عثمانی به ادبیات و حافظه مردم راه یافت.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["جابه‌جا شدن مرز ابریم و نوبه به سوی جنوب", "c57d5d77"], "d": ["مرز جنوبی بیلربیگی مصر با استوار شدن قلعه ابریم که بر دماغه‌ای صخره‌ای بر نیل برمی‌خاست به دست اوزدمیر بیگ و پیوستن کامل نوبه سفلی به مصر عثمانی به آن سوی آبشار دوم برده شد. (در ابریم تشکیلات اداری عثمانی پس از فتح مصر برپا شده بود؛ بر نقشه ابریم از 1517 عثمانی نشان داده می‌شود. این سال تقریبی است، منبع سال نمی‌دهد.) قلعه همان‌قدر که سدی در برابر یورش‌های نوبه بود نقطه نظارت بر راه زر و برده رسیده به سنار نیز بود. یگان نگهبان بوسنیایی که در آنجا جای گرفت چنان پایدار شد که نوادگانش سیصد سال بعد هنوز در قلعه بودند. منابع درباره زمان درآمدن ابریم به اداره عثمانی دو روایت جداگانه می‌دهند: مدخل سودان TDV پیوستن نوبه سفلی به مصر عثمانی را به عملیات اوزدمیر پاشا در میانه سده شانزدهم می‌بندد، اما مدخل نوبه می‌نویسد منطقه تا دره حلفا و تشکیلات اداری ابریم بی‌درنگ پس از فتح 1517 برپا شده است. سنجق ابریم در 26 ژوئیه 1573 به ایالت حبش بسته شد.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["گرفتن بجایه (بوژی) از اسپانیایی‌ها", "49691cda"], "d": ["بجایه که چهل و سه سال در دست اسپانیا بود و ساحل میان الجزایر و قسنطینه را دو نیم می‌کرد، پس از محاصره از خشکی و دریا تسلیم شد. با سقوط قلعه، ساحل اوجاق الجزایر تا وهران بی‌گسست شد. در اسپانیا این زیان چنان خشمی برانگیخت که فرمانده‌ای که قلعه را تسلیم کرده بود، آلونسو دو پرالتا، در زادگاهش اعدام شد.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["پیوستن زیلع به ایالت حبش", "7bbf369a"], "d": ["در جنوبی‌ترین نقطه ایالت حبش، بندر زیلع در ساحل آفریقایی خلیج عدن به اداره عثمانی بسته شد. این شهر که دروازه گشوده سلطان‌نشین عدل به دریا بود، واپسین نقطه تأمین برای کشتی‌هایی بود که از باب‌المندب بیرون می‌رفتند. با پیوستن زیلع مرز دولت عثمانی در آفریقا به جنوبی‌ترین نقطه خود رسید.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["نبرد شاهزادگان در قونیه", "1c8de387"], "d": ["شاهزاده بایزید که وارد کشمکش تاج‌وتخت شده بود با نیرویی حدود 30.000 نفره به پای قونیه آمد و در درگیری دو روزه از برادرش شاهزاده سلیم شکست خورد. بایزید شکست‌خورده از راه آماسیه به ایران نزد شاه طهماسب پناه برد. این نبرد مسئله جانشینی سلطنت را در سال‌های پایانی قانونی به مسئله‌ای از سیاست خارجی بدل کرد.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["پیروزی دریایی جربه", "c7b905c1"], "d": ["ناوگان عثمانی به فرماندهی پیاله پاشا، ناوگان متحد اسپانیا-جنوا-مالت را که برای بازپس‌گیری طرابلس گردآمده بود، در برابر جربه با مانور دوپاره‌شدن درهم پاشید. متحدان بخش بزرگ ناوگان خود را از دست دادند و قلعه جزیره نیز به‌زودی سقوط کرد. جربه پس از پروزه دومین پیروزی بزرگ دریایی شمرده می‌شود که برتری عثمانی را در مدیترانه استوار کرد.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["اعدام شاهزاده بایزید در قزوین", "a759de14"], "d": ["شاهزاده بایزید که به ایران پناه برده بود، در پی چانه‌زنی‌های دراز از سوی شاه طهماسب به هیئت عثمانی تسلیم شد و همراه چهار پسرش خفه شده کشته شد. صفویان در برابر تسلیم امتیازهای مالی مهم و تضمین مرزی به دست آوردند. با این اعدام واپسین مانع بر سر راه جلوس سلیم دوم برداشته شد و نظم صلح پیمان آماسیه حفظ گردید.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["گرفتن خیوس (ساقز) از جنوایی‌ها", "a4559b96"], "d": ["خیوس که دو سده به‌عنوان مستعمره بازرگانی خاندان جوستینیانی جنوایی اداره می‌شد و به عثمانی باج می‌داد، به این دلیل که باجش را به تأخیر انداخته و به کشتی‌های دشمن بندر داده بود، بی‌شلیک گلوله‌ای به دست پیاله پاشا تسلیم گرفته شد. با خیوس و ابسارا واپسین حضور جنوایی در کرانه خاوری اژه نیز برچیده شد. تولید مصطکی و امتیازهای مردم خیوس حفظ شد و جزیره به ایالت جزایر بحر سفید بسته شد.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["الحاق دوک‌نشین ناکسوس — همه جزایر کیکلاد", "68f0ec0b"], "d": ["دوک‌نشین لاتینی ناکسوس که از 1207 ادامه داشت و از 1537 به عثمانی باج می‌داد، با دستاویز شکایت‌هایی که از ستم واپسین دوک، جاکومو کریسپو، بر مردمش رسیده بود، برچیده شد. ناکسوس، پاروس، آنتی‌پاروس، آندروس، سیروس، میکونوس، ملوس، ایوس و همه جزایر کیکلاد پیرامون آنها با یک تصمیم مستقیماً به اداره عثمانی درآمد. قانونی مدتی اداره جزایر را به یوسف ناسی سپرد؛ فرمانروایی لاتینی سه سده و نیمه بدین‌سان در میانه اژه پایان یافت.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["شورش یمن و لشکرکشی قوجه سنان پاشا به یمن", "c8218d8e"], "d": ["مطهر، امام زیدی، به بهانه گرفتن زورکی مالیات شورید و اداره عثمانی را از بخش بزرگی از یمن برکند. قوجه سنان پاشا که از استانبول فرستاده شد، با عملیات 1568-1570 کوکبان را پس از محاصره‌ای دراز گرفت و فرمانروایی عثمانی را در منطقه از نو برقرار کرد. این لشکرکشی برای نگه داشتن نظارت بر دروازه جنوبی دریای سرخ و راه بازرگانی اقیانوس هند اهمیت حیاتی داشت.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["اتحاد دفاعی با سلطان‌نشین آچه و کمک در اقیانوس هند", "8e835f24"], "d": ["فرستادگان آچه که در برابر حمله‌های پرتغال از قانونی یاری خواسته بودند، با درگذشت پادشاه در زیگتوار، بیعت خود را به سلیم دوم تقدیم کردند و با او پیمان دفاعی امضا شد. پادشاه فرمان داد از اسکندریه توپ، تفنگ، مهمات و استادکار فرستاده شود؛ هفده کشتی جنگی برای اعزام به آب‌های هند آماده شد. بزرگ شدن شورش یمن مانع حرکت ناوگان شد، اما توپچی‌ها و استادکاران عثمانی که به آچه رسیدند در منطقه ردی ماندگار بر جا نهادند.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["پیاده‌شدن در قبرس: گرفتن لیماسول", "9074ccc9"], "d": ["سپاه عثمانی که در جزیره پیاده شد، بی‌آنکه با مقاومت بسیاری روبه‌رو شود لیماسول را گرفت و روز بعد به سوی لارناکا رفت. با نارضایتی مردم بومی از اداره ونیز و یاری آنان به نیروهای عثمانی در لارناکا نیز با مقاومت جدی روبه‌رو نشد؛ اسکله توزلا پایگاه پیاده کردن سرباز و تجهیزات شد. ونیز دفاع خود را در لفکوشا و ماگوسا انباشته بود؛ والی پافوس تنها پس از سقوط لفکوشا فرمانبری خود را به سردار اعلام کرد.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["فتح لفکوشا (نیکوزیا)", "413d866b"], "d": ["پس از محاصره‌ای که 25 ژوئیه 1570 آغاز شد و چهل و پنج روز کشید، لفکوشا، پایتخت قبرس زیر اداره ونیز، به سپاه عثمانی تسلیم شد. سقوط مرکز جزیره مقاومت ونیز را به قلعه ماگوسا فشرد. این فتح در غرب طنین بزرگی یافت و روند شکل‌گیری ناوگان اتحاد مقدس به رهبری پاپ را شتاب بخشید.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["تسلیم گیرنه — ساحل شمالی قبرس", "39fdeea5"], "d": ["سقوط لفکوشا در 9 سپتامبر با کشتار، مقاومت شمال قبرس را شکست. قلعه گیرنه در پشت کوه‌های پنج‌انگشت چون از سرنوشت پایتخت آگاه شد، هشت روز بعد مشروط تسلیم شد و پادگانش با اجازه بیرون رفتن از جزیره روانه گشت. در جزیره پرچم ونیز تنها در ماگوسا ماند؛ آن نیز یازده ماه دیگر پایداری می‌کرد.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["بازسازی ناوگان پس از لپانتو", "db51fe44"], "d": ["نخستین کار قلیچ علی‌پاشا که پس از شکست لپانتو به قاپودان‌پاشایی گماشته شد، بازسازی ناوگانی بود که تلفات سنگین دیده بود؛ کشتی‌سازی‌ها در زمستان 1571-1572 بی‌وقفه کار کردند. در ژوئن 1572 ناوگانی نو مرکب از حدود 250 گالی و 300 گالی ریس‌های داوطلب راهی مدیترانه شد. این بهبود سریع نشان داد لپانتو نیروی دریایی عثمانی را برای همیشه درهم نشکسته است.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["پیمان استانبول با ونیز — به رسمیت شناخته شدن قبرس", "4d08ef50"], "d": ["ونیز که با از هم پاشیدن اتحاد مقدس تنها مانده بود، با عثمانی جداگانه صلح بست، قبرس را رسماً از آنِ عثمانی شناخت و پرداخت غرامت جنگی را پذیرفت. پیمان آشکارا نشان داد پیروزی لپانتو برای جهان مسیحی سودی سیاسی نداشته است. ونیز از آن پس هفتاد سال از جنگ مستقیم با عثمانی پرهیز خواهد کرد.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["درگذشت سلیم دوم", "c289f5ee"], "d": ["سلیم دوم پس از افتادن حدود دو ماه نتوانست به دیوان بیاید و درگذشت. مرگ او تا رسیدن پسر بزرگش مراد از مانیسا به استانبول دوازده روز در کاخ پنهان نگه داشته شد. در روز مرگ منابع اختلاف دارند: سلانیکی 15 دسامبر می‌گوید؛ گرلاخ، محمد بن محمد و جنابی 13 دسامبر می‌گویند.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["اعلان مرگ سلیم دوم و جلوس مراد سوم", "84334d70"], "d": ["مرگ سلیم دوم و جلوس مراد سوم که از مانیسا آورده شد در 22 دسامبر 1574 رسماً اعلام گردید. پادشاه تازه بیست و یک سال بر تخت ماند و سلطنتش با جنگ‌های دراز ایران در شرق، آستانه جنگ دراز در غرب و تقلیل عیار آقچه در درون یاد خواهد شد. تا مرگ سوکولو محمد پاشا در 1579 در اداره دولت نظم پیشین ادامه یافت.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["نبرد وادی‌السیل (قصرالکبیر) — عبدالملک با پشتیبانی عثمانی سپاه پرتغال را نابود کرد", "21280dac"], "d": ["عبدالملک که با پشتیبانی عثمانی بر تخت مراکش نشست، سپاه بزرگ سباستین، پادشاه پرتغال، را در وادی‌السیل نابود کرد؛ چون در این نبرد سه فرمانروا با هم مردند در منابع غربی «نبرد سه پادشاه» نامیده می‌شود. نیروی نظامی پرتغال فروپاشید و کشور اندکی بعد به دست اسپانیا افتاد. عبدالملک نیز در نبرد مرد؛ برادرش احمد المنصور که جانشین او شد پیروزی را با هیئتی به استانبول اعلام کرد. رابطه دو دولت نه در حد باج یا تابعیت بلکه در سطح مبادله سفیر و هدیه ماند و به‌زودی بر سر مسئله هدیه تیره شد.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["اعلام بیعت مردم دربند به لالا مصطفی پاشا — دربند در اداره عثمانی", "9c55aeff"], "d": ["در جریان لشکرکشی شیروان هیئتی هفت‌نفره از مردم دربند نزد سردار لالا مصطفی پاشا که در ارش بود رفتند و بیعت خود را اعلام کردند. دربند (دمیرقاپی) که گذرگاه تنگ میان دیوار قفقاز و دریای خزر را می‌بندد، به‌عنوان گذرگاه ناگزیر راه‌های زمینی رسیده از شمال نقشی کلیدی در نگه داشتن شیروان ایفا کرد. فرمانروایی عثمانی در اینجا تا 1607 ادامه یافت.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["فتح شیروان: گرفتن شماخی", "9afae4c1"], "d": ["سپاهی که پس از پیروزی چیلدیر به قفقاز گشوده شد، وارد شیروان، ثروتمندترین ایالت صفویان در کرانه خزر، شد و شهر مرکزی شماخی را گرفت. با گماشته شدن اوزدمیراوغلو عثمان پاشا در آنجا به بیلربیگی، شاخه شمالی راه ابریشم زیر نظارت عثمانی درآمد. شیروان به جبهه‌ای بدل می‌شد که بیش از همه دست‌به‌دست شد و گران‌ترین جبهه جنگ شرق دوازده‌ساله بود.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["گرفتن باکو — رسیدن به ساحل خزر", "eb5adab8"], "d": ["باکو، بندر ساحل باختری دریای خزر، به‌عنوان واپسین حلقه عملیات شیروان گرفته شد. چاه‌های نفت پیرامون شهر در آن زمان نیز منبع درآمدی شناخته‌شده بود و بندر نقطه خروج ابریشم ایران بود که از راه خزر می‌رسید. دولت عثمانی بدین‌سان در تاریخ خود برای نخستین و تنها بار صاحب ساحل دریای خزر شد.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["فتح ایروان و ساخت قلعه", "7f623b7b"], "d": ["فرهاد پاشا که در قارص فرمان گرفته بود به ایروان برود و در آنجا قلعه‌ای بسازد، بر ایروان لشکر کشید و شهر در آغاز رمضان 991 (میانه سپتامبر 1583) زیر نظارت عثمانی درآمد. در ایروان که دروازه شمالی دره ارس را در دست دارد قلعه‌ای نو و بزرگ ساخته شد؛ شهر مرکز بیلربیگی شد. ایروان که در میانه راه سپاه میان قارص و تبریز ایستاده بود، ستون فقرات پشتیبانی جبهه شرق بود. قلعه چنان استوار ساخته شد که در دو سده بعد هدف همیشگی جنگ‌های عثمانی و ایران شد.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["الحاق قره‌باغ و گنجه", "29abaead"], "d": ["فرهاد پاشا در 1588 به‌عنوان واپسین دستاورد جنگ شرق ده‌ساله بر گنجه لشکر کشید و در 1 سپتامبر وارد شهر شد؛ منطقه قره‌باغ میان کورا و ارس و مرکز آن گنجه به اداره عثمانی درآمد. بدین‌سان شیروان، ایروان و قره‌باغ یکی شد و در قفقاز خطی بی‌گسست از عثمانی پدید آمد. پیمان فرهاد پاشا که در 1590 امضا می‌شد این مرز را ثبت می‌کرد، اما دستاورد تنها بیست سال نگه داشته شد.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["فتح بیهاچ", "651a7275"], "d": ["تلی حسن پاشا، بیلربیگی بوسنی، پس از گرفتن ریپاچ، قلعه پیش‌دستی بیهاچ، در نوامبر 1591، در 1592 شهر و خود قلعه را نیز گرفت؛ پس از ده روز محاصره فرمانده لامبرگ تسلیم شد. این فتح مرز بوسنی را در امتداد رود اونا پیش راند و واپسین دستاورد بزرگ عثمانی در آستانه جنگ درازی شد که یک سال بعد با کشته شدن تلی حسن پاشا در برابر کولپا درمی‌گرفت.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["آغاز «جنگ دراز» عثمانی و اتریش", "bd22c392"], "d": ["با شکست و شهادت تلی حسن پاشا، بیلربیگی بوسنی، در برابر کولپا (سیساک)، دولت عثمانی به اتریش اعلان جنگ کرد و جنگ درازی که سیزده سال خواهد کشید آغاز شد. این جنگ که در آن پیاده‌نظام مجهز به سلاح گرم تعیین‌کننده بود، به‌کارگیری سکبان و سربازان تفنگدار را در نظام ارتش عثمانی شتاب بخشید و زوال سپاهی تیمارلو را ژرف‌تر کرد. جنگ در 1606 با پیمان زیتواتوروک پایان خواهد یافت.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["قوجه سنان پاشا به لشکرکشی اتریش رفت — نخستین لشکرکشی جنگ دراز", "d4a2f46d"], "d": ["پس از شکست و شهادت حسن پاشا، بیلربیگی بوسنی، در برابر سیسک (ساساک)، صدراعظم قوجه سنان پاشا با سخنان درخشان و وعده‌ها پادشاه را به جنگ راضی کرد و با 12.000 ینی‌چری و یگان‌های دیگر راه افتاد. بدین‌سان نخستین لشکرکشی جنگ عثمانی و اتریش که سیزده سال خواهد کشید گشوده شد.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["فتح یانیق‌قلعه (گیور)", "14b75207"], "d": ["صدراعظم قوجه سنان پاشا پس از محاصره‌ای بیش از یک ماه، یانیق‌قلعه را که قفل راه وین شمرده می‌شد تسلیم گرفت. سقوط قلعه در اروپا هراس بزرگی برانگیخت و درخشان‌ترین دستاورد عثمانی در جنگ دراز شد. اما قلعه تنها چهار سال نگه داشته خواهد شد.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["درگذشت مراد سوم", "1b62e886"], "d": ["مراد سوم پس از بیست و یک سال سلطنت، در روزهایی که سپاه افلاق ابریل را سوزانده و تا سیلیستره رسیده بود درگذشت و در حظیره ایاصوفیه به خاک سپرده شد. پسرش محمد سوم که از مانیسا فراخوانده شده بود ده روز بعد به استانبول رسید و بر تخت نشست (27 ژانویه 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["از دست رفتن استرگون به اتریش", "f420d333"], "d": ["در محاصره‌ای که کارل فون مانسفلد رهبری می‌کرد، نگهبانان استرگون که یاری کافی نمی‌گرفتند قلعه را به آرشیدوک ماتیاس تسلیم کردند. با پایان یافتن پنجاه و دو سال فرمانروایی عثمانی زنجیره دفاعی خط دانوب شکست و بودین مستقیماً زیر تهدید افتاد. قلعه تنها ده سال بعد، در 1605، بازپس گرفته خواهد شد.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["فتح قلعه اگری", "3e511629"], "d": ["پس از سه هفته کشمکش، قلعه نیرومند اگری که عثمانی‌ها پیش‌تر هرگز نتوانسته بودند بگیرند، با تسلیم نگهبانان سقوط کرد. این فتح که پادشاه شخصاً در آن حضور داشت، روحیه‌ای را که از دست رفتن استرگون پدید آورده بود تا اندازه‌ای ترمیم کرد و ایالت اگری برپا شد. 1596 با پیروزی هاچوا که دو هفته بعد به دست آمد، موفق‌ترین سال عثمانی در جنگ دراز شد.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["از دست رفتن یانیق‌قلعه (گیور)", "b4ccc679"], "d": ["یگان‌هایی به فرماندهی میکلوش پالفی و آدولف فون شوارتزنبرگ با شبیخون و منفجر کردن دروازه‌های قلعه یانیق‌قلعه را بازپس گرفتند. از دست رفتن قلعه‌ای که چهار سال پیش قوجه سنان پاشا با زحمت بسیار به دست آورده بود، خط پیشرو عثمانی را در مجارستان فروریخت. همان سال هرچند نیروهای دشمن که بودین را محاصره کرده بودند عقب رانده شدند، توازن جنگ رفته‌رفته به جنگ فرسایشی بدل شد.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["شورش قره‌یازیجی عبدالحلیم", "30493b0d"], "d": ["قره‌یازیجی عبدالحلیم که سکبان‌ها و لوندهای گریخته از سپاه را در جنگ دراز گرد آورد، منطقه‌ای گسترده را در آناتولی میانه زیر نظارت گرفت، قلعه اورفه را گرفت (نوامبر 1599) و با عنوان «حلیم شاه» پادشاهی خود را اعلام کرد و فرمان‌هایی با طغرای خود فرستاد. قره‌یازیجی که نخستین رهبر موج بزرگ جلالی شمرده می‌شود، در 1602 مرده و جنبش را برادرش دلی حسن ادامه داده است. شورش آغاز دوران «قاچگونلوق بزرگ» است که در آن روستاییان آناتولی توده‌وار زمین خود را رها کردند.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["دفاع تیریاکی حسن پاشا از قانیزسا", "d56a5e6a"], "d": ["آرشیدوک فردیناند و متحدانش که می‌خواستند قانیزسا را که یک سال پیش فتح شده بود بازپس گیرند، قلعه را بیش از دو ماه محاصره کردند؛ تیریاکی حسن پاشا با نیروی 9000 نفره ایستادگی کرد. با وجود نگرفتن یاری بیرونی، یورش‌های همگانی را دفع کرد و با عملیات بیرون‌تازی دشمن را به عقب‌نشینی با تلفات سنگین واداشت. این دفاع در تاریخ‌نگاری عثمانی حماسی شده و «محاصره قانیزسا» خود به گونه‌ای ادبی بدل گشته است.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["درگذشت محمد سوم و جلوس احمد یکم", "da735fde"], "d": ["با مرگ محمد سوم در 20 دسامبر، پسر چهارده‌ساله‌اش احمد یکم بر تخت نشست. نخستین پادشاهی بودن او که در کودکی و بی‌آنکه به سنجق رفته باشد بر تخت نشست نشان می‌دهد شیوه پرورش شاهزادگان در ولایات عملاً پایان یافته بود. در سلطنت احمد یکم برادرکشی کنار گذاشته شد و به اصل «اکبریت» (جلوس مسن‌ترین عضو مرد خاندان) گذر خواهد شد.", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["بازپس‌گیری استرگون", "7330f273"], "d": ["صدراعظم لالا محمد پاشا استرگون را که ده سال پیش از دست رفته بود محاصره کرد و دوباره به اداره عثمانی افزود. در همان لشکرکشی پشته و واچ نیز رهایی یافت و عثمانی خط خود را در مجارستان سامان داد. این موفقیت سال بعد در زیتواتوروک نشستن نسبتاً نیرومند بر میز مذاکره را ممکن کرد؛ استرگون تا 1683 در دست عثمانی خواهد ماند.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["پیروزی دشت اوروچ و سرکوب شورش جانبولات‌اوغلو", "30f93532"], "d": ["جانبولات‌اوغلو علی‌پاشا که در حلب بیگ‌نشینی مستقل برپا کرده و در جست‌وجوی اتحاد با توسکانا بود، به دست صدراعظم کویوجو مراد پاشا در دشت اوروچ به شکستی سنگین دچار شد. با برقراری دوباره اقتدار مرکزی در سوریه، خطرناک‌ترین شاخه موج جلالی شکسته شد. تصفیه بی‌رحمانه دو ساله کویوجو مراد پاشا آرامش را در آناتولی، هرچند موقت، برقرار کرد.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["پیروزی آلاچایر و سرکوب شورش قلندر‌اوغلو", "55db0485"], "d": ["قلندر‌اوغلو، رهبر جلالی که پیرامون مانیسا و بورسا را باج‌گیر کرده بود، به دست کویوجو مراد پاشا در آلاچایر شکست خورد و ناگزیر به ایران گریخت. با این پیروزی واپسین لشکر بزرگ جلالی در آناتولی پراکنده شد. تصفیه سخت کویوجو مراد پاشا که روایت می‌شود شورشیان کشته‌شده را در چاه‌هایی که می‌کند انباشته است، هرچند در کوتاه‌مدت نظم آورد، زیان جمعیتی و تولیدی آناتولی را جبران نتوانست.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["دادن نخستین عهدنامه به هلند", "5d9d117e"], "d": ["کورنلیس هاگا، سفیر جمهوری متحد هلند، توانست از احمد یکم عهدنامه‌ای هم‌سنگ آنچه به فرانسه و انگلستان داده شده بود بگیرد. هلند بدین‌سان حق گشودن سفارت در استانبول، کنسولگری در اسکله‌های عثمانی و بازرگانی با پرچم خود را به دست آورد. این عهدنامه نماد ورود قدرت‌های دریایی شمالی که در بازرگانی مدیترانه جای ونیز را می‌گرفتند به بازار عثمانی است.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["مرگ احمد یکم و جلوس مصطفی یکم — شیوه اکبریت", "9901c09e"], "d": ["احمد یکم بیست و هشت‌ساله پس از بیماری معده‌ای که پنجاه و یک روز کشید درگذشت و به‌جای پسرش، برادرش مصطفی یکم بر تخت نشانده شد. بدین‌سان شیوه جانشینی پدر به پسر کنار گذاشته شد و عملاً به نظام «اکبریت» که مسن‌ترین عضو مرد دودمان بر تخت می‌نشیند گذر شد. این نخستین سلطنت که نود و شش روز کشید، آغاز دوران پرورش شاهزادگان در «قفس» نیز هست.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["خلع مصطفی یکم و جلوس عثمان جوان (عثمان دوم)", "e0f552f2"], "d": ["مصطفی یکم پس از نود و شش روز به این دلیل که سلامت روانش درست نبود از تخت پایین آورده شد و عثمان دوم، پسر چهارده‌ساله احمد یکم، پادشاه شد. بنا بر روایتی که به حسن‌بیگ‌زاده برمی‌گردد، در تصمیم خلع خواجه‌سرای حرم مصطفی آغا مؤثر بود. عثمان جوان با طرح برچیدن اوجاق ینی‌چری و برپایی سپاهی نو نخستین نام رادیکال در گفتگوهای اصلاحات عثمانی شمرده می‌شود. این طرح چهار سال بعد جانش را خواهد گرفت.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["پیمان سراو — تجدید صلح با ایران", "e778aca8"], "d": ["پیمان سراو که پس از شکست پل شکسته با ایران بسته شد، شرایط پیمان نصوح پاشا (1612) را تا حد زیادی تأیید کرد؛ مقدار ابریشم سالانه‌ای که صفویان می‌فرستادند از دویست بار به صد بار کاسته شد. بدین‌سان مرحله دوم جنگ‌های شرقی که از 1603 ادامه داشت بسته شد. صلح عمری دراز نخواهد داشت و با از دست رفتن بغداد در 1623 جنگ دوباره شعله خواهد کشید.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["لشکرکشی خوتین و پیمان خوتین", "bc4c823c"], "d": ["در برابر سپاه بزرگی که عثمان دوم شخصاً فرماندهی می‌کرد، اردوگاه مستحکمی که خودکیویچ در پای خوتین برپا کرده بود شکسته نشد و پس از ماه‌ها یورش نتیجه‌ای به دست نیامد. با پیمانی که در 9 اکتبر امضا شد، رود دنیستر مرز شناخته شد و لهستانی‌ها متعهد شدند جلو یورش‌های قزاق را بگیرند. این لشکرکشی که با وجود پیروزی خوانده شدن نتیجه‌ای نداد، بی‌اعتمادی پادشاه جوان به ینی‌چریان و قصد او برای تصفیه اوجاق را استوارتر کرد.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["گرفتن هرمز از پرتغالی‌ها", "93e5f6cf"], "d": ["نیروهای صفوی هرمز را که از 1515 در دست پرتغال بود محاصره و بازپس گرفتند؛ قشم و گمرون (بندر عباس) در ساحل نیز به اداره صفوی درآمد و تجارت خلیج فارس به بندر نو کشیده شد.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["خلع دوم مصطفی یکم و جلوس مراد چهارم", "1b3a9e74"], "d": ["مصطفی یکم که پس از قتل عثمان دوم برای بار دوم بر تخت نشانده شده بود، پس از یک سال و سه ماه دوباره برکنار شد و مراد چهارم یازده‌ساله پادشاه اعلام گردید. در نه سال نخست دولت عملاً به دست مادرش کوسم سلطان و بزرگان دربار اداره می‌شد. مراد چهارم از 1632 اداره را شخصاً در دست گرفت و دوران مرکزگرایی سختی را آغاز خواهد کرد.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["از دست رفتن بغداد به صفویان", "db81be0c"], "d": ["بکر صوباشی که در بغداد شورش کرده بود، پس از چانه‌زنی با صفویان، پسرش درویش محمد که از دژ درونی دفاع می‌کرد، شهر را به نیروهای شاه عباس تسلیم کرد. از دست رفتن یکی از شهرهای نمادین میراث خلافت و بخش بزرگ عراق در استانبول خشم بزرگی برانگیخت. بازپس‌گیری بغداد پانزده سال تنها هدف سیاست شرقی عثمانی خواهد بود.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["سرکوب شورش اباظه محمد پاشا با مرکزیت ارزروم", "e6da2729"], "d": ["اباظه محمد پاشا، بیلربیگی ارزروم، که به ادعای انتقام قتل عثمان دوم علیه ینی‌چریان شورید، سال‌ها آناتولی شرقی را زیر نظارت نگه داشت و در برابر مرکز ایستاد. با محاصره ارزروم به دست صدراعظم خسرو پاشا ناگزیر تسلیم شد، بخشوده شد و به بوسنی گماشته گردید. پایان شورش شرط پیشین رفتن مراد چهارم به لشکرکشی علیه ایران بود.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["نخستین اعدام شیخ‌الاسلام: اخی‌زاده حسین افندی", "a60a58c5"], "d": ["شیخ‌الاسلام اخی‌زاده حسین افندی با این بهانه که در آشوب نظامی میانجی‌گری کرده و به پادشاه در باب روش دادرسی هشداری مکتوب فرستاده بود، نزدیک بویوک‌چکمجه اعدام شد. نخستین شیخ‌الاسلام عثمانی بودن او که اعدام شد، سنت ریشه‌دار اینکه سنگین‌ترین مجازات اعضای علمیه تبعید بود را شکست. این رویداد نماد سخت شدن اقتدار مراد چهارم و برهم خوردن توازن دولت و علماست.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["فتح ایروان به دست مراد چهارم", "b65a9b73"], "d": ["مراد چهارم که در 28 مارس 1635 از استانبول حرکت کرد، در 28-29 ژوئیه ایروان را محاصره کرد و در 8 اوت قلعه را تسلیم گرفت؛ سپس وارد تبریز تخلیه‌شده شد و شهر را ویران کرد. پادشاه برای یادبود پیروزی در کاخ توپقاپی کوشک ایروان را ساخت. این لشکرکشی نخستین عملیات بزرگ شرقی پس از وقفه سی‌ساله بود که پادشاه شخصاً فرماندهی سپاه را بر عهده داشت.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["از دست رفتن ایروان به صفویان", "fbb8dd25"], "d": ["پس از عقب‌نشینی سپاه عثمانی، نیروهای شاه صفی ایروان را محاصره کردند و در هشت ماه بازپس گرفتند. از دست رفتن زودهنگام قلعه نشان داد فرمانروایی پایدار در قفقاز از نظر پشتیبانی چقدر دشوار است. ایروان با پیمان قصر شیرین 1639 نیز در ایران خواهد ماند و عثمانی از ادعای آذربایجان چشم خواهد پوشید.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["بازپس‌گیری بغداد", "4d2f27f3"], "d": ["مراد چهارم که در 8 مه 1638 از استانبول بیرون آمد، پس از محاصره‌ای سخت که چهل روز کشید بغداد را که پانزده سال در دست صفویان بود بازگرفت؛ در محاصره وزیر طیار محمد پاشا شهید شد. با فتح شهر اداره عثمانی در عراق از نو برپا شد و پادشاه عنوان «فاتح بغداد» را گرفت. فتح با پیمان قصر شیرین سال بعد پایدار شد و بنیاد مرز کنونی ترکیه و ایران را نهاد.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["مرگ مراد چهارم و جلوس سلطان ابراهیم", "e2ca1ca0"], "d": ["پس از مراد چهارم که در بیست و هفت‌سالگی (به شمار هجری بیست و هشت) مرد، برادرش ابراهیم، تنها عضو مرد بازمانده دودمان، بر تخت نشست. در سلطنت پادشاه تازه که سال‌ها در قفس زیسته بود، هزینه‌های دربار و کشمکش نفوذ درون کاخ نظم دولت را لرزاند. هشت سال بعد با خلع و کشته شدنش دومین قتل پادشاه در تاریخ عثمانی روی خواهد داد.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["بازپس‌گیری قلعه آزاق از قزاق‌ها", "e5fcf160"], "d": ["قلعه آزاق که قزاق‌های دن در 1637 گرفته بودند، در برابر عملیات مشترک سلطان‌زاده محمد پاشا و محمد گرای چهارم، خان کریمه، تخلیه شد؛ قزاق‌ها قلعه را آتش زده و عقب نشستند. بازپس‌گیری دروازه شمالی دریای سیاه دوران خطرناک رسیدن یورش‌های قزاق تا تنگه استانبول را بست. قلعه در 1696 این بار به تزار روس پتر یکم از دست خواهد رفت.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["آغاز لشکرکشی کرت و فتح خانیا", "a1b0c77f"], "d": ["به بهانه آنکه دزدان دریایی مالت کشتی حج عثمانی را زدند و به کرت پناه بردند به ونیز اعلان جنگ شد و ناوگانی به فرماندهی یوسف پاشا در جزیره نیرو پیاده کرد. پس از پنجاه و چهار روز محاصره قلعه خانیا گرفته شد و نخستین پایگاه پایدار عثمانی در کرت برپا گردید. بدین‌سان درازترین جنگ تاریخ عثمانی آغاز شد؛ جزیره تنها بیست و چهار سال بعد، در 1669، یکسره فتح خواهد شد.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["فتح رتیمنو — دو نیم شدن کرت", "8f2c4353"], "d": ["یک سال پس از گرفته شدن خانیا قلعه رتیمنو در بخش میانی جزیره نیز افتاد و نیمه باختری کرت یکسره به اداره عثمانی درآمد. در دست ونیز تنها پایتخت کاندیا و نوک خاوری ماند؛ جزیره بیست و سه سال دو نیم شده زیست. گرفتن رتیمنو گامی شد که محاصره کاندیا را آغاز کرد — درازترین محاصره تاریخ از اینجا آغاز شد.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["از دست رفتن کلیس به ونیز", "5473c22c"], "d": ["در جبهه دالماسیا در جنگ کرت (کاندیا)، ضدحمله فرمانده ونیزی لئوناردو فوسکولو کلیس را که از 1537 مرکز سنجق بود نیز دربرگرفت؛ قلعه به ونیز رسید. تمرکز عثمانی با همه نیرویش بر کرت، بازپس‌گیری این از دست رفتن در مرز دالماسیا را ناممکن کرد — کلیس دیگر به اداره عثمانی بازنخواهد گشت؛ مرکز سنجق به لیوونو برده شد.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["آغاز محاصره کاندیا", "13016b10"], "d": ["پس از گرفتن خانیا و رتیمنو سپاه عثمانی کاندیا، واپسین پایگاه بزرگ ونیز در جزیره، را به محاصره درآورد. این محاصره که بیست و یک سال خواهد کشید به‌عنوان یکی از درازترین محاصره‌های تاریخ نظامی جهان ثبت شد. در طول محاصره، کوشش‌های ناوگان ونیز برای بستن تنگه چاناق‌قلعه جنگ را به دل اژه خواهد کشاند.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["کشته شدن والده بزرگ کوسم سلطان", "9d763f79"], "d": ["کوسم سلطان، حدود شصت و دوساله، به فرمان تورهان سلطان، مادر محمد چهارم، به دست باش‌لالا اوزون سلیمان آغا و مردانش در اتاقی در حرم یافته و کشته شد. مرگ این بانوی نیرومند دودمان که در سه دوره پادشاهی سیاست دولت را هدایت می‌کرد، عملاً پایان دوران موسوم به «سلطنت زنان» شمرده می‌شود. اقتداری که خالی ماند راه را به سوی صدراعظم شدن کوپرولو محمد پاشا با اختیارات فوق‌العاده پنج سال بعد گشود.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["شکست چاناق‌قلعه و از دست رفتن بوزجاآدا و لمنوس", "e01a1f7e"], "d": ["پیروزی دریایی بزرگی که دریاسالار ونیزی موچنیگو در ژوئن 1656 در برابر تنگه چاناق‌قلعه به دست آورد ناوگان عثمانی را تقریباً یکسره نابود کرد؛ سپس بوزجاآدا، لمنوس و سموتراکی اشغال شد. با درآمدن تنگه به محاصره ونیز، بهای خوراک در استانبول بالا رفت و هراس از حمله به پایتخت پراکنده شد. این فاجعه علت بی‌واسطه گماشته شدن کوپرولو محمد پاشا در سپتامبر 1656 با اختیارات مشروط و فوق‌العاده به صدراعظمی شد.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["پیروزی چاناق‌قلعه و بازپس‌گیری بوزجاآدا", "603da863"], "d": ["ناوگانی که کوپرولو محمد پاشا بسیج کرده بود در 19 ژوئیه 1657 در برابر تنگه ناوگان ونیز را شکست داد؛ سپس نیروهایی به فرماندهی کورد پاشا در 25 اوت بوزجاآدا را بازپس گرفتند و در 30 اوت ونیزی‌ها جزیره را یکسره تخلیه کردند. در نوامبر لمنوس نیز رها شد، محاصره چاناق‌قلعه شکست و راه آذوقه استانبول دوباره گشوده شد. کوپرولو شخصاً به جزیره رفت و استحکامات را ترمیم کرد؛ این موفقیت نخستین دستاورد نظامی بزرگ دوران کوپرولوهاست.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["فتح یانووا (اینو) و لشکرکشی ارْدل", "d1089616"], "d": ["کوپرولو محمد پاشا برای کیفر دادن به گئورگ دوم راکوچی، شاهزاده ارْدل، که با رفتن بی‌اجازه به لشکرکشی لهستان حمایت عثمانی را زیر پا نهاده بود، به لشکرکشی رفت و از راه بلگراد پیشروی کرد و قلعه راهبردی یانووا را گرفت. برای ارْدل شاهزاده‌ای نو گماشته شد و پیوند دست‌نشاندگی به سختی یادآوری گردید. این لشکرکشی نخستین حلقه کوشش عثمانی برای برپایی دوباره اقتدار در اروپای میانه بود. ارْدل پیشتر شاهزاده‌نشینی تابع عثمانی بود؛ گرفتن یانووا فتح از دولتی بیگانه نبود بلکه بیرون آوردن این قلعه تابع ارْدل از اداره شاهزاده‌نشین و بستن مستقیم آن به سنجق عثمانی بود؛ باقی شاهزاده‌نشین در منزلت تابع ماند.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["سرکوب شورش اباظه حسن پاشا", "4ba74321"], "d": ["اباظه حسن پاشا که در برابر تصفیه‌های سخت کوپرولو محمد پاشا بیلربیگی‌های آناتولی و آغاهای سکبان را پشت سر خود داشت، با خواست عزل صدراعظم شورشی بزرگ آغاز کرد. شورش در حلب سرکوب و سران آن از میان برداشته شدند؛ این واپسین مقاومت جمعی پاشاهای ولایات در برابر مرکز بود. اقتدار کوپرولو بدین‌سان بی‌چون‌وچرا شد و مقام صدارت دوباره به مرکز راستین اجرایی دولت بالا رفت.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["فتح وارد (اورادیا)", "0e6ad300"], "d": ["در چارچوب لشکرکشی علیه گئورگ دوم راکوچی، شاهزاده ارْدل، که به عثمانی اعلان جنگ کرده بود، قلعه و شهر وارد گرفته شد. با سقوط یکی از قلعه‌های کلیدی ارْدل، ایالتی تازه از عثمانی (ایالت وارد) در منطقه برپا شد. فتح هابسبورگ‌ها را هشیار کرد و از دلایل بی‌واسطه جنگ عثمانی و اتریش شد که سه سال بعد آغاز می‌گشت. جاهای دیگری که در همین تاریخ پیوستند: وارات. اینجا نیز سرزمین از دولتی بیگانه گرفته نشد: ارْدل پیشتر شاهزاده‌نشینی تابع عثمانی بود؛ ایالت شدن وارد تنها اداره این شهر را از شاهزاده‌نشین تابع گرفت و مستقیماً به پادشاه بست، همان‌گونه که دو سال پیش در یانووا شد.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["نبرد سن‌گوتهارد (سنت گوتهارد)", "61ebc1f2"], "d": ["نیروهای عثمانی که از رود رآب گذشته بودند، به دست سپاه متحد اروپایی به فرماندهی مونته‌کوکولی متوقف شدند و تلفات سنگین دادند. این نبرد از آن رو در تاریخ نظامی نقطه عطف شمرده می‌شود که برتری آتش تفنگ پیاده‌نظام منضبط را در برابر یورش سواره‌نظام عثمانی نخستین بار آشکارا نشان داد. با وجود شکست، عثمانی توانست در پیمان واسوار که نه روز بعد امضا شد شرایطی سودمند به دست آورد.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["پیمان واسوار", "089c978c"], "d": ["پیمانی که با وجود شکست سن‌گوتهارد امضا شد، ماندن اویوار و وارد در دست عثمانی، بی‌طرف گذاشته شدن ارْدل زیر حمایت عثمانی و پرداخت «هدیه» 200.000 غروش از سوی اتریش را مقرر کرد. این صلح بیست‌ساله از نمونه‌های کمیاب بردن طرف بازنده بر سر میز است. نارضایتی‌ای که پیمان در افکار عمومی هابسبورگ پدید آورد جنبش مجارستان میانه و به‌طور غیرمستقیم لشکرکشی وین 1683 را تغذیه خواهد کرد.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["آغاز اداره دایی در الجزایر", "e99faa51"], "d": ["اوجاق الجزایر و طایفهٔ رئیس‌ها (کاپیتان‌های دزد دریایی) آخرین آغا را عزل کردند و حاج محمد را به شرط حیات به دایی برگزیدند. از این تاریخ الجزایر را نه بیلربیگی که استانبول می‌گماشت بلکه دایی‌ای که اوجاق محلی از درون خود برمی‌گزید اداره می‌کرد؛ پیوند عثمانی به خواندن نام سلطان در خطبه، سنجق و تعهد لشکرکشی محدود ماند. الجزایر بدین‌سان از ایالت به اوجاقلق بدل شد — همین دگرگونی را تونس در 1705 با حسینیان و طرابلس غرب در 1711 با قرمانلی‌ها گذراند.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["آغاز لشکرکشی لهستان — محمد چهارم و فاضل احمد پاشا در رأس سپاه", "75e15a39"], "d": ["چون یورش‌های لهستان علیه پترو دوروشنکو، هتمان اوکراین که زیر حمایت عثمانی درآمده بود، ادامه یافت، استانبول از پادشاه لهستان خواست از حمله‌ها دست بردارد؛ چون پاسخ مثبتی نیامد تصمیم لشکرکشی به لهستان گرفته شد. صدراعظم فاضل احمد پاشا با سپاهی که پادشاه نیز در آن بود در 4 ژوئن 1672 به سوی لهستان حرکت کرد. لشکرکشی به فتح کامیانیتس و پیمان بوچاچ می‌انجامید.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["فتح کامیانیتس و برپایی ایالت پودولیا", "c3f4f6d0"], "d": ["پس از محاصره‌ای نه‌روزه کامیانیتس، که نیرومندترین قلعه شرقی لهستان شمرده می‌شد، تسلیم گرفته شد؛ محمد چهارم در 2 سپتامبر در مسجدی که از کلیسای جامع برگردانده شده بود نخستین نماز جمعه را گزارد. با مرکز قرار دادن قلعه، ایالت پودولیا برپا شد و پرچم عثمانی در خاک اوکراین امروزی به شمالی‌ترین نقطه خود رسید. کامیانیتس تا پیمان کارلوویتس 1699 نقطه شمال‌باختری امپراتوری باقی خواهد ماند.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["قره‌مصطفی پاشا اومان را از لهستان تسلیم گرفت", "0d3543a0"], "d": ["قره‌مصطفی پاشا که علیه لهستان فرستاده شده بود اومان را که از قلعه‌های دست لهستان بود تسلیم گرفت؛ شهر تا کارلوویتس در اداره عثمانی ماند.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["فتح قلعه چهرین", "a17cedd0"], "d": ["پس از لشکرکشی سال پیش ملک ابراهیم پاشا که به نتیجه نرسید، صدراعظم مرزیفونلو قره‌مصطفی پاشا شخصاً فرماندهی کرد و قلعه مستحکم چهرین را محاصره کرد (19/21 ژوئیه) و در 21 اوت گرفت. سقوط قلعه‌ای که نماد رقابت عثمانی و روس بر سر هتمان‌نشین قزاق در اوکراین بود، روسیه را به صلح واداشت. این موفقیت یکی از سرچشمه‌های اعتماد به نفس مرزیفونلو بود که رو به وین خواهد آورد.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["پیمان باغچه‌سرای — نخستین صلح رسمی با روسیه", "df82bc0b"], "d": ["در پایان گفتگوهایی که پس از لشکرکشی‌های چهرین با میانجی‌گری خان کریمه انجام شد، با پذیرفتن رود اوزی (دنیپر) به‌عنوان مرز، صلحی بیست‌ساله میان دولت عثمانی و روسیه امضا شد. این سند از آن رو که نخستین پیمان فراگیر میان دو دولت است، سند آغازین روابط عثمانی و روس شمرده می‌شود. با این صلح جبهه شرقی ایمن شد و سپاه توانست به اروپای میانه هدایت شود.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["دادن برات پادشاهی مجارستان میانه به تکلی ایمره", "3cd8d51d"], "d": ["تکلی ایمره، اشراف‌زاده پروتستان مجار که علیه فشار هابسبورگ شورید، از آوریل 1682 «پادشاه برگزیده مجارستان میانه» شمرده شد و در 16 سپتامبر ابراهیم پاشا، بیلربیگی بودین، نشانه‌های شاهزادگی را به او تقدیم کرد. بدین‌سان دولت مجار دست‌نشانده‌ای نو زیر حمایت عثمانی برپا شد. این دخالت جنگ با اتریش را ناگزیر کرد و زنجیره‌ای را که به محاصره دوم وین در سال بعد می‌رسید آغاز کرد.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["از دست رفتن آیامورا (لفکاده) به ونیز", "e6905fee"], "d": ["ناوگان ونیز که به اتحاد مقدس پیوسته بود، پس از به توپ بستن شهر جزیره آیامورا در دریای ایونی را اشغال کرد. در همان سال با سقوط پروزه نیز نظارت عثمانی بر دهانه آدریاتیک شکست. این زیان‌ها گام‌های آغازین عملیاتی بود که موروزینی در سه سال همه موره را با آن می‌گرفت.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["از دست رفتن کورون به ونیز", "2ed762bc"], "d": ["نیروهای ونیز به فرماندهی موروزینی قلعه کورون را در جنوب‌باختری‌ترین نقطه شبه‌جزیره موره گرفتند؛ شهر از آن پس سی سال زیر اداره ونیز ماند. سقوط کورون نخستین دستاورد بزرگ عملیات ونیز برای فتح موره بود. قلعه تنها در 1715 به دست سپاه عثمانی به فرماندهی سیلاحدار علی‌پاشا بازپس گرفته شد.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["بازپس‌گیری آتن — عقب‌نشینی ونیز", "03393b46"], "d": ["موروزینی که در سپتامبر 1687 آکروپولیس را بمباران کرد و پارتنون را به هوا برد، پس از گذراندن زمستان در آتن دریافت نمی‌تواند در شهر پا بگیرد. با همه‌گیری طاعون، دشواری تدارکات و جان گرفتن دوباره نیروهای عثمانی، پادگان ونیز شهر را تخلیه کرد و به موره عقب نشست. آتن بدین‌سان بی‌جنگ به اداره عثمانی بازگشت، اما ویرانی‌ای که به پارتنون رسیده بود جبران نشد.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["لیپووا (Lippa) به کارافا تسلیم شد — به دست اتریش افتاد", "7f0a8d38"], "d": ["پس از محاصره سه‌روزه آنتونیو کارافا، لیپووا میان ۱۲ تا ۲۲ ژوئن ۱۶۸۸ تسلیم شد و به دست اتریش افتاد. عثمانیان بعدها شهر را بازپس گرفتند، اتریش در ۱۶۹۱ دوباره آن را گرفت؛ در لشکرکشی ۱۶۹۵ عثمانی دوباره کنترل را به دست آورد. سایر سکونتگاه‌هایی که در همین تاریخ در اطلس از عثمانی به هابسبورگ رسیدند: آراد و ویلاگوش (شیریا). برای آراد منبع تنها سال را می‌دهد (MKL، آراد: میان ۱۵۵۱ تا ۱۶۸۸ در دست عثمانی)؛ روز از لیپووا گرفته شده است و ویلاگوش زنجیره آراد را دنبال می‌کند (تقریب اعلام‌شده). دژهای لوگوش (Lugoj) و کارانشبش (Caransebeş) نیز در پایان ژوئن به اتریش رسیدند (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'؛ 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["دفع محاصره اغریبوز به دست ونیز", "aae7e6a0"], "d": ["موروزینی که پس از گرفتن موره به اژه روی آورده بود، با محاصره‌ای بیش از سه ماه کوشید اغریبوز را بگیرد؛ اما در برابر استحکاماتی که در زمستان 1687-1688 تقویت شده بود و ایستادگی پادگان با تلفات سنگین ناگزیر عقب نشست. این ناکامی پیشروی ونیز را در اژه متوقف کرد و اعتبار نظامی موروزینی را لرزاند. اغریبوز در کارلوویتس نیز در دست عثمانی خواهد ماند.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["از دست رفتن قلعه قانیزسا به اتریش", "553b45f3"], "d": ["قانیزسا که از ژانویه 1690 در محاصره سخت سپاه 60.000 نفره هابسبورگ بود، پس از ماه‌ها ایستادگی بی‌دریافت یاری، با توافق تسلیمی که واپسین نگهبان آن مصطفی پاشا امضا کرد از دست رفت. بدین‌سان فرمانروایی نودساله عثمانی در قلعه‌ای که با دفاع حماسی تیریاکی حسن پاشا یاد می‌شود پایان یافت. از دست رفتن قانیزسا فروپاشی واپسین پایگاه بزرگ عثمانی در باختر مجارستان بود.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["درگذشت سلیمان دوم", "d2478080"], "d": ["سلیمان دوم که پس از حدود چهل سال زندگی در قفس در 1687 بر تخت نشانده شده بود، در حالی که بیمار بود و آمادگی‌های سپاه را می‌نگریست، روز جمعه 22 ژوئن 1691 نزدیک ظهر در ادرنه درگذشت؛ سلطنتش سه سال و هشت ماه و دو روز بود. صدراعظم پیشاپیش دستور لازم را برای آنکه در صورت مرگ پادشاه برادرش احمد بر تخت نشانده شود داده بود. نماز جنازه همان روز در عمارت آلای کوشکی خوانده شد؛ پیکرش به استانبول آورده شد و در آرامگاه سلطان سلیمان قانونی در سمت راست او به خاک سپرده شد.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["جلوس احمد دوم", "52947b14"], "d": ["با مرگ سلیمان دوم، برادرش احمد دوم چهل و نه‌ساله در ادرنه بر تخت نشست. سلطنتش با سنگین‌ترین سال‌های جنگ‌های اتحاد مقدس همزمان شد؛ دو ماه پس از جلوس در سالانکمن صدراعظم فاضل مصطفی پاشا شهید شد. در برابر آن، نظام مالکانه که در دوران او به اجرا گذاشته شد، از مهم‌ترین تدبیرهایی بود که ساختار درازمدت دارایی عثمانی را دگرگون کرد.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["درگذشت محمد چهارم در ادرنه", "17388b7e"], "d": ["محمد شکارچی که در 1687 از تخت برکنار شده بود، هنگام لشکرکشی مجارستان سلیمان دوم در 1689 به ادرنه آورده شد و سلطنت برادر دیگرش احمد دوم را نیز دید. او در این شهر که بسیار دوست می‌داشت درگذشت. پیکرش به استانبول آورده شد و در آرامگاه مادرش تورهان سلطان در کنار ینی‌جامی به خاک سپرده شد.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["درگذشت احمد دوم در ادرنه", "c6306c08"], "d": ["احمد دوم که سلطنت چهار ساله‌اش در جنگ گذشت، در پنجاه و دو سالگی بر اثر استسقاء (ورم) در ادرنه درگذشت. پیکرش به استانبول آورده شد و در آرامگاه سلطان سلیمان قانونی به خاک سپرده شد. برادرزاده‌اش مصطفی دوم جانشین او شد.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["تصرف بصره به دست ایرانیان", "a9cdf3a3"], "d": ["در حالی که دولت عثمانی در باختر درگیر جنگ‌های اتحاد مقدس بود، بصره پس از همه‌گیری طاعون 1690 نخست از سوی شیخ منتفک مانع و سپس فرج‌الله، خان حویزه، مورد غارت قرار گرفته بود. ایرانیان با بهره‌گیری از این آشفتگی در 1696 شهر را گرفتند و نگهبانی در بصره گذاشتند.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["پیمان استانبول — واگذاری آزاق به روسیه", "79db4724"], "d": ["در کارلوویتس با روسیه تنها آتش‌بس دوساله ممکن شده بود؛ صلح پایدار در استانبول پس از چانه‌زنی‌های سخت یک سال و نیمه امضا شد. دولت عثمانی قلعه آزاق را که در 1696 از دست داده بود و سرزمین‌های پیرامون آن را رسماً به روسیه واگذاشت و از مالیات سالانه‌ای که خان کریمه از مسکو می‌گرفت چشم پوشید. در برابر آن روسیه حق داشتن سفیر دائمی در استانبول را به دست آورد؛ بدین‌سان حضور روس در ساحل شمالی دریای سیاه از نظر حقوقی ثبت شد.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["بازپس‌گیری قرنه و بصره به دست دالتابان مصطفی پاشا", "7adb777d"], "d": ["دالتابان مصطفی پاشا که پس از پیمان کارلوویتس به والی‌گری بغداد و سرعسکری بصره گماشته شد، با نیروهای حلب، رقه، سیواس و قرامان و ناوگان رودخانه‌ای که از بیره‌جیک فرود آمد به سوی جنوب لشکر کشید. شیخان قبایل پیرامون یکی‌یکی فرمانبری کردند، داود خان، نگهبان ایرانی بصره، شهر را ترک کرد و قرنه و بصره دوباره به اداره عثمانی درآمد.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["درگذشت مصطفی دوم", "626c394d"], "d": ["مصطفی دوم که با واقعهٔ ادرنه تخت را به برادرش احمد سوم واگذاشت، حدود پنج ماه پس از برکناری در ادرنه که بسیار دوست می‌داشت درگذشت. اندوه رویدادهای اخیر نیز بر بیماری‌اش افزوده بود. برخی منابع غربی می‌نویسند در میان مردم این باور رواج داشت که او مسموم شده است.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["آغاز اداره کولمن (ممالیک) در بغداد", "abe52618"], "d": ["با گماشته شدن حسن پاشا، گرجی‌تبار، به والی‌گری بغداد، دورانی آغاز شد که در عراق به جای والیان منصوب مرکز، طبقه‌ای حاکم که از میان بردگان خود پرورده بود چیره شد. با والی‌گری سلیمان پاشا در 1749 این نظام کاملاً جا افتاد و باب‌عالی دیگر ناگزیر نبود هر که را می‌خواهد بگمارد، بلکه باید یکی از کولمن‌هایی را که نفوذ را به دست گرفته بودند منصوب می‌کرد. این ساختار نیمه‌خودگردان هرچند در دفاع مرز ایران سودمند بود، نظارت اقتدار مرکزی بر عراق را یک سده و نیم ضعیف کرد.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["بنیان‌گذاری دودمان حسینی در تونس", "cb1a98f9"], "d": ["در خلأ اقتداری که با حمله نیروهای الجزایر به تونس پدید آمد، حسین بن علی، آغای سپاهی ترک‌تبار، بیگی را به دست گرفت و با اعلام بستگی به پادشاه عثمانی مشروعیت یافت. دودمانی که بنیان نهاد در سال‌های 1705-1735 و 1756-1957 تونس را اداره کرد؛ نظام بیگی که از پدر به پسر می‌گذشت جای اداره اوجاق را گرفت. بدین‌سان نخستین نمونه ساختارهای دودمانی وابسته به مرکز اما عملاً خودگردان در اوجاق‌های غرب پدید آمد.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["گرفتن وهران و مرسی‌الکبیر از اسپانیایی‌ها", "b67ce06a"], "d": ["نیروهای بیلربیگی اوجاق الجزایر وهران را که دو سده در دست پادگان اسپانیا بود و بندر مرسی‌الکبیر را پس از محاصره‌ای دراز گرفتند. این بزرگ‌ترین موفقیتی بود که اوجاق‌های غرب زیر حمایت عثمانی در مدیترانه باختری علیه اسپانیا به دست آوردند و جناح غربی الجزایر را ایمن کرد. شهر در 1732 دوباره اشغال اسپانیا خواهد شد، اما در 1792 برای همیشه بازپس گرفته می‌شود.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["پیمان پروت — بازپس‌گیری آزاق و تاگانروگ", "bac5d2a1"], "d": ["پیمان هفت‌مادّه‌ای که با تسلیم سپاه روس در محاصره کنار پروت امضا شد، بازگردانده شدن قلعه آزاق را همراه با زمین و مهمات به عثمانی مقرر داشت. استحکامات تاگانروگ، کامنکا و ینی‌قلعه ویران خواهد شد و طرفین در این مناطق قلعه نو نخواهند ساخت. نظام ناوگان و پایگاهی که پتر یکم شانزده سال در وورونژ و آزاق برپا کرده بود فروریخت؛ فرود روسیه به دریای سیاه حدود پنجاه سال به تأخیر افتاد.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["بنیان‌گذاری دودمان قره‌مانلی در طرابلس غرب", "e1105d4a"], "d": ["در طرابلس غرب که از کشمکش آغاهای اوجاق به ستوه آمده بود، افسر سواره احمد قره‌مانلی اداره را به دست گرفت و با برات بیلربیگی‌ای که از استانبول گرفت وضع خود را رسمی کرد. با دست احمد پاشا، پسرش محمد پاشا و نوه‌اش یوسف پاشا دودمانی پدید آمد که میان 1711-1835 ادامه یافت؛ ساختاری نیمه‌مستقل که ناوگان خود را برپا می‌کرد و با دولت‌های اروپایی مستقیماً پیمان می‌بست پدید آمد. این دوران تنها در 1835 با پیوستن مستقیم ایالت به مرکز پایان خواهد یافت.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["پیمان ادرنه با روسیه", "14901a70"], "d": ["چون وعده‌های پروت ادا نشد دو بار دیگر اعلان جنگ شده بود و سرانجام با پذیرفتن تعهدات از سوی روس‌ها صلح پایدار در ادرنه امضا شد. پیمان شرایط پروت را تأیید کرد؛ روسیه در امور لهستان دخالت نمی‌کرد، از سرزمین‌های قزاق عقب می‌نشست و مانع بازگشت شارل دوازدهم، پادشاه سوئد، به کشورش نمی‌شد. بسته شدن جبهه شمالی بدین‌سان ممکن کرد که دولت عثمانی روی خود را به جبهه موره و ونیز بگرداند. جاهای دیگری که در همین تاریخ پیوستند: خوتین.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["اعلان جنگ به ونیز — تدارک لشکرکشی موره", "d970b122"], "d": ["با دستاویز اینکه ونیز از شورشیان مونته‌نگرو پشتیبانی می‌کرد، کشتی‌های بازرگانی عثمانی را مصادره کرد و موره را که در کارلوویتس گرفته بود با مالیات‌های سنگین می‌فشرد، در دیوان تصمیم جنگ گرفته شد. لشکرکشی‌ای که صدراعظم سیلاحدار داماد علی‌پاشا تدارک دید، سال بعد در کمتر از صد روز به بازپس‌گیری همه شبه‌جزیره موره می‌انجامید. اما این موفقیت اتریش را به حرکت می‌آورد و در 1716 درِ جنگی بسیار سنگین‌تر را می‌گشود.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["استندیل (تینوس): تسلیم واپسین جزیره ونیز در اژه", "4abec891"], "d": ["ناوگانی که به لشکرکشی موره می‌رفت، در راه در برابر استندیل، تنها جزیره‌ای که در اژه در دست ونیز مانده بود، لنگر انداخت. جزیره‌ای که با وجود سقوط دوک‌نشین ناکسوس در 1566 به برکت جمعیت لاتینی‌اش صد و پنجاه سال دیگر پرچم ونیز را داشت، پس از محاصره‌ای کوتاه بی‌خون‌ریزی تسلیم شد. بدین‌سان واپسین ردپای ونیز در دریای اژه زدوده شد و دریا یکسره به دریای درونی عثمانی بدل گشت.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["فتح آنابولی — قلعه کلیدی موره", "62a5808a"], "d": ["آنابولی، پایتخت ونیز در موره و نیرومندترین استحکام آن، با گرفته شدن باروی پالامیدی پس از نه روز بمباران سقوط کرد. چنین زود گرفته شدن قلعه مقاومت را در باقی شبه‌جزیره شکست. بازپس‌گیری موره که در کارلوویتس از دست رفته بود عملاً اینجا تکمیل شد. در همین تاریخ در اطلس سکونتگاه دیگری که از ونیز به عثمانی می‌رسد: Argos — از زنجیره ابی‌مرکز آنابولی پیروی می‌کند (TDV anabolu؛ تقریب با بیان).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["تسلیم مودون", "43faa909"], "d": ["پس از سقوط آنابولی قلعه مودون در جنوب‌باختری‌ترین نقطه موره، از خشکی با سپاه و از دریا با ناوگان محاصره شد و زود تسلیم گشت. این بندر که ونیز در لشکرکشی‌های مدیترانه شرقی دو سده به کار می‌برد، منزلگاه ناگزیر کشتی‌ها برای گرفتن آب و آذوقه بود. از دست رفتنش توان جابه‌جایی ناوگان ونیز را در اژه پایان داد.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["تسلیم کورون — پایان لشکرکشی موره", "e4b9c8a4"], "d": ["با تسلیم قلعهٔ کورون که دهانهٔ خلیج مسینیا را در اختیار داشت، فرمانروایی ونیز بر شبه‌جزیرهٔ موره به‌کلی پایان یافت. شبه‌جزیره‌ای که در کارلوفچا از دست رفته بود، تنها سه ماه پس از آغاز لشکرکشی یکسره بازگردانده شد. در ادامهٔ همین لشکرکشی، در سپتامبر 1715 جزیرهٔ ایامائورا (لفکاده) در دریای ایونی نیز از ونیز گرفته شد. این سرعت ونیز را ناگزیر کرد که اتریش را به جنگ بکشاند و سه سال بعد راه به‌سوی پاساروفچا گشوده شد.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["تصرف جزیرهٔ چوها (کیترا)", "494de6c6"], "d": ["جزیرهٔ چوها در جنوبی‌ترین نقطهٔ موره، پس از تکمیل تصرف شبه‌جزیره، به‌دست ناوگان تسلیم گرفته شد. این جزیره که گذرگاه میان دریای ایونی و دریای اژه را زیر نظر داشت، پاسگاه پیشرفتهٔ ونیز برای نظارت بر این آب‌ها بود. با این همه، تنها جزیرهٔ در دست عثمانی باقی نماند: سه سال بعد در پاساروفچا به ونیز بازگردانده شد.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["اتحاد اتریش و ونیز — درِ جنگ عثمانی و اتریش 1716-1718", "99511ca2"], "d": ["پس از بازپس‌گیری موره از ونیز به دست عثمانی، اتریش با این ادعا که پیمان کارلوویتس نقض شده با ونیز پیمان اتحاد امضا کرد؛ شاهزاده اوژن در نامه‌ای به صدراعظم بازگردانده شدن جاهای گرفته‌شده از ونیز را خواست. در رایزنی در اردوگاه داود‌پاشا به فشار صدراعظم علی‌پاشا به اتریش اعلان جنگ شد و برای آن از شیخ‌الاسلام فتوا گرفته شد.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["صدراعظم علی‌پاشا به لشکرکشی اتریش رفت", "2fbdce42"], "d": ["پس از اعلان جنگ به اتریش، سردار اکرم علی‌پاشا با سپاهی بیش از 100.000 نفر به لشکرکشی اتریش رفت؛ ناوگان نیز همان تابستان رو به کورفو آورد. سپاه از بلگراد بر وارادین خواهد تاخت و در شکست آغاز اوت صدراعظم شهید خواهد شد.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["شکست وارادین (پتروارادین) — شهادت داماد علی‌پاشا", "265c1d81"], "d": ["سپاه عثمانی که از راه بلگراد از دانوب گذشته بود، در برابر وارادین با نیروهای اتریش به فرماندهی شاهزاده اوژن روبه‌رو شد؛ در نخستین یورش، هجوم ینی‌چریان سنگرهای دشمن را به تنگنا آورد، اما با فروریختن جناح سواره صف‌ها از هم پاشید. صدراعظم سیلاحدار داماد علی‌پاشا با تیری به پیشانی شهید شد و اردوگاه و توپخانه یکسره به دست دشمن افتاد. این شکست که وقایع‌نامه‌های عثمانی آن را «سال وارادین» می‌نامند، نخستین حلقه زنجیره‌ای بود که به از دست رفتن تمشوار و در سال بعد بلگراد می‌رسید.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["ناکامی محاصره کورفو", "b2aa7011"], "d": ["قره‌مصطفی پاشا، سرعسکر موره، از خشکی و قاپودان دریا جانم‌خواجه محمد پاشا از دریا بر کورفو تاختند؛ جزیره پایگاه کلیدی ونیز در آدریاتیک بود. اما استحکامات بسیار نیرومند قلعه، نیروهای کمکی که ناوگان ونیز آورد و خبر شکست از جبهه دانوب به برداشته شدن محاصره انجامید. گرفته نشدن کورفو فضای برخاسته از فتح دوباره موره را فرونشاند و مرکز ثقل جنگ را به مجارستان جابه‌جا کرد.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["از دست رفتن تمشوار (تیمیشوآرا) به اتریش", "27fe1365"], "d": ["پس از شکست وارادین شاهزاده اوژن مستقیماً بر تمشوار تاخت و قلعه پس از محاصره‌ای بیش از چهل روز با قرارداد تسلیم شد. شهری که در 1552 در روزگار قانونی فتح شده و 164 سال به‌عنوان مرکز بیلربیگی ستون شرقی دفاع مجارستان شمرده می‌شد، بدین‌سان از دست رفت. با سقوط تمشوار سراسر منطقه بانات به اتریش رسید و مرز عثمانی به جنوب دانوب رانده شد. در همین تاریخ در اطلس سکونتگاه‌های دیگری که از عثمانی به هابسبورگ می‌رسند: Csákóvár، Facset و Karánşebeş (کارانسبش — Caransebeş) — همراه با پایان کار ایالت تمشوار (TDV timisvar؛ روز در سطح سکونتگاه در منبع نیست، زنجیره ابی‌مرکز، تقریب با بیان).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["تسلیم قلعه هارام (یئنی پالانکا) به اتریش — ساحل دانوب بانات از دست رفت", "38ee4c6d"], "d": ["ژنرال سواره‌نظام اتریشی مرسی که پس از سقوط تمشوار مأمور گرفتن بقیه بانات بود، در 14 نوامبر بر هارام (یئنی پالانکا) در ساحل دانوب تاخت؛ چون در 16 نوامبر به قلعه رسید، پادگان 200 نفره عثمانی با برافراشتن پرچم سفید و به شرط عقب‌نشینی آزادانه تسلیم شد. بدین‌سان خط دانوب بانات جنوبی که از 1552 در دست عثمانی بود نیز به اتریش رسید. در همین تاریخ در اطلس سکونتگاه دیگری که از عثمانی به هابسبورگ می‌رسد: Versec — از زنجیره ابی‌مرکز هارام پیروی می‌کند (بانلاکی 0019/1703؛ تقریب با بیان).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["پیمان پاساروفچا — موره به دست آمد، بلگراد و بانات از دست رفت", "d46aa216"], "d": ["موره از ونیز بازپس گرفته شده بود، اما اتریش که وارد جنگ شد با پیروزی‌های خود در پتروارادین و بلگراد در میز مذاکره برتری یافت. پیمانی که با میانجیگری انگلستان و هلند امضا شد، موره را در دست عثمانی گذاشت، ولی در برابر آن، شمال صربستان، بانات و والاکی کوچک همراه با بلگراد به اتریش واگذار شد؛ به تعبیر TDV «شمال بوسنی یکسره به اتریش واگذار شده است» — قلعه‌هایی مانند بوسنی دوبیچا و بوسنی برود در کنار ساوا از همین روز در نقشه به اتریش می‌گذرد (مرز دقیق را کمیسرها یک‌به‌یک ترسیم کردند، TDV این قلعه‌ها را به نام نمی‌شمارد)؛ ونیز نیز موضع‌هایش در ساحل ایونی مانند پروزه و چوها را حفظ کرد. با عهدنامهٔ تجاری امضاشده در همان روز، عوارض گمرکی کالاهای اتریشی از پنج درصد به سه درصد کاهش یافت. این پیمان، ضمن ثبت عقب‌نشینی دولت عثمانی در اروپای مرکزی، صلح بیست‌وهفت‌ساله‌ای را گشود که زمینهٔ دورهٔ لاله (1718-1730) شد: نخستین چاپخانهٔ عثمانی (1727، ابراهیم متفرقه) در دورهٔ صدارت داماد ابراهیم پاشا نوشهری، هیئت‌های ترجمه، مشاهدات واکسن آبله و زندگی نوین درباری-فرهنگی از دستاوردهای این سال‌های صلح است. سکونتگاه‌های دیگری که در همان روز در اطلس دست‌به‌دست می‌شوند: کرایووا (Craiova)، ریمنیک (Râmnicu Vâlcea) و تورنو سورین (والاکی کوچک/اولتنیا، از عثمانی به اتریش) و نیز ایامائورا (لفکاده) (از عثمانی به ونیز؛ TDV ayamavra: در 1718 با پیمان پاساروفچا جزیره به ونیز واگذار شد). در والاکی کوچک همچنین تیرگو ژیو به اتریش؛ ووینیتسا (TDV pasarofca-antlasmasi) و جزیرهٔ چوها (کیترا، TDV cuka-adasi: ماده 3 پاساروفچا) به ونیز می‌رسد.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["لشکرکشی شرق: گرفتن تفلیس و آغاز جنگ ایران", "78343dc2"], "d": ["با فروپاشی دولت صفوی بر اثر هجوم افغان و فرود روسیه به سواحل خزر، دولت عثمانی برای آنکه خلأ یکسره به نفوذ روس نیفتد سپاه به شرق فرستاد. با گرفتن تفلیس گرجستان به اداره عثمانی پیوست؛ سپس پیشروی به سوی گنجه، ایروان و نخجوان ادامه یافت. این لشکرکشی که در پس ظاهر صلح‌آمیز دوران لاله انجام شد، آغاز ماجرایی دراز در شرق بود که سیزده سال خواهد کشید و سرانجام با بازگرداندن همه جاهای به دست‌آمده پایان می‌یافت.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["لشکرکشی ایران 1723: ورود به شیروان و گرجستان", "c81189fc"], "d": ["با فروپاشی دولت صفوی بر اثر حملهٔ افغان‌ها و به بهانهٔ جلوگیری از فرود روسیه در سواحل خزر، لشکرکشی به شرق آغاز شد. سپاه ارزروم از راه گرجستان به تفلیس و شاخهٔ شیروان به شماخی وارد شد و سرزمین‌هایی را که یکصد و سی سال پیش از دست رفته بود بازپس گرفت. این لشکرکشی واپسین پیشروی بزرگ عثمانی در قفقاز بود.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["تصرف کرمانشاه — دروازهٔ زاگرس", "ad14799f"], "d": ["سپاه بغداد با عبور از گذرگاه‌های زاگرس کرمانشاه را که دروازهٔ غربی ایران شمرده می‌شد گرفت. این شهر بر سر راه کاروان‌ها و سپاهیان از بغداد به اصفهان بود و تصرف آن امنیت شرقی ایالت عراق را تأمین می‌کرد. این پیشروی، رقابت عثمانی و روسیه را برای تقسیم قلمرو پراکندهٔ صفوی آغاز کرد.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["مقاسمه‌نامه استانبول — تقسیم ایران با روسیه", "fce8eec2"], "d": ["برای جلوگیری از رویارویی عثمانی و روسیه بر سر سرزمین فروپاشیده صفوی، با میانجی‌گری سفیر فرانسه پیمان تقسیمی امضا شد. کرانه‌های باختری و جنوبی دریای خزر به روسیه و گرجستان، شیروان، آذربایجان و شهرهای ایران غربی به دولت عثمانی واگذار شد. این تقسیم که بر کاغذ دستاوردی بزرگ می‌نمود، به‌زودی با برآمدن نادرشاه عملاً بی‌اعتبار می‌شد. بنا بر پیمان، سرزمین‌های حاصلخیز شیروان مانند شابران و مشکور در سوی روسیه گذاشته شد (چایجی‌اوغلو، DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["تصرف نخجوان", "bdf14d0a"], "d": ["نیروهای عثمانی که در امتداد ارس پیش می‌رفتند نخجوان و اردوباد را گرفتند؛ جلفا نیز به لوای نخجوان پیوست. این شهر به‌عنوان دروازهٔ شمال‌غربی ایران به ایالت تازه‌تأسیس ایروان وابسته شد. بدین‌سان مرز عثمانی دوباره به شرقی‌ترین خط دورهٔ قانونی رسید.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["فتح همدان", "e1339a97"], "d": ["سپاهی که از کرمانشاه به‌سوی شرق راه می‌سپرد، همدان را در آستانهٔ باختری فلات ایران پس از محاصره‌ای طولانی گرفت. این شهر واپسین منزل بزرگ راه اصفهان بود و شرقی‌ترین نقطه‌ای بود که سپاهیان عثمانی از زمان لشکرکشی عراقین بدان رسیده بودند. معاهدهٔ استانبول که در همان سال با روسیه امضا شد، تقسیم ایرانِ پراکنده را میان عثمانی و روسیه بر کاغذ آورد.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["فتح دوبارهٔ ایروان", "88acabef"], "d": ["پس از محاصره‌ای سخت به مدت نود روز، قلعهٔ کلیدی دره ارس، ایروان، دوباره به اداره عثمانی درآمد. قلعه‌ای که در 1583 ساخته و در 1604 از دست رفته بود این بار با پادگانی نیرومندتر استحکام یافت. درازای محاصره نشانهٔ آن بود که سپاه عثمانی دیگر به آسانی پیش نمی‌رفت. نواحی کارپی (اوچ‌کیلیسه)، شرور، ماکو و شورگل نیز به ایالت ایروان پیوست.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["گرفتن تبریز — تصرف آذربایجان", "e502a4f7"], "d": ["تبریز که پس از کوشش ناکام سال پیش دوباره محاصره شد، پس از نبردی سخت که کوچه‌به‌کوچه ادامه داشت به سپاه عثمانی تسلیم شد. مرند، مراغه و سووق‌بلاغ (مهاباد) وابسته به ایالت تبریز نیز به اداره عثمانی درآمد. همان سال لوری، گنجه، اردبیل و خرم‌آباد نیز گرفته شد و مناطقی که بنا بر مقاسمه‌نامه استانبول به سهم عثمانی افتاده بود عملاً اشغال شد. این گستره که در شرق به دست آمد پیشرفته‌ترین مرز پس از دوران پیمان فرهاد پاشا بود؛ اما نگه داشتن آن بار سنگینی بر سپاه و خزانه نهاد.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["فتح گنجه — پایان لشکرکشی قفقاز", "875bca7a"], "d": ["گنجه، واپسین هدف عملیات قفقاز، به‌عنوان مرکز قره‌باغ میان کُر و ارس تسلیم گرفته شد. با تکمیل خط شیروان، ایروان، نخجوان و گنجه، دولت عثمانی در قفقاز به گسترهٔ سال 1590 رسید. اما این دستاورد کوتاه‌عمر بود: ظهور نادرشاه ظرف ده سال سراسر منطقه را بازپس می‌گرفت.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["پیمان همدان — پیوستن ایران غربی به عثمانی", "94a29dc3"], "d": ["با پیمانی که با اشرف شاه، فرمانروای افغان، امضا شد جنگ چهارساله پایان یافت و سرزمین‌های ایران غربی که دولت عثمانی اشغال کرده بود از نظر حقوقی به رسمیت شناخته شد. اشرف شاه در برابر آن خلافت پادشاه عثمانی را پذیرفت و تعهد کرد در ایران خطبه به نام پادشاه خوانده شود. این پیروزی دیپلماتیک کوتاه‌عمر بود؛ ضدحمله‌ای که نادرشاه در 1730 آغاز کرد دستاوردهای پیمان را در چند سال از میان می‌برد.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["حکیم‌اوغلو علی پاشا ارومیه (روم‌یه) را گرفت", "eac7f64d"], "d": ["در لشکرکشی ایران، حکیم‌اوغلو علی پاشا نخست ارومیه (روم‌یه) و سپس تبریز را که برای عثمانی تخلیه شده بود در 15 نوامبر 1731 گرفت. TDV روز تصرف ارومیه را نمی‌دهد؛ تنها سال و اینکه پیش از تبریز بوده معلوم است.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["پیمان احمد پاشا — بازگرداندن بخش بزرگ ایران غربی", "590d839f"], "d": ["پس از پیروزی نادرشاه در ملایر و حمله‌های پیاپی ایران، احمد پاشا، والی بغداد، بی‌مشورت با مرکز متن صلحی را امضا کرد. بنا بر پیمان رود ارس مرز شناخته شد؛ شهرهای ایران غربی مانند همدان، کرمانشاه، اردلان، اردبیل و تبریز به ایران بازگردانده شد و گنجه و تفلیس در دست عثمانی ماند. این متن که در استانبول با واکنش روبه‌رو شد، نادرشاه نیز آن را ناکافی یافت و پیش از سپری شدن سال 1732 جنگ دوباره شعله کشید. اطلس کوتور را که زنجیره خوی را دنبال می‌کند نیز در همین روز از عثمانی به صفوی رسیده می‌شمارد (TDV hoy؛ روز ویژه کوتور در منبع نیست — تقریب با بیان).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["از دست رفتن دوباره وهران به اسپانیا", "20485027"], "d": ["ناوگان بزرگ پیاده‌سازی که فیلیپ پنجم، پادشاه اسپانیا، فرستاده بود به فرماندهی کنت مونته‌مار به برابر وهران آمد، نیروهای اوجاق الجزایر را شکست داد و شهر را بازگرفت. بندری که بیست و چهار سال پیش فتح شده بود، شصت سال دوباره در دست پادگان اسپانیا ماند. این زیان که مرزهای توان اوجاق‌های غرب را در مدیترانه باختری نشان داد، تنها با فتح قطعی وهران در 1792 جبران شد.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["اصلاح اوجاق خمباره‌چی به شیوه اروپایی و بنیان‌گذاری خمباره‌خانه", "d980cf2a"], "d": ["خمباره‌چی احمد پاشا، فرانسوی‌تبار که به خدمت عثمانی درآمده بود، با پشتیبانی صدراعظم حکیم‌اوغلو علی‌پاشا اوجاق خمباره‌چی را به یگانی حقوق‌بگیر و سامان‌یافته به سبک اروپایی بدل کرد. به سیصد سرباز که از بوسنی گرفته شده بودند آموزش منظم بر پایه حساب و هندسه داده شد؛ برای تشکیلات، تجهیزات و بازنشستگی نظام‌نامه‌های نو فراهم آمد و با فن نو صد توپ خمباره و پنجاه هزار خمباره ساخته شد. خمباره‌خانه که در آن هندسه آموخته می‌شد، نخستین هسته آموزش مهندسی نظامی نوین در عثمانی شمرده می‌شود.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["درگذشت احمد سوم", "455f7fba"], "d": ["احمد سوم که با شورش پاترونا خلیل در 1730 از تخت برکنار شده بود، شش سال پایانی زندگی را در بخش ویژهٔ پادشاهان برکنارشدهٔ کاخ توپقاپی گذراند و در شصت و سه سالگی درگذشت. در باغچه‌قاپی در آرامگاه مادربزرگش تورهان سلطان در کنار ینی‌جامی به خاک سپرده شد.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["پیمان استانبول — واگذاری قفقاز جنوبی به ایران", "8c205aab"], "d": ["دومین جنگ ایران که چهار سال کشید، با پیمانی که پس از شکست ارپاچای و از دست رفتن گنجه و تفلیس امضا شد پایان یافت. دولت عثمانی از همه سرزمین‌های قفقاز جنوبی و ایران غربی که از 1723 گرفته بود عقب نشست و مرز به خط قصر شیرین 1639 بازگشت. از سیزده سال لشکرکشی شرق بار مالی سنگین و خزانه‌ای تهی بر جای ماند؛ در برابر آن بسته شدن جبهه شرق برای جنگ تازه‌ای که با روسیه آغاز شده بود دستاوردی حیاتی بود.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["سقوط قلعه اوزی (اوچاکوف) به روس‌ها", "f93e61f3"], "d": ["سپاه روس به فرماندهی مارشال مونیخ قلعه اوزی را در دهانه دنیپر محاصره کرد؛ با منفجر شدن زرادخانه دفاع فروریخت و قلعه با تلفات جانی بسیار سقوط کرد. از دست رفتن اوزی، که قفل ساحل شمال‌باختری دریای سیاه شمرده می‌شد، راه کریمه را بر روس‌ها گشود و در استانبول هراس بزرگی پدید آورد. قلعه سال بعد به سبب بیماری همه‌گیر و دشواری تدارکات از سوی روس‌ها تخلیه شد و دوباره به عثمانی رسید.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["پیروزی بانالوکا — رهایی بوسنی", "f603865a"], "d": ["چون نیروهای اتریش به بوسنی درآمدند و بانالوکا را محاصره کردند، حکیم‌اوغلو علی‌پاشا، والی بوسنی، با نیروهایی که از مردم بومی گرد آورده بود به یاری شتافت و دشمن برتر از نظر شمار را به شکستی سنگین دچار کرد. این پیروزی طرح اتریش برای اشغال بوسنی را در نخستین گام فروریخت و شمال ایالت یکسره بازپس گرفته شد. بانالوکا از نقاط عطفی شد که روحیه سپاه عثمانی را که پس از 1683 در برابر اتریش پیوسته عقب می‌نشست بهبود بخشید.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["پیروزی هیسارجیق (گروتسکا) — گشوده شدن راه بلگراد", "2101cdff"], "d": ["سپاه اتریش که برای پاس‌داشت بلگراد پیش می‌رفت، در تنگه‌ای باریک در ساحل دانوب به کمین افتاد و در نبردی که یک روز کشید تلفات سنگین داد. هنگامی که نیروهای مارشال والیس به‌شکلی آشفته به بلگراد عقب می‌نشستند سپاه عثمانی به پای قلعه رسید و محاصره را آغاز کرد. هیسارجیق از زمان کارلوویتس قطعی‌ترین پیروزی میدانی در برابر اتریش بود و مستقیماً بازپس‌گیری بلگراد را ممکن کرد.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["پیمان نیش — صلح با روسیه، بی‌طرف شدن آزاق و بازداشتن یورش‌های کریمه", "674f974e"], "d": ["روسیه که با رضایت اتریش به صلح در بلگراد تنها مانده بود، با میانجی‌گری ویلنو، سفیر فرانسه، ناگزیر جنگ را پایان داد. با ویران شدن استحکامات قلعه آزاق، منطقه زمین بی‌طرف میان دو دولت اعلام شد؛ روسیه شرط نداشتن کشتی جنگی و بازرگانی در دریای سیاه را پذیرفت. بدین‌سان هدف روسیه برای رسیدن به دریا یک نسل دیگر به تأخیر افتاد و دولت عثمانی برای آخرین بار در سده هجدهم سودمند از میز برخاست.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["اوزی از اشغال روس بازگشت: پس از ویرانی با صلح 1739 تحویل داده شد", "7ecc2bef"], "d": ["روس‌ها اوزی را در 11 ژوئیه 1737 گرفته بودند. بنا بر صلح 1739 با روسیه، قلعه پس از ویران شدن استحکاماتش دوباره به عثمانی‌ها تحویل داده شد؛ عثمانی اوزی را تا پیش از پیمان یاش در 1788 نگه داشت.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["دفاع موصل — دفع نادرشاه", "c03ffbc1"], "d": ["نادرشاه که کرکوک و اربیل را گرفته و به پای موصل رسیده بود، چهل روز شهر را به توپ بست و یورش‌های همگانی پیاپی سامان داد. دفاعی که والی حسین پاشا الجلیلی با مسلح کردن مردم شهر پیش برد، سپاه ایران را با تلفات سنگین به برداشتن محاصره واداشت. ایستادن موصل مانع از دست رفتن سراسر عراق شد و نفوذ خاندان جلیلی را در شهر یک سده استوار کرد.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["پیمان درعیه — بنیان‌گذاری نخستین امارت سعودی در نجد", "188751bf"], "d": ["امیر محمد بن سعود که عالم رانده‌شده از عیینه، محمد بن عبدالوهاب، را در درعیه در پناه خود گرفت، با او پیمانی بست که اقتدار سیاسی را در خدمت دعوت دینی می‌نهاد. این توافق برای خاندان سعود تاریخی نو آغازید و امارت‌های پراکنده واحه‌ای نجد را پیرامون یک جنبش یکی کرد. این نیرو که در نیم‌سده تا کربلا، مکه و مدینه گسترش می‌یافت دولت عثمانی را ناگزیر می‌کرد از فرمانروایی خود در حجاز دفاع کند.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["پیمان کردان — پایان جنگ‌های عثمانی و ایران", "1d3a919e"], "d": ["با پیمانی که پس از واپسین جنگ چهارساله امضا شد مرز قصر شیرین 1639 همچنان که بود تجدید شد؛ هیچ‌یک از دو سو سود سرزمینی نبرد. اصرار نادرشاه بر شناخته شدن جعفری‌گری به‌عنوان مذهب پنجم بی‌پاسخ ماند؛ در برابر آن آزادانه حج رفتن حاجیان ایرانی و مبادله سفیر میان دو سو مقرر شد. جنگ‌های عثمانی و ایران که از دو سده درگذشته بود بدین‌سان عملاً بسته شد؛ این مرز تا امروز تا حد زیادی حفظ شده است.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["مرگ محمود یکم و جلوس عثمان سوم", "30203700"], "d": ["محمود یکم که در سلطنت بیست و چهار ساله خود سرزمین‌های از دست رفته در پیمان بلگراد را بازگرفت و از اصلاحات اوجاق خمباره‌چی پشتیبانی کرد، هنگام بازگشت از سلام جمعه درگذشت. برادرش عثمان سوم، که تا پنجاه و هشت‌سالگی در قفس زیسته بود، جانشین او شد. سلطنتی کوتاه و ناآرام آغاز شد؛ در دوران عثمان سوم که در سه سال شش صدراعظم را عوض کرد، رکود چشمگیری بر کارهای دولت چیره شد.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["مرگ عثمان سوم و جلوس مصطفی سوم", "3ac10f85"], "d": ["پس از سه سال سلطنت، با درگذشت عثمان سوم مصطفی سوم که برای اندیشه‌های اصلاح گشوده بود و به کارهای دولت علاقه نزدیک نشان می‌داد بر تخت نشست. پادشاه تازه با تکیه بر تجربه صدراعظم قوجه راغب پاشا کوشید دارایی را سامان دهد و سپاه را نو کند؛ توپچیان سریع‌السیر بارون دو توت در این دوران برپا شد. اما جنگ روس که در 1768 درآمدند همه دستاوردهای سلطنت هفده‌ساله را در سایه می‌برد.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["اعلان جنگ به روسیه — رویداد بالتا و آغاز جنگ 1768-1774", "9c6aabe0"], "d": ["چون یگان‌های روس و قزاق که کنفدراسیون بار در لهستان را تعقیب می‌کردند شهرک بالتا را در مرز عثمانی تاختند و سوزاندند، دیوان تصمیم جنگ گرفت و سفیر روس در یدی‌قوله زندانی شد. جنگی که بی‌تدارک نظامی جدی و با اعلان شش ماه پیش وارد شد، از همان آغاز بد پیش رفت. این کشمکش شش‌ساله با شبیخون چشمه، شکست کارتال و اشغال کریمه به یکی از سنگین‌ترین زنجیره‌های شکست تاریخ عثمانی بدل می‌شد.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["از دست رفتن قلعه خوتین به روس‌ها", "66d43ea4"], "d": ["پس از آنکه دو کوشش سپاه روس به فرماندهی شاهزاده گولیتسین دفع شده بود، با شکستی که صدراعظم میان کامیانیتس و خوتین خورد سپاه عقب نشست و نگهبانان قلعه را تخلیه کردند. از دست رفتن بی‌مقاومت نیرومندترین استحکام عثمانی در شمال دانوب، دروازه‌های افلاق و مولداوی را بر روس‌ها گشود. دو شاهزاده‌نشین همان سال اشغال شد؛ خوتین تنها در 1774 با پیمان کوچک قینارجه بازپس گرفته شد.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["شکست دشت کارتال (کاگول)", "6f408eaf"], "d": ["سه هفته پس از سوزاندن ناوگان در چشمه، سپاه اصلی عثمانی در کنار دانوب در دشت کارتال در برابر یگان‌های بسیار کوچک‌تر اما منضبط مارشال رومیانتسف پراکنده شد. اردوگاه، بارها و صدها توپ به دست دشمن افتاد؛ یگان‌های گریزان هنگام گذر از دانوب تلفات بزرگی دادند. نابودی هم ناوگان و هم سپاه زمینی در همان تابستان به سقوط پی‌درپی کیلیا، آق‌کرمان، اسماعیل و بندر و اشغال کریمه انجامید.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["اشغال شبه‌جزیره کریمه به دست روسیه", "217837b0"], "d": ["سپاهیان روس که یک سال پیش بوجاک را گرفته بودند، به فرماندهی شاهزاده دولگوروکوف از اور قاپی گذشتند و همه شبه‌جزیره کریمه را زیر پا گرفتند. خان از تخت برکنار شد و صاحب گرای هوادار روس بر سر کار آمد و نخستین گام در جداسازی خان‌نشین از عثمانی برداشته شد. از دست رفتن کریمه که سه سده سپر شمالی عثمانی بود، آغاز روند استقلال در 1774 و الحاق مستقیم در 1783 بود.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["مرگ مصطفی سوم و جلوس عبدالحمید یکم", "42cba8e2"], "d": ["به جای مصطفی سوم که در بحرانی‌ترین لحظه جنگ روس درگذشت، برادرش عبدالحمید یکم که چهل و سه سال از عمر خود را در قفس کاخ گذرانده بود در چهل و نه‌سالگی بر تخت نشست. پادشاه تازه که یکی از دشوارترین دوران دولت را به ارث می‌برد، ناگزیر شد با شرایط سنگین پیمان کوچک قینارجه که همان سال امضا می‌شد روبه‌رو شود. سلطنت پانزده‌ساله‌اش با از دست رفتن کریمه و جنگ روس تازه گذشت و در 1789 با سکته‌ای که هنگام خواندن خبر سقوط اوزی بر او عارض شد پایان یافت.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["شکست کوزلوجه — شکستی که به کوچک قینارجه رسید", "8e0542f9"], "d": ["نیروهای عثمانی که در برابر شومنو گرد آمده بودند در کوزلوجه به بازوهای یکی‌شده سووروف و کامنسکی شکست خوردند و بخش بزرگ سپاه پراکنده شد. با این شکست در بالکان نیرویی برای ایستادگی نماند؛ پیشروان روس شومنو را محاصره کردند و اردوگاه صدراعظم زیر تهدید افتاد. نشستن بر میز در کوچک قینارجه پیش از گذشتن یک ماه و پذیرفتن شرایط فوق‌العاده سنگین مستقیماً نتیجه این شکست است.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["واگذاری بوکووینا (مولداوی شمالی) به اتریش", "190f9caa"], "d": ["اتریش که از سستی ناشی از کوچک قینارجه بهره می‌برد، منطقه بوکووینا را که میان مولداوی و ارْدل پیوند می‌دهد خواست و بی‌آنکه وارد جنگ شود با تهدید و رشوه این سرزمین را به دست آورد. از دست رفتن این منطقه حاصلخیز و راهبردی در جنوب‌باختر خوتین، وویودایی مولداوی را عملاً دو نیم کرد. این واگذاری که بی‌شلیک گلوله‌ای انجام شد، از آشکارترین نشانه‌هایی شمرده شد که عثمانی دیگر بازدارندگی خود را از دست داده است. در 1775 با واگذاری بوکووینا سوچاوا و چرنوویتس به اتریش رسید (روز تأیید نشده).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["اشغال بصره به دست ایران", "0161e709"], "d": ["صادق خان، برادر کریم خان زند، پس از محاصره‌ای یک‌ساله بصره را گرفت و دولت عثمانی مهم‌ترین بندر خود را در خلیج بصره از دست داد. اشغال بصره راه بازرگانی هند، درآمد خرما و مروارید و دفاع جنوبی عراق را مستقیماً لرزاند. شهر تنها در 1779 با مرگ کریم خان و در جریان کشمکش‌های تاج‌وتخت در ایران بازگرفته شد.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["تنقیح‌نامه عینالی‌قوواق — سازش موقت بر سر کریمه", "9b3b0468"], "d": ["دو دولتی که بر سر اینکه چه کسی بر خان‌نشین کریمه بنشیند به آستانه جنگ رسیده بودند، با میانجی‌گری فرانسه در کاخ عینالی‌قوواق متن توضیحی امضا کردند. روسیه پذیرفت سربازانش را از کریمه بکشد و دولت عثمانی خان‌نشینی شاهین گرای هوادار روس را بشناسد؛ حق خلافت دینی پادشاه بر کریمه تأیید شد. این توازن شکننده که چهار سال خواهد پایید، در 1783 با الحاق مستقیم شبه‌جزیره به دست روسیه یکسره فرو ریخت.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["ساخت قلعهٔ آناپا — خط دفاعی قفقاز", "be92a80f"], "d": ["با از دست رفتن کریمه در پی کوچوک قاینارجا، برای حفظ نفوذ عثمانی در قفقاز ساخت قلعه‌ای نو در دهانهٔ رود کوبان آغاز شد. آناپا که بر بقایای مستعمرهٔ جنوایی بنا شد، با بازار، حمام‌ها و بیش از دویست و پنجاه دکانش در مدتی کوتاه به شهری بدل شد که پیوند با قبایل چرکس را برقرار می‌کرد. این قلعه در برابر فرود روسیه در قفقاز، چهل و هشت سال پیشروترین پاسگاه عثمانی ماند.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["عزل و اعدام صدراعظم خلیل حمید پاشا", "c44001ca"], "d": ["خلیل حمید پاشا، صدراعظم اصلاح‌طلبی که عبدالحمید یکم در مناسبت‌های گوناگون رضایت خود را از خدماتش نشان داده بود، نزدیک بامداد 31 مارس 1785 ناگهان عزل و به گالیپولی تبعید شد و همهٔ دارایی‌اش مصادره گردید. نخست ایالت حبشه، سنجق جده و شیخ‌الحرمی مکه به او داده شد؛ هنگامی که آوریل 1785 را در بوزجاآدا با تدارک راه می‌گذراند، از این ولایت نیز عزل شد و با فرمان اعدامی که صادر گردید، به دست قره‌کدخدازاده علی، از کسان جزایرلی غازی حسن پاشا، کشته شد. سر بریده‌اش به استانبول فرستاده شد و در اورتاقاپی به نمایش گذاشته شد. بر پایهٔ TDV این سقوط ناگهانی هرچند به اتهام توطئهٔ برکناری پادشاه و نشاندن شاهزاده سلیم به جای او تفسیر شده، اما دلایل اصلی احتمالاً خشم ناشی از سکوتش دربارهٔ الحاق کریمه، دشمنی محافل زیان‌دیده از اصلاحاتش و مخالفت غازی حسن پاشا بوده است.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["اعلان جنگ به روسیه — آغاز جنگ عثمانی و روس 1787-1792", "3bfb870c"], "d": ["پس از سفر پرشکوه کاترین دوم به کریمه و در حمایت گرفتن گرجستان، دیوان برای برگرداندن الحاق تصمیم جنگ گرفت و سفیر روس دوباره در یدی‌قوله زندانی شد. اما سپاه آماده نبود، خزانه تهی بود و جست‌وجوی متحد بی‌نتیجه مانده بود. جنگی که پنج سال خواهد کشید، با سقوط اوزی همراه کشتار، از دست رفتن اسماعیل و شرایط سنگین پیمان یاش پایان می‌یافت.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["وارد شدن اتریش به جنگ — کشمکش در دو جبهه", "ae912290"], "d": ["امپراتور اتریش یوزف دوم بنا بر اتحاد پنهانی‌ای که در 1781 با روسیه بسته بود، به دولت عثمانی اعلان جنگ کرد و به سوی بلگراد و بوسنی حرکت کرد. سپاه عثمانی ناگهان ناگزیر شد همزمان در دو جبهه بجنگد: در شمال با روسیه و در باختر با اتریش. با وجود پیروزی‌هایی که در لازارتخانه، مهادیه و شبش در برابر اتریشی‌ها به دست آمد، جبهه باختری نیز در 1789 با از دست رفتن بلگراد فرو می‌ریخت.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["اتحاد عثمانی و پروس", "03b88e51"], "d": ["سلیم سوم که به‌محض جلوس در اروپا به دنبال متحد بود، با پروس پیمان اتحادی امضا کرد که یاری متقابل را در نظر داشت؛ پروس متعهد شد به روسیه و اتریش اعلان جنگ کند و دولت عثمانی نیز متعهد شد تا کریمه بازنگرفته صلح نکند. این نخستین متن اتحاد متقابل واقعی بود که در تاریخ عثمانی با یک دولت اروپایی امضا شد و نشان می‌داد برداشت کلاسیک «با کافران اتحادی نیست» کنار گذاشته شده است. پروس وارد جنگ نشد، اما با واداشتن اتریش به صلح راه را برای پیمان زیشتووی گشود.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["سقوط قلعه اسماعیل و کشتار", "6a296b0c"], "d": ["قلعه اسماعیل که نیرومندترین استحکام دلتای دانوب شمرده می‌شد، با یورش همگانی خونین ژنرال سووروف در یک روز گرفته شد؛ پادگان و مردم شهر تا حد زیادی از دم شمشیر گذشتند. این کشتار که در اروپا طنین گسترده یافت، در افکار عمومی عثمانی شوکی ژرف پدید آورد و ستون فقرات خط دفاعی دانوب را شکست. قلعه یک سال بعد با پیمان یاش بازگرفته می‌شد، اما سرنوشت جنگ پیشتر تعیین شده بود.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["پیمان زیشتووی — بسته شدن جبهه اتریش", "58741f1d"], "d": ["با فشار پروس و مشغول شدن اتریش در باختر با انقلاب فرانسه، دو دولت با مبنا قرار دادن مرزهای پیش از جنگ به صلح رسیدند. اتریش همه جاهایی را که اشغال کرده بود، از جمله بلگراد، بازگرداند؛ دولت عثمانی تنها اصلاحات کوچکی در مرز کرواسی پذیرفت. بسته شدن جبهه باختری با این شرایط به دولت عثمانی امکان داد همه نیروی خود را علیه روسیه گرد آورد و زیان پیمان یاش را محدود کند. با این اصلاحات در مرز کرواسی، چتین (چتینگراد) و دره‌ژنیک گراد از عثمانی به هابسبورگ می‌رسد (TDV zistovi-antlasmasi؛ کوریچ 2016، یادداشت 118، ماده 4). اورشووا (اورشووای کهنه) تنها جایی است که بازگردانده نشد (بانلاکی 0019/1796)؛ اطلس انتقال حقوقی را به این روز می‌نویسد (اشغال عملی 16 آوریل 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["پیمان یاش — از دست رفتن قطعی کریمه و مرز تورلا", "a56fd194"], "d": ["با پیمانی که در پایان جنگ پنج‌ساله امضا شد رود تورلا (دنیستر) مرز شناخته شد؛ کرانه چپ رود به روسیه و کرانه راست به عثمانی ماند و اوزی و پیرامونش برای همیشه از دست رفت. دولت عثمانی امید بازپس‌گیری کریمه را یکسره رها کرد و الحاق 1783 را از نظر حقوقی شناخت؛ افلاق و مولداوی با معافیت مالیاتی دوساله بازگردانده شد. با پذیرفتن تعهد غرامت جنگی دوازده میلیون غروش، شمال دریای سیاه برای همیشه به روسیه واگذاشته شد. جاهای دیگری که در همین تاریخ پیوستند: اسماعیل.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["تخلیهٔ وهران (Vehrân) به دست اسپانیایی‌ها و واگذاری آن به الجزایر", "9f95cee6"], "d": ["پس از آنکه در زلزلهٔ 1790 قلعه و شهر بیشتر ویران شد، اسپانیا که دیگر تاب نگهداری پادگان پرهزینه‌ای را که سه سده داشت نمی‌آورد، با اوجاق الجزایر توافق کرد و وهران و مرسی‌الکبیر را بی‌جنگ واگذاشت. بدین‌سان واپسین موضع اروپایی در ساحل شمال آفریقا نیز برچیده شد. الجزایر عثمانی سی و هشت سال، تا اشغال فرانسه، بر سراسر ساحل مسلط ماند.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["فرمانروایی عملی عثمان پازوانداوغلو در ویدین", "0ce70361"], "d": ["عثمان پازوانداوغلو که علیه نظم‌های نظام جدید شورید، والی ویدین را گریزاند، شهر را گرفت و در امتداد دانوب با خندق‌های ژرف استوار کرد. در 1797 در اوج قدرت با گرد آوردن نیرویی نزدیک به هشتاد هزار نفر نیکوپول، زیشتووی، روسه، صوفیه و نیش را زیر نظارت گرفت؛ خود را اصلاح‌طلب نه شورشی معرفی می‌کرد. محاصره ماه‌ها طولانی باب‌عالی در 1798-1799 بی‌نتیجه ماند و او تا مرگش در 1807 در شمال بلغارستان نیمه‌مستقل فرمان راند.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["گشایش مهندس‌خانه بری همایون", "e9a3a34b"], "d": ["برای پرورش افسران توپخانه، استحکامات و نقشه‌برداری برای سپاه نظام جدید، مهندس‌خانه زمینی در خاص‌کوی گشوده شد؛ همتای زمینی مهندس‌خانه بحریه بود که در 1773 بنیان گرفته بود. در برنامه جبر، هندسه، مکانیک، استحکامات و بالستیک آموخته شد و کتاب‌های ریاضی و توپخانه از زبان‌های اروپایی ترجمه شد. این مدرسه که ریشه آموزش مهندسی نوین در ترکیه شمرده می‌شود، آغاز دانشگاه فنی استانبول امروزی به شمار می‌آید.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["اعلان جنگ به فرانسه و اتحاد با روسیه و انگلستان", "80e95bd7"], "d": ["با اشغال مصر به دست ناپلئون، دولت عثمانی دوستی سنتی دو سده و نیمه با فرانسه را شکست و به فرانسه اعلان جنگ کرد. در همین روند برای نخستین بار در تاریخ خود با روسیه اتحاد بست و به ناوگان روس اجازه داد از تنگه‌ها بگذرد و به مدیترانه برود؛ سپس با انگلستان نیز اتحاد امضا شد. به برکت این اتحادها جزایر ایونی از فرانسوی‌ها گرفته شد، اما گشوده شدن تنگه‌ها به روی یک ناوگان بیگانه نمونه‌ای پدید آورد که بعدها بهای سنگینی داشت.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["بازپس‌گیری پرِوزه از فرانسوی‌ها — نبرد نیکوپولیس", "d8e5e892"], "d": ["با سقوط جمهوری ونیز در 1797، جزایر ایونی و پرِوزه، پارگا و ووینیتسا در خشکی به دست فرانسه افتاد. علی پاشا تپه‌دلنلی، والی یانیا، با بهره‌گیری از جنگی که با اشغال مصر به دست فرانسه گشوده شد، به‌سوی پرِوزه لشکر کشید و در ویرانه‌های نیکوپولیس بیرون شهر پادگان فرانسه را سخت شکست داد. بدین‌سان این بندر که در پاساروفچا در دست ونیز مانده بود، هشتاد سال بعد به اداره عثمانی درآمد. بوتریند (Butrinto) با منفجر کردن استحکامات از سوی پادگان فرانسه و عقب‌نشینی آنان به کورفو در 25 اکتبر سقوط کرد (Curlin, Preveza B, 2010؛ روز اطلس از پرِوزه گرفته می‌شود) و به اداره عثمانی درآمد.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["دفاع عکا — دفع ناپلئون", "56b5c45b"], "d": ["ناپلئون که از مصر به سوی سوریه پیش می‌رفت، عکا را محاصره کرد و دو ماه یورش‌های پیاپی سامان داد؛ شهر را جزار احمد پاشا با پشتیبانی ناوگان انگلیس و یگان‌های نظام جدید که از استانبول فرستاده شده بود پاس داشت. ناپلئون که ناگزیر محاصره را برداشت و به مصر عقب نشست، رؤیای گسترش به شرق را در پای این باروها به خاک سپرد. خبر در استانبول با شادمانی بسیار پذیرفته شد و دلیل گذراندن نخستین آزمون جدی سپاه آموزش‌دیده نوبنیاد شمرده شد.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["یورش وهابیان به کربلا", "522341ed"], "d": ["نیروهای وهابی که از نجد برخاسته بودند وارد کربلا شدند، شهر را غارت کردند، آرامگاه امام حسین را ویران ساختند و بیش از سه هزار تن را کشتند. والیان کولمن دولت عثمانی در عراق نتوانستند جلو یورش را بگیرند؛ رویداد هم در ایران و هم در استانبول واکنش بزرگی برانگیخت. این حمله اعلان آن بود که جنبش سعودی دیگر از امارت واحه‌ای بیرون آمده و به نیرویی منطقه‌ای بدل شده که شهرهای مقدس عثمانی را تهدید می‌کند.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["کارتلی-کاختی (گرجستان شرقی) به روسیه الحاق شد", "3b650c5e"], "d": ["پادشاهی کارتلی-کاختی که در 1783 حمایت روسیه را پذیرفته و در 1795 دچار لشکرکشی ویرانگر ایران شده بود، منحل شد؛ با فرمان 12 سپتامبر 1801 ایالتی از روسیه اعلام شد و استقرار نظام اداری روسیه آغاز گردید. گرجستان از این تاریخ استقلال خود را از دست داد؛ ظرف چند سال مگرلیا (1803)، ایمرتی و گوریا (1804) نیز به سلطهٔ روسیه درآمدند و روسیه به مرز قفقازی عثمانی رسید. با این رویداد گوری، دوشتی (کارتلی) و تلاوی (کاختی) به روسیه رسید.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["تخلیه مصر از فرانسوی‌ها", "00cfdc8c"], "d": ["در پی عملیات مشترک نیروهای عثمانی و انگلیس از خشکی و دریا نخست قاهره و سپس اسکندریه تسلیم گرفته شد و نیروهای فرانسوی با کشتی به کشورشان فرستاده شدند. با پایان یافتن اشغال سه‌ساله، مصر بر کاغذ به اداره عثمانی بازگشت، اما کشمکش چیرگی میان بیگ‌های کولمن و یگان‌های آلبانیایی کشور را به آشوب کشاند. این خلأ ظرف چند سال زمینه برآمدن محمدعلی قوالایی را فراهم می‌کرد.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["پیمان پاریس — برقراری دوباره صلح با فرانسه", "1b76991f"], "d": ["با پیمانی که پس از تخلیه مصر امضا شد حالت جنگ میان دولت عثمانی و فرانسه رسماً پایان یافت و کاپیتولاسیون‌های پیشین تجدید شد. به کشتی‌های بازرگانی فرانسه اجازه ورود به دریای سیاه داده شد؛ در برابر آن فرانسه تمامیت ارضی عثمانی را شناخت. برقراری صلح به سیاست خارجی سلیم سوم که میان روسیه و انگلستان گیر کرده بود دوباره جای مانور بخشید.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["گرفتن طائف به دست وهابیان", "7b791359"], "d": ["نیروهای وهابی به فرماندهی سعود بن عبدالعزیز در نخستین حمله به حجاز طائف را محاصره و غارت کردند؛ شهر به‌عنوان نخستین دروازه گشوده به سرزمین‌های مقدس فرو افتاد. برای پادشاه عثمانی که عنوان پشتیبان حرمین را داشت، این ضربه‌ای بود که مستقیماً مشروعیت سلطنت را لرزاند. دو ماه و نیم بعد همان سپاه به مکه خواهد تاخت.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["نخستین گرفتن مکه به دست وهابیان", "21157c05"], "d": ["دو ماه و نیم پس از سقوط طائف، نیروهای وهابی وارد مکه شدند، آرامگاه‌ها را ویران کردند و بر پایه برداشت خود نظمی برقرار ساختند؛ شریف غالب ناگزیر به جده عقب نشست. بسته شدن راه‌های حج در سراسر جهان اسلام طنین انداخت و استانبول را مجبور کرد از والی مصر محمدعلی یاری نظامی بخواهد. این فرمانروایی نخستین تنها سه ماه خواهد کشید.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["بازپس‌گیری مکه به دست شریف غالب", "83d08dff"], "d": ["شریف غالب که به جده عقب نشسته بود، با نیروهایی که گرد آورد مکه را محاصره کرد و پس از بیست و پنج روز محاصره شهر را از وهابیان بازگرفت؛ خطبه دوباره به نام عثمانی خوانده شد. این فرمانروایی دوم نیز پایدار نخواهد بود و نیروهای سعود در 1806 شهر را دوباره خواهند گرفت.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["آغاز قیام نخست صرب", "0f6e8767"], "d": ["چون دایی‌های ینی‌چری شورشی که اداره بلگراد را به دست گرفته بودند، بزرگان صرب را به‌صورت دسته‌جمعی کشتند، مقاومت مسلحانه به رهبری قره‌یورگی آغاز شد. جنبشی که در آغاز با وفاداری به پادشاه تنها علیه دایی‌ها پیش می‌رفت، به‌زودی به قیامی ملی با خواست خودمختاری و استقلال بدل شد. نیروهای صرب در 1806 بلگراد را گرفتند؛ این قیام نخستین حلقه جنبش‌های استقلال‌طلب ملی‌گرایانه در بالکان شد.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["اشغال مدینه به دست وهابیان", "84e310d7"], "d": ["پس از مکه مدینه نیز به دست نیروهای وهابی افتاد؛ گنجینه روضه مطهره پراکنده شد و آرامگاه‌های گنبددار شهر ویران گشت. بدین‌سان هر دو شهر مقدس با هم از نظارت عثمانی بیرون رفت و کاروان‌های حج از شام و مصر سال‌ها نتوانستند راه بیفتند. مدینه تنها هفت سال بعد، در 1812، به دست سپاه مصر به فرماندهی طوسون پاشا، پسر محمدعلی پاشا، بازگرفته شد.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["آغاز جنگ با روسیه (جنگ عثمانی و روس 1806-1812) و بستن تنگه‌ها", "ea170804"], "d": ["سلیم سوم که پس از پیروزی اوسترلیتز ناپلئون به فرانسه نزدیک شده بود، با وجود فشار روس وویودای افلاق و مولداوی را عزل کرد؛ سپاهیان روس دو شاهزاده‌نشین را اشغال کردند و جنگ آغاز شد. دولت عثمانی تنگه‌ها را به روی ناوگان روس بست؛ در برابر آن انگلستان نیز در کنار روسیه ایستاد و ناوگانی به استانبول فرستاد. این جنگ شش‌ساله که با شورش قاباقچی و برکناری سلیم سوم درهم تنید، در پیمان بخارست 1812 با از دست رفتن بسارابیا پایان می‌یافت.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["رسیدن ناوگان انگلیس به برابر استانبول (عملیات داکورث)", "195bb58f"], "d": ["انگلستان که می‌خواست دولت عثمانی را به گسستن پیوندش با فرانسه وادارد، ناوگانی به فرماندهی دریاسالار داکورث را از چاناق‌قلعه گذراند و در برابر استانبول لنگر انداخت. با راهنمایی سباستیانی، سفیر فرانسه، مردم استانبول بسیج شدند، باتری‌های ساحلی ظرف چند روز تقویت شد و ناوگان پیش از آنکه شهر را به توپ ببندد ناگزیر عقب نشست؛ در بازگشت در چاناق‌قلعه تلفات سنگین داد. این‌که پایتخت نخستین بار تا این اندازه نزدیک از سوی ناوگانی بیگانه تهدید شد، مسئله تنگه‌ها را در کانون دیپلماسی اروپا نشاند.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["خفه شدن مصطفی چهارم", "eeb75c20"], "d": ["پس از آنکه علمدار مصطفی پاشا مورد حمله قرار گرفت و کشته شد و شورشیان خواستند به‌سوی کاخ بروند، مصطفی چهارم برکنارشده به فرمان برادرش محمود دوم خفه و کشته شد. پیکرش در باغچه‌قاپی در آرامگاه پدرش عبدالحمید یکم به خاک سپرده شد؛ در میان شورشیان این شایعه پراکنده شد که تابوت خالی است.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["پیمان قلعه سلطانیه — صلح با انگلستان و قاعده تنگه‌ها", "fe282117"], "d": ["پس از ناکامی عملیات داکورث با پیمانی که با انگلستان امضا شد جنگ میان دو دولت پایان یافت و امتیازهای پیشین بازرگانان انگلیسی بازگردانده شد. حکمی که در متن آمده و «قاعده قدیم» نامیده می‌شود ثبت کرد که در زمان صلح هیچ کشتی جنگی بیگانه نمی‌تواند از تنگه‌ها بگذرد. این اصل در سراسر سده نوزدهم مبنای حقوقی همه ترتیبات بین‌المللی شد که رژیم تنگه‌ها را شکل می‌دادند.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["شکست اسلوبوزیا — محاصره سپاه دانوب", "54b60fd1"], "d": ["بخش بزرگ سپاه عثمانی که در برابر روسه از دانوب گذشته بود، با مانور محاصره‌ای که کوتوزوف از کرانه دیگر رود انجام داد در اسلوبوزیا گرفتار شد و به گرسنگی رها شد. هزاران سرباز ناگزیر تسلیم شدند؛ نیروی در دست صدراعظم عملاً آب شد و باب‌عالی یک ماه بعد ناگزیر آتش‌بس خواست. این شکست علت بی‌واسطه پذیرفتن واگذاری بسارابیا در پیمان بخارست 1812 است.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["بازپس‌گیری بلگراد و سرکوب قیام نخست صرب", "06f56f52"], "d": ["شورشیان صرب که با پیمان بخارست از پشتیبانی روس محروم شده بودند، در برابر عملیات مشترک نیروهای بوسنی و روم‌ایلی تاب نیاوردند؛ خورشید احمد پاشا وارد بلگراد شد و قیام نه‌ساله یکسره سرکوب گردید. قره‌یورگی به اتریش گریخت و سنجق سمندره دوباره مستقیماً به اداره عثمانی بسته شد. اما تدابیر سختی که به کار رفت دو سال بعد به رهبری میلوش اوبرنویچ قیامی دوم و پایدار برانگیخت.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["قیام دوم صرب و شاهزاده بزرگی میلوش اوبرنویچ", "e6e82ad2"], "d": ["پس از سرکوب قیام نخست، در برابر تدابیر سنگینی که به کار رفت قیامی تازه به رهبری میلوش اوبرنویچ درگرفت؛ این بار باب‌عالی به‌جای نیرو سازش را برگزید. با توافقی که شد میلوش با عنوان «شاهزاده بزرگ» شناخته شد و اختیار گرفتن مالیات و اداره امور درونی به کنِزهای صرب سپرده شد. این هسته نخستین خودگردانی عملی، نقطه آغاز روندی شد که به فرمان 1830 و استقلال 1878 می‌رسید.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["قیام افلاق — گذر ایپسیلانتی از پروت و قیام ولادیمیرسکو", "67d46a98"], "d": ["آلکساندر ایپسیلانتی، ژنرال سپاه روس، به نام فیلیکی اتریا از پروت گذشت و کوشید در افلاق و مولداوی قیامی همگانی از یونانیان آغاز کند؛ در همان روزها تودور ولادیمیرسکو نیز روستاییان بومی را به حرکت آورد. دو جنبش یکی نشد: ولادیمیرسکو به دعوت ایپسیلانتی برای جنگ مشترک علیه ترک‌ها پاسخ داد «من نه علیه ترک‌ها بلکه علیه یونانیان شوریده‌ام» و اندکی بعد به دست مردان ایپسیلانتی کشته شد. قیام در ماه مه به دست نیروهای عثمانی سرکوب شد، اما نظام وویوداهای فنری برچیده شد و شعله قیام به موره جهید.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["بنیان‌گذاری دولت دوم سعودی در ریاض", "34dad3bd"], "d": ["شش سال پس از سقوط درعیه در 1818 و فروپاشی دولت نخست سعودی، ترکی بن عبدالله پادگان‌های مصر را از نجد بیرون راند و امارتی نو سعودی با مرکزیت ریاض بنیان نهاد. ساختار تازه از رسیدن به حجاز پرهیز کرد و در نجد ماندن را برگزید و از درگیری مستقیم با نیروهای عثمانی-مصر دوری جست. این دولت دوم تا پایان سده ادامه می‌یافت و دومین حلقه زنجیره‌ای بود که به بنیان‌گذاری عربستان سعودی امروز می‌رسید. جاهای دیگری که در همین تاریخ از دست رفتند: درعیه (نجد).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["پیمان آق‌کرمان — امتیازها به صربستان و شاهزاده‌نشین‌ها", "c75f15d0"], "d": ["دولت عثمانی که بی‌درنگ پس از برچیدن اوجاق ینی‌چری بی‌سپاه مانده بود، در برابر التیماتوم روسیه ناگزیر پیمانی با شرایط سنگین پذیرفت. خودگردانی وعده‌داده‌شده به صربستان تأیید شد، پذیرفته شد که وویوداهای افلاق و مولداوی بی‌تأیید روس عزل نشوند و به کشتی‌های بازرگانی روس در تنگه‌ها آزادی کامل داده شد. چون باب‌عالی دو سال بعد بر سر مسئله یونان پیمان را نشناخته اعلام کرد، روسیه آن را دلیل جنگ شمرد.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["برچیده شدن نظام تیمار", "84d5d1d6"], "d": ["یک سال پس از برچیدن اوجاق ینی‌چری، حدود 5.200 سپاهی تیمارلو در پنجاه و سه سنجق در روم‌ایلی و آناتولی، همراه با درآمد تیمارها، به سواره‌نظام عساکر منصوره بدل شدند. بدین‌سان نظام تیمار که ستون فقرات چهارسده‌ای نظام زمین، مالیات و سپاه عثمانی بود عملاً پایان یافت. تیمارهای خالی‌شده به خزانه سپرده شد و راه گذار به سپاه حقوق‌بگیر مرکزی و نظام مالیات نقدی گشوده شد.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["بنیان‌گذاری طب‌خانه عامره — آغاز آموزش پزشکی نوین", "ac3e57c0"], "d": ["برای پرورش پزشک و جراح برای سپاه نوبنیاد عساکر منصوره، به پیشنهاد حکیم‌باشی مصطفی بهجت افندی طب‌خانه عامره در شهزاده‌باشی گشوده شد. درس‌ها بر پایه برنامه اروپا سامان یافت و آموزش در آغاز به فرانسوی بود؛ چند سال بعد جراح‌خانه عامره نیز بنیان گرفت و دو نهاد یکی شد. این مدرسه که آغاز آموزش پزشکی نوین در ترکیه شمرده می‌شود، ریشه دانشکده پزشکی استانبول امروزی دانسته می‌شود.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["آغاز جنگ عثمانی و روس 1828-1829", "9dff4e05"], "d": ["پس از سوزاندن ناوگان در ناوارین و اعلان نشناختن پیمان آق‌کرمان از سوی باب‌عالی، روسیه از دو جبهه با هم جنگ آغاز کرد. چون اوجاق ینی‌چری تازه برچیده شده و سپاه نو در مرحله برپایی بود، دفاع عثمانی از آغاز ضعیف بود؛ روس‌ها هنگام گذر از دانوب در شرق قارص و آخالتسیخه را گرفتند. سپاه روس که ظرف یک سال تا ادرنه پیش رفت، شرایط سنگین پیمان ادرنه 1829 و استقلال یونان را تحمیل می‌کرد.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["نخستین پیمان با ایالات متحده آمریکا", "d737516f"], "d": ["با پیمان بازرگانی و کشتیرانی که پس از تماس‌های چندساله امضا شد، آمریکا در خاک عثمانی منزلت ملت کامله‌الوداد و حق گذر بازرگانی از تنگه‌ها را به دست آورد. ماده‌ای محرمانه جداگانه پیش‌بینی می‌کرد عثمانی هرگاه بخواهد در کشتی‌سازی‌های آمریکا کشتی بسازد و کشتی آماده و چوب بخرد؛ سنای آمریکا پیمان را تصویب کرد اما این ماده محرمانه را با 27 رأی در برابر 18 رد کرد. با این همه راه کشتی بسته نشد: هنری اکفورد در 1831 کشتی‌ای را که آورده بود به عثمانی فروخت و استادکاران آمریکایی که در عینالی‌قوواق کار می‌کردند ناوگان را با کشتی‌های نوع تازه آراستند. این پیمان سند نخستین رابطه فراگیر دولت عثمانی با دولتی بیرون از اروپا شد.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["پایان دادن به اداره کولمن در بغداد", "7e1d38a3"], "d": ["محمود دوم که سیاست مرکزگرایی دنبال می‌کرد، داود پاشا، والی بغداد، را که پول خواسته‌شده را نمی‌فرستاد و مأمور آمده از مرکز را کشته بود، شورشی اعلام کرد. نیرویی به فرماندهی علی‌رضا پاشا پس از محاصره‌ای نود روزه شهر را گرفت و کولمن‌ها تقریباً همه تصفیه شدند. بدین‌سان اداره نیمه‌مستقل کولمن که از 1704 ادامه داشت پایان یافت و عراق دوباره مستقیماً به مرکز بسته شد.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["بنیان‌گذاری مکتب حربیه در سربازخانه ماچکا", "bf31c7d9"], "d": ["برای فراهم آوردن افسران آموزش‌دیده به شیوه اروپایی برای عساکر منصوره محمدیه، مکتب فنون حربیه در سربازخانه ماچکا گشوده شد. به دانش‌آموزان ریاضی، نقشه، استحکامات و زبان بیگانه آموخته شد؛ اندکی بعد با فرستادن دانشجو به وین و پاریس کادر تقویت شد. این مدرسه جایی شد که سنت افسر مکتب‌دیده در سپاه عثمانی و در نتیجه نسل نظامی-روشنفکر نو در پایان سده نوزدهم در آن زاده شد.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["پیوستن مستقیم طرابلس غرب به مرکز — پایان دودمان قره‌مانلی", "faabcb96"], "d": ["پس از کشمکش‌های تاج‌وتخت درون خاندان قره‌مانلی و فشار فزاینده اروپا پس از اشغال الجزایر به دست فرانسه در 1830، باب‌عالی مستقیماً در طرابلس غرب دخالت کرد. ناوگانی که از استانبول فرستاده شد وارد شهر شد، واپسین بیگ قره‌مانلی عزل و به استانبول آورده شد و ایالت به والی‌ای که از مرکز گماشته شد سپرده گردید. با پایان یافتن دوران دودمان 124 ساله، واپسین پاره سرزمینی که دولت عثمانی در شمال آفریقا مستقیماً اداره می‌کرد استوار شد.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["برچیدن دفتردارلق و برپایی نظارت مالیه", "89f8125e"], "d": ["مقام دفتردارلق که رأس نظام مالی کلاسیک عثمانی بود لغو شد و نظارت مالیه، وزارتخانه‌ای به سبک اروپایی، برپا گردید و خزانه‌های پراکنده در یک دست گرد آمد. همان سال دیگر واحدهای باب‌عالی نیز با نام نظارت بازسازماندهی شد و به ساختار هیئت وزیران نوین گذر شد. این ترتیب از مهم‌ترین گام‌هایی بود که زیرساخت اداری فرمان تنظیمات را که یک سال بعد اعلام می‌شد فراهم کرد.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["استقرار انگلیسی‌ها در عدن", "ddbd556b"], "d": ["انگلستان با تکیه بر پیمان بازرگانی و دوستی‌ای که در 1802 با سلطان لحج، احمد بن عبدالکریم، امضا کرده بود، در بندر عدن نیرو پیاده کرد و شهر را زیر نظارت گرفت. این بندر که دهانه دریای سرخ را در دست دارد، به‌عنوان پایگاه تأمین زغال راه هند به نقطه کلیدی راهبرد امپراتوری انگلیس بدل شد. هرچند ادعای دولت عثمانی بر یمن بر کاغذ ادامه یافت، فرمانروایی عملی آن در ساحل جنوبی از این تاریخ دیگر بازنگشت.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["بازگشت به ساحل تهامه: گرفتن حدیده، زبید و مخا", "353982d2"], "d": ["با عقب‌نشینی سپاه مصر در 1840 ساحل یمن بی‌صاحب مانده بود؛ نیروهایی به فرماندهی توفیق پاشا زیر نظارت شریف مکه پیاده شدند و بنادر حدیده، زبید و مخا را به اداره عثمانی بستند. خواسته شد تا صنعا پیشروی شود، اما با ایستادگی مردم به حدیده بازگشته شد؛ بدین‌سان کوهستان‌ها در دست امامان زیدی ماند و فرمانروایی عثمانی بیست و سه سال تنها در نوار تهامه ادامه یافت. یمن درونی تنها در 1872 با لشکرکشی احمد مختار پاشا بازگرفته خواهد شد.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["قرارداد بالتالیمانی: حمایت مشترک عثمانی و روس بر افلاق و مولداوی", "d3bb22e9"], "d": ["با سرایت انقلاب‌های 1848 به افلاق و مولداوی، نیروهای عثمانی و روس شاهزاده‌نشین‌ها را با هم اشغال کرده بودند. با قراردادی که در بالتالیمانی امضا شد مقرر گردید وویوداها نه با انتخاب بلکه به دست پادشاه برای هفت سال گماشته شوند و دو دولت نظارت مشترکی در منطقه برپا کنند. توافق در حالی که حاکمیت بر کاغذ عثمانی را نگه می‌داشت، به روسیه حق شراکت عملی داد و جدایی شاهزاده‌نشین‌های دانوب از عثمانی را شتاب بخشید.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["مسئله پناهندگان مجار: پناه بردن کوشوت و همراهانش به عثمانی", "1c7d7ef4"], "d": ["با سرکوب انقلاب مجارستان 1848-1849 با مداخله روس-اتریش، لایوش کوشوت و هزاران پناهنده مجار-لهستانی به سرزمین‌های عثمانی پناه بردند. اتریش و روسیه به‌سختی استرداد پناهندگان را خواستند؛ باب‌عالی با پشتیبانی انگلستان و فرانسه استرداد را رد کرد و گروه را در کوتاهیه جای داد. پیرامونیان کوشوت حدود هجده ماه در آنجا ماندند و صدها پناهنده مسلمان شدند و به خدمت عثمانی درآمدند. این رویداد از پیروزی‌های دیپلماتیک کمیاب شمرده شد که اعتبار عثمانی دوران تنظیمات را در افکار عمومی اروپا بالا برد.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["بنیان‌گذاری انجمن دانش: نخستین فرهنگستان عثمانی در استانبول", "6fda1365"], "d": ["انجمن دانش که با تصمیم مجلس معارف عمومیه بنیان گرفت، نخستین فرهنگستان علمی عثمانی است که برای فراهم آوردن کتاب‌های علمی و درسی به ترکی سامان یافته بود. در 18 ژوئیه 1851 در ساختمان دارالمعارف با مراسم گشوده شد؛ در میان اعضای بومی و بیگانه‌اش احمد جودت پاشا نیز بود. هرچند کوتاه‌عمر بود، آثاری مانند تاریخ جودت پاشا و قواعد عثمانیه از دستاوردهای این نهاد شد و در تبدیل ترکی به زبان علم سنگ بنا شمرده می‌شود.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["پیروزی اولتنیتسا: نخستین موفقیت عثمانی در جبهه دانوب", "a660ad2f"], "d": ["در مرحله آغازین جنگ کریمه، سردار اکرم عمر لطفی پاشا از دانوب گذشت و در اولتنیتسا نیروهای روس را با تلفات سنگین عقب راند. پیروزی با متوقف کردن پیشروی روس در آغاز جنگ، توان سپاه عثمانی را که پس از تنظیمات با آموزش به دست آورده بود به اروپا نشان داد. این موفقیت زمینه روانی‌ای را که تصمیم انگلستان و فرانسه به ورود به جنگ در کنار عثمانی را آسان می‌کرد فراهم ساخت.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["پیمان اتحاد با انگلستان و فرانسه در استانبول", "04809278"], "d": ["پیمان اتحادی که در جنگ کریمه علیه روسیه میان دولت عثمانی و انگلستان و فرانسه امضا شد، عملیات مشترک سه دولت و صلح جداگانه نکردن متحدان پیش از پایان جنگ را مقرر داشت. بدین‌سان دولت عثمانی در تاریخ خود نخستین بار با منزلت طرف برابر وارد اتحاد نظامی با دولت‌های بزرگ اروپا شد. این پیمان زمینه حقوقی پذیرفته شدن رسمی عثمانی در نظام دولت‌های اروپایی را در پاریس دو سال بعد نیز فراهم کرد.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["بنیان‌گذاری شهرامانت استانبول: نخستین تشکیلات شهرداری نوین", "be4af27f"], "d": ["متحدان نظامی که در جریان جنگ کریمه در استانبول انباشته شدند و بحران زیرساختی که جمعیت فزاینده پدید آورد، ناکافی بودن اداره کلاسیک شهر با مرکزیت قضاوت را آشکار کرد. با شهرامانتی که به‌سان نمونه‌های اروپایی برپا شد، پاکیزگی، نرخ‌گذاری، نظارت بر بازار و کارهای آبادانی در یک دست گرد آمد؛ سال بعد در بی‌اوغلو-غلطه «دایره بلدیه ششم» به‌عنوان منطقه آزمایشی برپا شد. این گام آغاز شهرداری‌گری نوین در عثمانی شمرده می‌شود.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["پیمان پاریس: پایان جنگ کریمه و پذیرفته شدن عثمانی در نظام دولت‌های اروپایی", "4aee0e2a"], "d": ["با پیمان پاریس که جنگ کریمه را پایان داد، دولت عثمانی عضو برابر حقوق دولت‌های اروپایی اعلام شد و تمامیت ارضی آن زیر تضمین مشترک دولت‌های بزرگ درآمد. دریای سیاه بی‌طرف شد، ادعای حمایت روسیه بر رعایای ارتدوکس که از کوچک قینارجه به دست آورده بود بی‌اعتبار شد و جنوب بسارابیا (قضاهای کیلیا، کاهول، اسماعیل و بولگراد) به مولداوی داده شد. اما همین پیمان با تبدیل فرمان اصلاحات به تعهدی بین‌المللی در دخالت در امور درونی را نیز گشود.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["گشایش کاخ دلمه‌باغچه: انتقال مرکز اداره از توپقاپی", "71ad26d0"], "d": ["کاخی که عبدالمجید در 1842 به خاندان بالیان سفارش داد، پس از چهارده سال ساخت گشوده شد و مرکز اداره دولت از توپقاپی چهارسده‌ای به ساحل بسفر منتقل شد. کاخ با سبک اروپایی، پلکان بلورین و تالار مراسم، بیان سنگی ادعای غربی‌شدن تنظیمات شد. هزینه عظیم آن از انتقادپذیرترین اقلام سال‌هایی شد که دارایی عثمانی به مارپیچ وام خارجی درآمد.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["یکی شدن افلاق و مولداوی زیر فرمانروایی کوزا: زایش رومانی", "baef4da5"], "d": ["در انتخاباتی که پس از پیمان پاریس سامان یافت هر دو شاهزاده‌نشین سرهنگ الکساندرو یوان کوزا را وویودا برگزیدند و یگانگی عملی پدید آمد. هرچند باب‌عالی و اتریش مخالفت کردند، امر انجام‌شده‌ای که فرانسه پشتیبان آن بود ناگزیر پذیرفته شد. این اتحاد که بر کاغذ وابسته به عثمانی ماند، در 1862 نام رومانی می‌گرفت و در 1877 استقلال یک‌جانبه خود را اعلام می‌کرد؛ نقطه عطف از هم گسستن فرمانروایی عثمانی در کنار دانوب است.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["رویداد کوله‌لی: نخستین کوشش کودتا علیه عبدالمجید در استانبول", "e3653b21"], "d": ["انجمنی پنهان آمیخته از نظامی و غیرنظامی که از سیاست تنظیمات و برابری‌ای که فرمان اصلاحات برای غیرمسلمانان شناخته بود ناخشنود بود، هنگام برنامه‌ریزی برای برکناری پادشاه در نشستی در مسجد قلیچ علی‌پاشا مورد یورش قرار گرفت. چون متهمان در سربازخانه کوله‌لی محاکمه شدند رویداد با همین نام یاد می‌شود؛ حکم‌های اعدام به تبعید تبدیل شد. این رویداد نخستین کوشش کودتای کاخی شمرده می‌شود که سازمانی با انگیزه ایدئولوژیک در تاریخ عثمانی به آن دست زد.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["جنگ داخلی دروزی-مارونی در جبل لبنان و رویدادهای دمشق", "5595fdd6"], "d": ["درگیری‌هایی که در مه 1860 با کشته شدن دو دروزی در نزدیکی صیدا درگرفت، به خونین‌ترین جنگ داخلی دروزی-مارونی در کوهستان بدل شد و در ژوئیه به دمشق سرایت کرد و با مرگ هزاران مسیحی پایان یافت. با پیاده شدن نیروی فرانسه، باب‌عالی فؤاد پاشا را با اختیار فوق‌العاده به منطقه فرستاد؛ عملیات سخت سرکوب انجام گرفت. رویدادها دستاویز دخالت اروپا شد و علت بی‌واسطه یافتن منزلت ویژه از سوی لبنان بود.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["آغاز انتشار ترجمان احوال: نخستین روزنامه ترکی خصوصی در استانبول", "24792957"], "d": ["ترجمان احوال که آغاه افندی منتشر کرد و شیناسی کار نویسندگی آن را برعهده گرفت، نخستین روزنامه ترکی است که بی‌پشتیبانی دولت منتشر شد. در مقدمه شماره نخست حق مردم برای سخن گفتن درباره کارهای خود دفاع شد و روزنامه با پاورقی کردن «شاعر اولنمه‌سی» شیناسی در ادبیات نوین ترکی را نیز گشود. زایش مفهوم افکار عمومی و مطبوعات مخالف در عثمانی به این تاریخ برمی‌گردد.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["نظام‌نامه جبل لبنان: منزلت متصرفی ممتاز برای لبنان", "bf375603"], "d": ["نظام‌نامه‌ای که پس از کشتارهای 1860 با فشار دولت‌های بزرگ فراهم شد، جبل لبنان را به متصرفیتی ممتاز بدل کرد که مستقیماً به باب‌عالی بسته بود و با شورای اداره‌ای که بر پایه توازن میان مذاهب شکل می‌گرفت اداره می‌شد. شرط شد که متصرف از رعایای عثمانی و مسیحی کاتولیک باشد و گماشتنش به تأیید دولت‌های بزرگ برسد؛ نخستین متصرف داود پاشا بود. این نظم تا 1915 ادامه می‌یافت و هسته دولت لبنان نوین را می‌ساخت.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["درگذشت عبدالمجید و جلوس سلطان عبدالعزیز", "27204d7c"], "d": ["با مرگ عبدالمجید که در سلطنت بیست و دوساله خود فرمان‌های تنظیمات و اصلاحات را امضا کرده بود و تسلیم سل شد، برادرش عبدالعزیز بر تخت نشست. پادشاه تازه در سال‌های نخست با تدابیر صرفه‌جویی و زندگی ساده امید بخشید؛ ناوگان را به یکی از نیروهای انگشت‌شمار جهان بدل کرد. اما در پایان سلطنتش وام خارجی سنگین، ورشکستگی 1875 و قیام‌های بالکان انباشته شد و زمینه جنبش خلع 1876 را فراهم کرد.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["نام گرفتن شاهزاده‌نشین‌های یکی‌شده به رومانی", "d960e3fc"], "d": ["افلاق و مولداوی که در 1859 با انتخاب دوگانه کوزا عملاً یکی شده بودند، در 1862 مجلس‌ها و دولت‌های خود را در بخارست زیر یک سقف گرد آوردند و رسماً نام رومانی گرفتند. دولت عثمانی هرچند از نظر حقوقی عنوان مولا و مالیات سالانه را نگه داشت، نظارت خود را بر شاهزاده‌نشین عملاً از دست داد. پایان یافتن نفوذ چهارسده‌ای عثمانی در شمال دانوب با این تاریخ نمادین شده است.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["پیوستن سواکن، مصوع و دهلک به مصر", "a0924860"], "d": ["مصوع که در 1846 سلطان عبدالمجید همراه با سواکن به‌عنوان سالیانه (تخصیص درآمد) به محمدعلی پاشا، والی مصر، داده بود، در دوران خدیو اسماعیل پاشا همراه با دهلک و سواکن در شمار املاک مصر درآمد و با منزلت قائم‌مقامی سازمان یافت. بدین‌سان این سه بندر در ساحل آفریقایی دریای سرخ هرچند از نظر حقوقی خاک عثمانی ماندند، از نظر اداری مستقیماً از باب‌عالی به قاهره رسیدند — در همان لایه تابعی قرار گرفتند که همسایه‌اش مصر و سودان بودند.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["آغاز قیام کرت (1866-1869)", "3679b861"], "d": ["قیام گسترده‌ای که با پشتیبانی آشکار یونان در جزیره درگرفت، خواست انوسیس (پیوستن به یونان) رومیان کرت را نخستین بار به مسئله‌ای بین‌المللی بدل کرد. نبرد کوهستانی سخت سه‌ساله به سپاه عثمانی تلفات سنگین داد و در افکار عمومی اروپا طنین بزرگی یافت. قیام تنها در 1868 با رفتن عالی پاشا به جزیره و به اجرا گذاشتن نظام‌نامه‌ای که امتیازهای گسترده می‌داد فرو نشست.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["عقب‌نشینی واپسین پادگان‌های عثمانی از قلعه‌های بلگراد و صربستان", "b34217db"], "d": ["با فشار دولت‌های بزرگ و درخواست پافشارانه شاهزاده میهایلو، باب‌عالی پذیرفت واپسین پایگاه‌های نظامی‌ای را که در صربستان در دست داشت تخلیه کند؛ در 18 آوریل 1867 پرچم عثمانی در قلعه بلگراد پایین آورده شد و کلیدها به شاهزاده تسلیم گردید. بدین‌سان حضور نظامی عملی عثمانی که از 1521 ادامه داشت پایان یافت و واپسین مانع بزرگ بر راه صربستان به استقلال برداشته شد. مولایی پادشاه به مسئله‌ای تنها نمادین از پرچم و مالیات کاسته شد.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["دادن عنوان خدیو به والیان مصر", "09e10c12"], "d": ["با لابی پرشدت اسماعیل پاشا، از نسل سوم دودمان قوالایی، و پول‌هایی که به استانبول ریخت، به والی مصر عنوان خدیو داده شد که بر برتری او بر دیگر والیان تأکید می‌کرد. در همان سال‌ها شیوه جانشینی نیز به‌گونه‌ای تغییر یافت که از پدر به پسر می‌گذشت و به مصر اختیارات دارای ماهیت حاکمیتی مانند وام خارجی گرفتن، دادن نشان و داشتن کنسولگری شناخته شد. این گام‌ها نخستین حلقه زنجیره‌ای است که جدایی حقوقی مصر از عثمانی را شتاب بخشید.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["نظام‌نامه کرت: امتیازهای گسترده اداری برای جزیره", "12052262"], "d": ["برای پایان دادن به قیام سه‌ساله صدراعظم عالی پاشا شخصاً به جزیره رفت و با نظام‌نامه‌ای که به تأیید پادشاه منتشر شد، به کرتی‌ها شوراهای اداره مختلط، دادگاه‌های محلی، به‌کار رفتن زبان رومی در کارهای رسمی و آسانی‌های مالیاتی داده شد. این ترتیب فرمانروایی عثمانی را سی سال دیگر در جزیره برپا نگه داشت. اما امتیازهایی که به جمعیت مسیحی داده شد جایگاه کرتی‌های مسلمان را ضعیف کرد و تخم بحران 1896-1898 را کاشت.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["گشایش شورای دولت: بنیان‌گذاری شورای دولت عثمانی", "70b16497"], "d": ["با ارادهٔ 5 مارس 1868 مجلس احکام عدلیه دو بخش شد: کارهای اداری-تقنینی به شورای دولت و کارهای قضایی به دیوان احکام عدلیه سپرده شد؛ نهاد در باب‌عالی با مراسم گشوده شد و مدحت پاشا نخستین رئیس آن شد. مأموریت یافت لوایح قانون را فراهم آورد، اختلافات اداری را حل کند و محاکمه کارمندان را پیش ببرد. با ساختار مختلط اعضای مسلمان و غیرمسلمان، نخستین اجرای نهادی اندیشه تفکیک قوا در عثمانی شمرده می‌شود.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["گشایش کانال سوئز: کوتاه شدن راه هند از راه مصر", "377ccd04"], "d": ["ساخت که در 1859 آغاز شده بود ده سال طول کشید و کانال 163 کیلومتری که مدیترانه را به دریای سرخ می‌پیوندد با مراسمی باشکوه به بهره‌برداری رسید. چون راه پیوند اروپا به هند هزاران مایل کوتاه شد، مصر ناگهان به نقطه کلیدی بازرگانی جهانی بدل گشت. این ارزش ژئواستراتژیک علت اصلی اشغال مصر به دست انگلستان سیزده سال پس از گشایش کانال خواهد شد؛ و بدهی‌ای که کانال بر دوش مصر نهاد، خدیویت را به ورشکستگی می‌کشاند.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["بنیان‌گذاری اکسارخات بلغار: جدایی کلیسای بلغار از فنر", "33a8272c"], "d": ["با فرمان پادشاه کلیسایی مستقل (اکسارخات) از پاتریارکی روم جدا برپا شد و اینکه کدام قضاها به اکسارخات بسته شود به رأی‌گیری مردم سپرده شد. باب‌عالی هرچند این گام را برای شکستن نفوذ رومی برداشت، نتیجه برعکس شد: کلیسا به مرکز سازمان‌یافته هویت ملی بلغار و ادعای بلغار بر مقدونیه بدل شد. بدین‌سان بنیاد نهادی رقابت بلغار-رومی-صرب در بالکان و قیام‌های 1876 نهاده شد.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["قرار گرفتن عسیر زیر اداره مستقیم", "4559e099"], "d": ["با گشایش کانال سوئز و افزایش ارزش راهبردی دریای سرخ، آشکار شد که کوهستان‌های عسیر در میانهٔ راه خشکی یمن را نمی‌توان بی‌نظارت گذاشت. نیروهای رِدیف پاشا که برای لشکرکشی یمن بیرون آمدند، به ابها وارد شدند و منطقه را مستقیماً به اداره عثمانی پیوستند و سنجق عسیر برپا شد. به سبب جغرافیای کوهستانی و نفوذ ادریسی‌ها این تسلط هرگز کامل نشد.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["لشکرکشی مدحت پاشا به نجد: برپایی دوباره فرمانروایی عثمانی در لحسا", "7db51461"], "d": ["مدحت پاشا، والی بغداد، از کشمکش تاج‌وتخت درون خاندان سعودی بهره برد، به ساحل باختری خلیج بصره نیرو فرستاد و منطقه لحسا را با نام سنجق نجد به ولایت بصره بست. با گماشتن عبدالله بن فیصل به متصرفی فرمانروایی عثمانی بر کاغذ برپا شد. لشکرکشی هدفش بازداشتن گسترش نفوذ انگلیس در خلیج بود و همان سال به درآمدن قطر نیز زیر نظارت عثمانی انجامید.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["درگذشت صدراعظم عالی پاشا: پایان کادر تنظیمات", "1cf0141c"], "d": ["پس از مرگ فؤاد پاشا در 1869 و با درگذشت عالی پاشا که سیاست تنظیمات را به‌تنهایی بر دوش می‌کشید، نسل دیپلمات‌های کارکشته‌ای که سی سال سیاست خارجی دولت را می‌راندند به پایان رسید. اداره خودسرانه و هوادار روس محمود ندیم پاشا که جانشین او شد، اداره شخصی عبدالعزیز را استوار کرد. در پنج سال پس از مرگ عالی پاشا دارایی ورشکست شد، بالکان شورید و تغییر سلطنت ناگزیر گشت.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["برپایی نظارت عثمانی در قطر", "3b453165"], "d": ["به دعوت شیخ قاسم بن ثانی که زیر فشار انگلیس بود، نیروهای عثمانی در شبه‌جزیره قطر پیاده شدند و در پاییز 1871 نظارت عثمانی در منطقه برقرار گشت. قطر به‌عنوان قضایی وابسته به سنجق نجد سازمان یافت و شیخ به قائم‌مقامی گماشته شد. این اقدام عینی‌ترین دستاورد سیاست پیشروانه مدحت پاشا در خلیج علیه انگلستان شد؛ پرچم عثمانی تا 1913 بر شبه‌جزیره برافراشته بود.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["فرمان وراثت برای تونس — بیگی در خانوادهٔ محمد صادق پاشا", "1509ebb0"], "d": ["با فرمانی که به ابتکار خیرالدین پاشا — فرستادهٔ محمد صادق پاشا، بی تونس، به استانبول، که شکست فرانسه از پروس را فرصت شمرده بود — صادر شد، تونس به شرط وابستگی مستقیم به استانبول به شیوهٔ وراثت به محمد صادق پاشا و فرزندانش داده شد. بدون اجازهٔ پادشاه جنگ و گفت‌وگوی صلح نمی‌شد، هیچ سرزمینی از کشور به دیگری واگذار نمی‌گردید و درخواست سرباز عثمانی برآورده می‌شد. فرانسه فرمان را به رسمیت نشناخت؛ ده سال بعد تونس را اشغال کرد.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["گرفتن صنعا: برپایی دوباره اقتدار عثمانی در یمن", "978e20a0"], "d": ["چون با گشایش کانال سوئز ارزش راهبردی دریای سرخ افزایش یافت، باب‌عالی سپاه فرقه احتیاطیه را به فرماندهی احمد مختار پاشا به یمن فرستاد. با گرفتن صنعا اقتدار دولت در یمن درونی که دو سده عملاً از دست رفته بود دوباره برپا شد و منطقه به ولایت بدل گردید. اما کشمکش با امامان زیدی هرگز پایان نیافت؛ قیام‌های 1891، 1898 و 1904 پرهزینه‌ترین و درازترین جبهه درونی عثمانی را ساخت. جاهای دیگری که در همین تاریخ پیوستند: صنعا، تعز.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["آغاز قیام هرزگوین: شعله‌ور شدن دوباره مسئله شرق", "571b18ec"], "d": ["قیام روستاییان مسیحی پیرامون نوسینیه به سبب مالیات‌های سنگین و فشار اعیان زود به سراسر هرزگوین سرایت کرد و با داوطلبان صربستان و مونته‌نگرو تغذیه شد. قیامی که اصلاحاتی را که اتریش و روسیه تحمیل می‌کردند برانگیخت، سال بعد قیام‌های بلغار و اعلان جنگ صرب-مونته‌نگرو را به راه انداخت. بدین‌سان نخستین حلقه زنجیره بزرگی که به جنگ 93 و از دست رفتن بالکان با پیمان برلین می‌انجامید گشوده شد.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["ورشکستگی دارایی عثمانی: نیم شدن پرداخت‌های بدهی خارجی", "2cac2fa5"], "d": ["وام‌هایی که از 1854 پیاپی گرفته شد، هزینه‌های جنگ کریمه، ساخت کاخ‌ها و قحطی 1873-74 آناتولی کسری بودجه را به پرتگاهی بیش از پنج میلیون لیره بدل کرد. دولت محمود ندیم پاشا با اعلام اینکه پرداخت‌های بهره و اصل بدهی پنج سال به نصف کاهش می‌یابد عملاً مهلت‌گذاری اعلام کرد. این تصمیم که در بورس‌های اروپا واکنش بزرگی برانگیخت، روندی را آغاز کرد که شش سال بعد با فرمان محرم و بنیان‌گذاری اداره بدهی‌های عمومی پایان می‌یافت.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["خلع مراد پنجم و جلوس عبدالحمید دوم", "cffb2271"], "d": ["مراد پنجم که پس از برکناری عبدالعزیز بر تخت نشست، به سبب سلامت روانی که مرگ عمویش و رویداد حسن چرکس آن را لرزانده بود نتوانست کار کند؛ از سلطنت نود و سه‌روزه‌اش تنها در هفت روز داوری‌اش درست بود. با فتوای شیخ‌الاسلام خلع شد و برادرش عبدالحمید دوم جای او نشست. پادشاه تازه با دادن این وعده به مدحت پاشا که مشروطیت را اعلام خواهد کرد بر تخت نشست؛ دورانی که سی و سه سال خواهد کشید آغاز می‌شد.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["کنفرانس کشتی‌سازی: تحمیل اصلاحات بالکان از سوی دولت‌های بزرگ", "b5006a2c"], "d": ["کنفرانسی که دولت‌های بزرگ برای حل بحران بالکان در استانبول گرد آوردند، تقسیم بلغارستان به دو ولایت خودمختار و اجرای اصلاحات زیر نظارت بین‌المللی در بوسنی و هرزگوین را خواست. باب‌عالی در روز گشایش کنفرانس با شلیک توپ اعلان قانون اساسی را خبر داد و کوشید تحمیل‌ها را با اصلاحات قانون اساسی پاسخ دهد. نمایندگان آن را دفع‌الوقت شمردند و در 20 ژانویه 1877 پراکنده شدند؛ چهار ماه بعد روسیه اعلان جنگ کرد.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["گشایش نخستین مجلس مبعوثان در دلمه‌باغچه", "429bb279"], "d": ["115 نماینده‌ای که بنا بر قانون اساسی برگزیده شده بودند، در 19 مارس 1877 با مراسمی در تالار مراسم کاخ دلمه‌باغچه نخستین بار گرد آمدند؛ بدین‌سان دوران مجلس نمایندگی در تاریخ عثمانی آغاز شد. نمایندگان مسلمان و غیرمسلمان دولت را به‌سختی بازخواست کردند و اداره جنگ و مسئولیت وزیران را به بحث گذاشتند. این مخالفت دلیرانه علت اصلی کوتاه شدن عمر مجلس می‌شد.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["آغاز دفاع پلوونا: ایستادگی غازی عثمان پاشا", "0e04a878"], "d": ["عثمان پاشا که در جنگ 93 برای قطع راه استانبول به روی سپاه روس که از دانوب گذشته بود از ویدین به پلوونا لشکر کشید، شهرک را با استحکامات و سنگر مستحکم کرد و دفاعی افسانه‌ای را که پنج ماه کشید آغاز نمود. سه یورش بزرگ پیاپی روس و رومانی با تلفات سنگین دفع شد و سپاهی که تزار الکساندر دوم شخصاً اداره می‌کرد ناگزیر به محاصره شد. پلوونا به‌عنوان درخشان‌ترین موفقیت دفاعی سپاه عثمانی در سده نوزدهم در تاریخ ماند.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["سقوط پلوونا: فروپاشی جبهه دانوب", "185e7602"], "d": ["عثمان پاشا که در محاصره پنج‌ماهه آذوقه‌اش پایان یافته بود، از راه رود ویت به عملیات بیرون‌تازی دست زد؛ با زخمی و اسیر شدنش شهر تسلیم شد. فرماندهان روس پاشای اسیرشده را با بازگرداندن شمشیرش درود گفتند و به عثمان پاشا عنوان «غازی» داده شد. با سقوط پلوونا راه سپاه روس گشوده شد؛ در دو ماه صوفیه، فیلیپوپولیس و ادرنه افتاد و پیشروان روس به یشیل‌کوی رسیدند.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["اشغال صوفیه به دست نیروهای روس", "ef369d22"], "d": ["سپاه روس که پس از سقوط پلوونا از بالکان گذشته بود، وارد صوفیه‌ای شد که بی‌دفاع مانده بود. شهر دیگر به اداره عثمانی بازنخواهد گشت و در پایان 1878 پایتخت شاهزاده‌نشین خودمختار بلغارستان و در 1879 به‌طور عملی پایتخت آن خواهد شد. بر نقشه صوفیه از این تاریخ از اداره مستقیم عثمانی بیرون می‌رود و به اشغال موقت روس و سپس اداره خودمختار بلغار می‌رسد.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["آتش‌بس ادرنه: خاموشی سلاح‌ها در جنگ 93", "1f899180"], "d": ["با سقوط پیاپی صوفیه، فیلیپوپولیس و ادرنه و رسیدن سپاه روس به سواحل مرمره، باب‌عالی ناگزیر آتش‌بس خواست. آتش‌بسی که در ادرنه امضا شد، شرایط صلح مقدماتی مانند خودمختاری بلغارستان، استقلال مونته‌نگرو-صربستان-رومانی و غرامت سنگین جنگی را بر عثمانی پذیراند. این شرایط یک ماه بعد در سن‌استفانو به متن پیمان بدل می‌شد.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["تعطیل بی‌پایان مجلس مبعوثان به دست عبدالحمید دوم", "e770b540"], "d": ["با انتقادهای سخت نمایندگانی که دولت و کاخ را مسئول فاجعه‌آمیز پایان یافتن جنگ می‌دانستند، عبدالحمید دوم با تکیه بر اختیاری که قانون اساسی به او داده بود مجلس را بی‌پایان تعطیل کرد. نخستین پارلمان عثمانی که حدود یازده ماه کار کرده بود بدین‌سان بسته شد و دوران استبداد که سی سال خواهد کشید آغاز گشت. مجلس تنها پس از انقلاب 1908 دوباره می‌توانست گرد آید.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["پیمان سن‌استفانو: طرح بلغارستان بزرگ", "2c7cc611"], "d": ["پیمان سن‌استفانو که جنگ 93 را پایان داد، بلغارستانی خودمختار و غول‌آسا برمی‌ساخت که تا اژه می‌رسید و مقدونیه را دربر می‌گرفت؛ استقلال صربستان، مونته‌نگرو و رومانی را می‌شناخت؛ قارص، اردهان، باتوم و بایزید را به روسیه می‌گذاشت و افزون بر آن غرامت جنگی‌ای که پرداختنش ناممکن بود تحمیل می‌کرد. این متن که روسیه را به مدیترانه می‌رساند واکنش شدید انگلستان و اتریش را برانگیخت. بی‌آنکه اجرا شود در چهار ماه با کنگره برلین از نو سامان یافت؛ با این همه به‌عنوان سندی که پایان روم‌ایلی عثمانی را اعلام می‌کرد ماند.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["قارص، اردهان و باتومی به روسیه واگذار شد — الویهٔ ثلاثه", "99bdfad2"], "d": ["با پیمان برلین دولت عثمانی قارص، اردهان و باتومی را در برابر بخشی از غرامت جنگی به روسیه واگذاشت؛ اما بایزید (دوغوبایزید) و دره الشکرد که در ایاستفانوس به روسیه داده شده بود، در دست عثمانی ماند. هرچند باتومی به‌عنوان بندر آزاد واگذار شد، این وضعیت را تنها تا 1886 توانست نگه دارد. روس‌ها قارص را ولایتی وابسته به فرمانداری کل ماوراء قفقاز با مرکز تفلیس ساختند؛ از ساکنان الویهٔ ثلاثه شمارشان تا 100.000 تن ناگزیر به مهاجرت به سوی ارزروم شد. با همین پیمان بسارابیای جنوبی (کیلیا، کاهول، بولگراد) از رومانی به روسیه بازگردانده شد.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["اشغال بوسنی-هرزگوین و یگی‌پازار به دست اتریش-مجارستان", "e5f901df"], "d": ["سپاهیان اتریش-مجارستان با تکیه بر اختیاری که پیمان برلین داده بود وارد بوسنی شدند؛ هرچند دولت عثمانی پذیرفته بود مقاومت نکند، مردم مسلمان-ارتدوکس بومی در سارایوو و موستار سلاح برداشتند و سه ماه مقاومتی سخت نشان دادند. اشغال تنها در 20 اکتبر 1878 تکمیل شد. حاکمیت حقوقی پادشاه تا 1908 بر کاغذ ماند، اما بوسنی چهارسده‌ای عثمانی عملاً از دست رفت و موج بزرگ مهاجرت مسلمانان آغاز شد. سکونتگاه‌های دیگری که در همین تاریخ از دست رفتند: بانالوکا.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["فرمان محرم و بنیان‌گذاری اداره بدهی‌های عمومی", "02b7cc03"], "d": ["گفتگوهایی که پس از ورشکستگی 1875 با نمایندگان دولت‌های بستانکار انجام شد، به فرمانی به تاریخ 28 محرم 1299 (20 دسامبر 1881) انجامید: اصل بدهی بیش از نیم کاهش یافت، در برابر آن پربارترین اقلام درآمد مانند عوارض نمک، تنباکو، ابریشم، تمبر و ماهی به اداره بدهی‌های عمومی که بستانکاران مستقیماً اداره می‌کردند واگذار شد. این اداره که هزاران کارمند به کار می‌گرفت، به تشکیلات مالی جداگانه‌ای در درون دولت بدل شد. این تاریخ پایان عملی استقلال مالی عثمانی شمرده می‌شود.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["سواکن — تنها بندری که به مهدی نیفتاد", "5a37b198"], "d": ["از فوریه 1884 در حالی که همه مناطق شرق سودان جز سواکن به فرمانروایی محمد احمد مهدی درآمد، بندر با پشتیبانی نظامی نیرویی سه‌گردانی از انگلیس به فرماندهی ژنرال گراهام برپا ماند. این آغاز دورانی بود که وضع عملی و حقوقی از هم جدا شد: هرچند ساحل عملاً زیر نظارت نظامی انگلیس بود، پیوند اداری آن در 1885 از مصر گرفته می‌شد و مستقیماً به ولایت یمن، یعنی باب‌عالی، بسته می‌شد — این نظم تا 1888 که فرانسه زیلع را اشغال کرد ادامه یافت.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["کشته شدن مدحت پاشا در زندان طائف", "f4562261"], "d": ["مدحت پاشا، معمار قانون اساسی و نام نمادین نخستین مشروطیت، که در دادگاه یلدیز درباره مرگ عبدالعزیز مجرم شناخته شده و حکم اعدامش به تبعید تبدیل شده بود، به طائف فرستاده شده بود. بنا بر گزارش TDV در شب 7-8 مه 1884 در سلولش خفه و کشته شد و علت رسمی بیماری «شیرپنجه» اعلام گردید. مرگ او در دوران عبدالحمید دوم نماد برچیده شدن مخالفت قانون اساسی شد.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["دادن امتیاز راه‌آهن حیدرپاشا-آنکارا به آلمانی‌ها", "5705b163"], "d": ["با اراده پادشاه امتیاز ساخت و بهره‌برداری خط حیدرپاشا-آنکارا به آلفرد فون کائولا، بانکداری که نماینده دویچه بانک بود، داده شد و شرکت راه‌آهن آناتولی برپا شد. این امتیاز نقطه عطفی شد که انحصار انگلیسی-فرانسوی را در حمل‌ونقل و سیاست خارجی عثمانی شکست و نفوذ آلمان را جا انداخت. با امتیاز خط بغداد که یازده سال بعد به همین شرکت داده می‌شد، رؤیای «برلین-بغداد» پدید می‌آمد که به یکی از محورهای اصلی رقابت قدرت‌های بزرگ پیش از جنگ جهانی یکم بدل می‌شد.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["بنیان‌گذاری جمعیت اتحاد عثمانی در استانبول", "b7187939"], "d": ["چهار دانشجوی طب نظامی جمعیت اتحاد عثمانی را به‌عنوان سازمانی پنهان علیه اداره استبدادی بنیان نهادند؛ این ساختار زود به جمعیت اتحاد و ترقی بدل شد که همه عناصر مخالف جنبش ترکان جوان را زیر سقف خود گرد می‌آورد. سازمان‌یابی مبتنی بر سلول با تبعیدیان اروپا و افسران سالونیک یکی شد. کادری که در 1908 مشروطیت دوم را اعلام می‌کرد و پس از 1913 دولت را به‌تنهایی اداره خواهد کرد، از همین سلول کوچک دانشجویی برآمد.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["یورش به بانک عثمانی: اقدام داشناک‌ها در غلطه", "08b3095f"], "d": ["گروهی مسلح از سازمان ارمنی داشناکسوتیون برای جلب توجه اروپا به مسئله ارمنی مقر مرکزی بانک عثمانی در غلطه را گرفت، گروگان گرفت و تهدید کرد ساختمان را منفجر می‌کند. بحران با میانجی‌گری سفیران و در برابر بیرون بردن اقدام‌کنندگان از کشور با کشتی پایان یافت. رویدادهای خونینی که در روزهای پس از یورش در استانبول روی داد، در تبدیل مسئله ارمنی به اهرم دخالت بین‌المللی تعیین‌کننده بود.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["آغاز جنگ عثمانی و یونان 1897: جبهه تسالی", "33e490ab"], "d": ["با پیاده کردن ناوگان و نیرو از سوی یونان در کرت و حمله‌های گروه‌های مسلح در مرز روم‌ایلی دولت عثمانی اعلان جنگ کرد. سپاه عثمانی که هیئت اصلاح آلمانی آموزشش داده بود در تسالی به سرعت پیشروی کرد و ظرف یک ماه ینی‌شهر، چاتالجه و دومکه را گرفت؛ سپاه یونان پراکنده شد. با دخالت دولت‌های بزرگ سرزمین‌های به‌دست‌آمده بازگردانده شد، اما جنگ تنها پیروزی نظامی قطعی دوران عبدالحمید دوم ماند و نتوانست مانع از دست رفتن عملی کرت شود.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["دادن امتیاز خط قونیه-بغداد به آلمانی‌ها", "fd8b6cbd"], "d": ["پس از سفر قیصر ویلهلم دوم در 1898 به استانبول و دمشق، به شرکت راه‌آهن آناتولی امتیاز مقدماتی خطی که از قونیه تا بغداد و بصره کشیده می‌شد داده شد. پروژه راه‌آهن بغداد برای عثمانی به معنای تقویت نظارت مرکز بر ولایات عربی و برای آلمان به معنای رسیدن به خلیج بصره بود. این پروژه که انگلستان و روسیه به‌سختی با آن مخالف بودند، از بحث‌برانگیزترین پرونده‌های رقابت امپریالیستی منتهی به جنگ جهانی یکم شد.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["آغاز ساخت راه‌آهن حجاز در دمشق", "62f58f68"], "d": ["خطی که عبدالحمید دوم با ارادهٔ 2 مه 1900 فرمان داد، در 1 سپتامبر 1900 با مراسمی رسمی در دمشق ساختش آغاز شد. این پروژه که یکسره با کمک‌های گردآمده از جهان اسلام و کار مهندسان و سربازان عثمانی ساخته شد، سفر حاجیان دمشق-مدینه را از چهل روز به پنج روز کاهش داد. هم اثری اعتباربخش بود که اقتدار معنوی خلافت را استوار می‌کرد و هم سرمایه‌گذاری راهبردی که نظارت نظامی بر حجاز را تقویت می‌نمود.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["برنامه مورتسشتگ: نظارت بین‌المللی بر اصلاحات در مقدونیه", "4c7464da"], "d": ["پس از قیام ایلیندن امپراتوران روس و اتریش در مورتسشتگ دیدار کردند و بسته اصلاحات تازه‌ای برای مقدونیه فراهم آوردند. برنامه گماشتن دو مأمور غیرنظامی بیگانه کنار بازرس کل عثمانی، بازسازماندهی ژاندارمری به دست افسران اروپایی و تغییر مرزهای اداری بر پایه ملیت را پیش‌بینی می‌کرد. باب‌عالی با این دلیل که حقوق حاکمیت آسیب می‌بیند مقاومت کرد، اما در برابر فشار مشترک ناگزیر پذیرفت؛ برنامه از عوامل بنیادین شتاب‌دهنده سازمان‌یابی اتحادی در میان افسران جوان شد.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["درگذشت مراد پنجم", "396659a7"], "d": ["مراد پنجم که در 1876 حدود سه ماه بر تخت ماند و خلع شد، پس از تلاش‌هایی برای بازگرداندن او به تخت، بیست و هشت سال زیر مراقبت سخت زندانی زیست و بر اثر دیابت درگذشت. در آرامگاه جدید خواتین در ینی‌جامی در کنار مادرش به خاک سپرده شد. او به‌عنوان کوتاه‌مدت‌ترین پادشاه عثمانی در تاریخ ماند.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["از دست رفتن صنعا به امام یحیی", "e7f876cb"], "d": ["قیامی که امام زیدی یحیی حمیدالدین در 1904 آغاز کرد، در آوریل 1905 با سقوط صنعا پس از محاصره پایان یافت؛ شهر از اداره عثمانی بیرون رفت و در طول محاصره گرسنگی و بیماری همه‌گیر پدید آمد. جغرافیای کوهستانی یمن، درازی خطوط تدارکات و مشروعیت محلی امامت زیدی فرمانروایی عثمانی در آنجا را از آغاز شکننده کرده بود. شهر پنج ماه بعد با بهای تلفات سنگین بازگرفته خواهد شد، اما مسئله یمن تا 1918 بسته نخواهد شد.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["سوءقصد یلدیز: حمله بمب‌گذاری‌شده به عبدالحمید دوم", "1ee2e1a6"], "d": ["سازمان داشناکسوتیون با منفجر کردن لاندوی بمب‌گذاری‌شده با زمان‌سنج در برابر کالسکه پادشاه که از سلام جمعه بیرون می‌آمد سوءقصد سامان داد؛ چند دقیقه تأخیر عبدالحمید که با شیخ‌الاسلام گفتگو می‌کرد جانش را نجات داد. در انفجار بیست و شش تن مردند و بیش از پنجاه تن زخمی شدند. رویداد وسواس امنیتی پادشاه و اداره استبدادی متکی بر تشکیلات جاسوسی را سخت‌تر کرد؛ و موضوع شعر «بیر لحظه‌ی تأخر» توفیق فکرت نیز شد.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["بازپس‌گیری صنعا: سرکوب قیام امام یحیی", "dec3b8f9"], "d": ["قیامی که در 1904 به رهبری امام زیدی یحیی آغاز شد، در آوریل 1905 با سقوط صنعا پایان یافت و در شهر گرسنگی و بیماری همه‌گیر پدید آمد. سپاه‌های کمکی به فرماندهی علی‌رضا پاشا و احمد فیضی پاشا با عملیاتی که میان 15 ژوئیه و 1 سپتامبر 1905 انجام دادند و نیروهای تعز نیز پشتیبانش بودند، با بهای تلفات سنگین شهر را بازگرفتند و قیام سرکوب شد. عملیات یمن به سپاه عثمانی ده‌ها هزار تلفات و بار مالی عظیم آورد؛ ترس از «تبعید به یمن» در میان افسران روم‌ایلی در رأس شکایت‌هایی بود که سازمان‌یابی اتحادی را تغذیه می‌کرد.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["گرد آمدن نخستین مجلس مبعوثان مشروطیت دوم", "e7fd2716"], "d": ["مجلسی که پس از وقفه‌ای سی‌ساله با انتخابات دو درجه‌ای شکل گرفت، در 17 دسامبر 1908 با نطق پادشاه گشوده شد و احمد رضا بیگ، رهبر جنبش ترکان جوان، به ریاست آن برگزیده شد. مجلس که از نمایندگان ترک، عرب، آلبانیایی، یونانی، ارمنی و یهودی تشکیل می‌شد، واپسین آزمون بزرگ آرمان عثمانی‌گری بود. اما استقلال بلغارستان، الحاق بوسنی و اعلان پیوستن کرت به یونان پیش از گشایش مجلس این خوش‌بینی را در سایه برده بود.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["سپاه حرکت و خلع عبدالحمید دوم: جلوس محمد پنجم رشاد", "6a65a704"], "d": ["سپاه حرکت که پس از رویداد 31 مارت از سالونیک راه افتاده بود، در شب 22-23 آوریل از چهار سو وارد استانبول شد و در 24 آوریل کاخ یلدیز تسلیم گشت. مجلس عمومی ملی در 27 آوریل خلع عبدالحمید دوم را تصمیم گرفت؛ پادشاه به سالونیک فرستاده شد و برادرش محمد پنجم رشاد بر تخت نشانده شد. اداره شخصی سی و سه‌ساله بدین‌سان پایان یافت، اما جای آن را دورانی گرفت که در آن پادشاه نمادین شد و اتحاد و ترقی با پشتیبانی سپاه حکومت می‌کرد.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["قیام آلبانی: مقاومت مسلحانه در کوزوو و اشکودره", "93ed30c6"], "d": ["سیاست مالیاتی مرکزگرایانه دولت اتحادی، کارزار گردآوری سلاح و بحث الفبای لاتین، طایفه‌های آلبانیایی را که تا آن روز از وفادارترین عناصر به دولت شمرده می‌شدند به قیام واداشت. هرچند سپاه به فرماندهی محمود شوکت پاشا قیام را به‌سختی سرکوب کرد، ناآرامی در 1911 و 1912 دوباره شعله کشید. این قیام‌ها هم سپاه عثمانی را در آستانه جنگ بالکان فرسود و هم زایش جنبش ملی آلبانیایی را شتاب بخشید.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["پیمان اوشی: واگذاری طرابلس غرب و بنغازی به ایتالیا", "4ffa1fd2"], "d": ["باب‌عالی که در برابر تدارک جنگ دولت‌های بالکان جرأت کشمکش در دو جبهه را نداشت، در شهرک اوشی سوئیس با ایتالیا صلح پنهان امضا کرد و طرابلس غرب و بنغازی را واگذاشت. دولت عثمانی بدین‌سان واپسین سرزمین خود را در آفریقا از دست داد؛ در برابر آن بازگردانده شدن رودس و دوازده جزیره‌ای که ایتالیا اشغال کرده بود وعده داده شد، اما این وعده هرگز عملی نشد. هنگام امضای پیمان جنگ بالکان از پیش آغاز شده بود. با این رویداد Murzuk (فزان)، Gât، Sebha، Ubârî، Tırgan (Traghan)، Zevîle (Zawila) و el-Katrûn (فزان (سنجق ولایت طرابلس غرب)) به اداره ایتالیا گذشت.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["اشغال لمنوس از سوی یونان", "9555af1d"], "d": ["در جنگ نخست بالکان ناوگان یونان لمنوس را اشغال کرد؛ بندر مودروس جزیره برای محاصرهٔ تنگهٔ چاناق‌قلعه پایگاه شد. جزیره در لوزان (24 ژوئیه 1923) به یونان واگذار شد.", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["اشغال تاسوس از سوی یونان", "6c03c7f0"], "d": ["در جنگ نخست بالکان یونان تاسوس و ساموتراکی را اشغال کرد.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["اشغال ساموتراکی از سوی یونان", "911e82a3"], "d": ["در جنگ نخست بالکان یونان ساموتراکی را اشغال کرد.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["اشغال لسبوس (میدیلی) از سوی یونان", "6b2b07ba"], "d": ["ناوگان یونان در میدیلی به خشکی فرود آمد؛ جزیره در پایان جنگ نخست بالکان به دست ارتش و ناوگان یونان گرفته شد. کنفرانس لندن (مه 1913) وضعیت را تأیید کرد.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["فرود یونان در خیوس", "901c6539"], "d": ["یونانی‌ها در جنگ نخست بالکان، در خیوس که در 7 آوریل 1912 بمباران شده بود فرود آمدند؛ پادگان عثمانی در 3 ژانویه 1913 تسلیم شد. جزیره با پیمان لوزان (24 ژوئیه 1923) به یونان واگذار شد.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["کشته شدن صدراعظم محمود شوکت پاشا در استانبول با سوءقصد", "68e60e63"], "d": ["محمود شوکت پاشا که پس از یورش باب‌عالی به صدراعظمی گماشته شده بود، هنگام رفتن به نظارت حربیه نزدیک چارشی‌قاپی با تیراندازی به کالسکه‌اش کشته شد. اتحاد و ترقی سوءقصد را به گردن مخالفان انداخت و موج گسترده بازداشت و اعدام را آغاز کرد و فرقه حریت و ائتلاف عملاً تصفیه شد. با این رویداد دیکتاتوری تک‌حزبی اتحادیان که بر سه‌گانه انور-طلعت-جمال تکیه داشت، قطعاً برپا شد.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["آغاز جنگ دوم بالکان: کشمکش متحدان بر سر تقسیم", "48d088a2"], "d": ["متحدان بالکان که نتوانستند سرزمین‌هایی را که با پیمان لندن از عثمانی گرفته بودند میان خود تقسیم کنند، به جان هم افتادند؛ با حمله بلغارستان به مواضع صرب و یونان جنگ دوم آغاز شد. چون رومانی و مونته‌نگرو نیز در برابر بلغارستان وارد جبهه شدند، سپاه بلغار فروریخت. دولت عثمانی از این فرصت بهره برد، از خط میدیه-ائنز که پیمان لندن ترسیم کرده بود گذشت و تراکیه شرقی را همراه با ادرنه بازپس گرفت.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["پیمان استانبول: صلح با بلغارستان و ثبت ادرنه", "c8c18b2d"], "d": ["پیمانی که پس از جنگ دوم بالکان میان دولت عثمانی و بلغارستان امضا شد، با پذیرفتن رود مریچ به‌عنوان مرز، ماندن ادرنه، کیرک‌کلیسه، دیمتوکا و تراکیه شرقی را در دست عثمانی از نظر حقوقی ثبت کرد. دده‌آغاج در بلغارستان گذاشته شد (کاوالا نیز پس از اشغال بلغار در پاییز 1912 در ژوئیه 1913 به یونان رسیده و با پیمان بخارست 10 اوت 1913 در یونان ثبت شده بود)، مبادله متقابل جمعیت میان دو کشور و حقوق مسلمانان در بلغارستان سامان یافت. تضمین تنها پاره سرزمینی که از فاجعه بالکان بازپس گرفته شد، همین متن است. جاهای دیگری که در همین تاریخ پیوستند: گومولجینه.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["بازپس‌گیری بوزجاآدا و ایمروز — پیمان آتن", "ec084d09"], "d": ["از جزایر شمال اژه که یونان در جنگ بالکان اشغال کرده بود، بوزجاآدا و ایمروز که دهانهٔ تنگه را در اختیار دارند، در مذاکرات پیمان آتن برای دفاع از چاناق‌قلعه ضروری شمرده شدند و به عثمانی بازگردانده شدند. جزایر دیگر در دست یونان ماند. این دو جزیره آخرین سرزمین‌هایی بود که امپراتوری در اژه در دست داشت و در لوزان نیز به ترکیه واگذار شد.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["پیمان آتن: صلح با یونان و واگذاری سالونیک و یانینا", "8e94def7"], "d": ["پیمانی که میان دولت عثمانی و یونان امضا شد، رسیدن سالونیک، یانینا و مقدونیه جنوبی را که در جنگ بالکان از دست رفته بود به یونان رسماً شناخت و از حقوق عثمانی بر کرت چشم پوشید. حقوق دینی و مالکیت مسلمانان مانده در یونان، منزلت وقف‌ها و گماشتن مفتیان به تفصیل سامان یافت. منزلت جزایر اژه بی‌حل ماند و به‌عنوان سرچشمه تنش پیوسته میان دو دولت برجا ماند.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["امضای پیمان اتحاد پنهان عثمانی و آلمان در استانبول", "0472efb3"], "d": ["به‌محض درگرفتن جنگ در اروپا، در عمارت صدراعظم سعید حلیم پاشا پیمان اتحادی پنهان میان دولت عثمانی و آلمان امضا شد؛ متن پیش‌بینی می‌کرد در صورت وارد شدن روسیه به جنگ علیه آلمان عثمانی نیز در کنار آلمان بایستد. پیمان حتی از کابینه پنهان داشته شد و تنها چهار تن از آن آگاه بودند. سه ماه بعد با یورش دریای سیاه دولت عثمانی عملاً به جنگ کشانده می‌شد و سرنوشت امپراتوری با این سند بسته می‌گشت.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["برچیدن یک‌جانبه کاپیتولاسیون‌ها", "ec773d18"], "d": ["دولت عثمانی در لحظه‌ای که اروپا درگیر جنگ بود، اعلام کرد کاپیتولاسیون‌هایی را که امتیازهای قضایی، مالی و گمرکی به بیگانگان می‌داد از 1 اکتبر 1914 یک‌جانبه برچیده است. پایان دادن به این نظام امتیازی چهارسده‌ای در داخل کشور با شور بزرگ استقلال پذیرفته شد و در استانبول جشن‌ها برپا گردید. همه دولت‌ها از جمله آلمان متحد به تصمیم اعتراض کردند؛ کاپیتولاسیون‌ها تنها در 1923 در لوزان برای همیشه به تاریخ می‌پیوست.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["یورش دریای سیاه: بمباران بنادر روس به دست ناوگان عثمانی", "8ad4ef61"], "d": ["گوئبن و برسلاو (یاووز و میدیلی) که از آلمان گریخته و به‌گونه «خریداری‌شده» به ناوگان عثمانی پیوسته بودند، به فرماندهی دریاسالار سوشون به دریای سیاه رفتند، بنادر روس را به توپ بستند و کشتی‌ها را غرق کردند. این فرمان که انور پاشا پنهان از کابینه داد، بی‌طرفی را عملاً پایان داد. در یک هفته روسیه، انگلستان و فرانسه اعلان جنگ کردند و دولت عثمانی بی‌بازگشت وارد جنگ جهانی یکم شد.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["گرفتن فاو به دست نیروهای انگلیسی-هندی — گشوده شدن جبهه عراق", "08663813"], "d": ["بامداد روز پس از اعلان جنگ دولت‌های ائتلاف به دولت عثمانی، تیپ انگلیسی-هندی که در بحرین منتظر بود در فاو، در دهانه شط‌العرب، پیاده شد. یگان کوچک عثمانی در قلعه ویران فاو زیر آتش کشتی‌های جنگی عقب نشست و ایستگاه خط تلگراف هند به دست انگلیسی‌ها افتاد. جبهه عراق بدین‌سان گشوده شد.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["اعلان جهاد اکبر: خواندن فتوای جهاد در مسجد فاتح", "2a6174e8"], "d": ["پنج فتوایی که شیخ‌الاسلام اورگوپلو خیری افندی داد، به نام خلیفه-پادشاه در مسجد فاتح خوانده شد و همه مسلمانان به جهاد علیه دولت‌های ائتلاف فراخوانده شدند. این اقدام که آلمان امید بسیار بدان بسته بود، هدفش برانگیختن مسلمانان مستعمرات انگلیس و فرانسه بود. قیام همگانی مورد انتظار روی نداد؛ برعکس شورش شریف حسین، امیر مکه، با پشتیبانی انگلیس دو سال بعد مرزهای نفوذ سیاسی خلافت را به‌تلخی نشان داد.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["تسلیم قرنه به انگلیسی‌ها", "621d36b0"], "d": ["نیروهای صبحی بیگ، والی بصره، که پس از سقوط بصره به قرنه، محل پیوستن دجله و فرات، عقب نشسته بودند، پس از درگیری‌های 4-8 دسامبر در بامداد 9 دسامبر 1914 تسلیم شدند.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["عملیات ساری‌قمیش: فاجعه در جبهه قفقاز", "5cbde7f0"], "d": ["انور پاشا برای بازپس‌گرفتن قارص-اردهان-باتوم که در 1878 از دست رفته بود و برانگیختن ترک‌های قفقاز، ارتش سوم را در زمستان به مانوری سوق داد که می‌خواست نیروهای روس را از راه کوه‌های الله‌اکبر محاصره کند. به سبب تجهیزات ناکافی زمستانی، تمام شدن تدارکات و کولاکی که تا منفی سی درجه می‌رسید، سپاه پیش از ورود به نبرد آب شد؛ ده‌ها هزار سرباز یخ‌زده مردند. عملیات از سنگین‌ترین فاجعه‌های عثمانی در جنگ شد و جبهه شرق را دو سال بی‌دفاع گذاشت.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["نخستین عملیات کانال: حمله به سوئز از راه صحرای سینا", "02dd72f5"], "d": ["جمال پاشا، فرمانده ارتش چهارم، برای رهانیدن مصر از اشغال انگلیس و بستن کانال سوئز به روی رفت‌وآمد، حمله‌ای از صحرای سینا ترتیب داد. هرچند یگان‌های عثمانی به کرانه شرقی کانال رسیدند و بخشی توانست بگذرد، با برتری انگلیس و روی ندادن قیام مردمی مصر که انتظارش می‌رفت عقب نشستند. عملیات به هدف نرسید، اما با ناگزیر کردن انگلستان به نگه داشتن نیرویی بزرگ در مصر تأثیری راهبردی غیرمستقیم پدید آورد.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["صدور قانون اعزام و اسکان (تهجیر)", "2f2bc22c"], "d": ["پس از قیام وان و پیشروی روس، دولت قانونی موقت صادر کرد که به فرماندهان سپاه اجازه می‌داد جمعیتی را که امنیت پشت جبهه را برهم می‌زند ارزیابی می‌شد به مناطق دیگر منتقل کنند و پادشاه در 27 مه 1915 آن را تصویب کرد. در نتیجه اجرا بخش بزرگ جمعیت ارمنی ولایات شرق و جنوب آناتولی به سوی سوریه و موصل اعزام شد؛ در جریان اعزام به سبب بیماری، گرسنگی و حمله‌ها تلفات جانی بسیار بزرگی روی داد. این تصمیم به‌عنوان سنگین‌ترین و امروز نیز بحث‌برانگیزترین مسئله سال‌های پایانی عثمانی برجا مانده است.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["نیروهای عثمانی موش را از اشغال روسیه بازپس گرفتند", "fb1be113"], "d": ["شش ماه پس از نخستین اشغال موش از سوی روس‌ها، سپاه شانزدهم عثمانی در ضدحملهٔ بیتلیس-موش به شهرک وارد شد.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["موش دوباره به دست روس‌ها افتاد", "43ad8a03"], "d": ["بر اثر ضدحملهٔ روسیه، دستهٔ عثمانی موش را تخلیه کرد؛ شهرک میان 22-25 اوت 1916 دوباره اشغال روسیه شد و تا بهار 1917 در دست ماند.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["موش قطعاً از اشغال روسیه رها شد", "f0e89703"], "d": ["موش که در جنگ جهانی اول زیر اشغال روسیه درآمده بود، در 1 مه 1917 به‌دست نیروهای عثمانی قطعاً بازپس گرفته شد.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["درگذشت عبدالحمید دوم در کاخ بیلربیی", "c9662582"], "d": ["عبدالحمید دوم که در 1909 از تخت برکنار شده و نخست به سالونیک و با از دست رفتن شهر در جنگ بالکان به استانبول آورده شده و در کاخ بیلربیی در حبس خانگی نگه داشته می‌شد، درگذشت. او در سلطنت سی و سه‌ساله‌اش کوشیده بود با دور نگه داشتن دولت از جنگ‌ها وقت بخرد، اما با اداره استبدادی نیز یاد می‌شد. پیکرش با جمعیتی بزرگ در آرامگاه محمود یکم در دیوان‌یولو به خاک سپرده شد؛ مرگ او با سال جنگی‌ای همزمان شد که نظامی که برپا کرده بود از پیش برچیده شده بود.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["پیمان برست-لیتوفسک: بازپس‌گیری قارص، اردهان و باتوم", "da82636f"], "d": ["پیمانی که میان روسیه‌ای که پس از انقلاب بلشویکی از جنگ کناره گرفته بود و دول متحد امضا شد، جبهه شرق را بست و قارص، اردهان و باتوم (الویه ثلاثه) را که عثمانی با پیمان برلین 1878 از دست داده بود به دولت عثمانی بازگرداند. این تنها دستاورد سرزمینی بود که در تاریخ عثمانی پس از وقفه چهل‌ساله به دست آمد. اما پس از آتش‌بس مودروس منطقه دوباره از دست خواهد رفت و راه‌حل قطعی با پیمان قارص 1921 خواهد آمد.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["نیروهای عثمانی به آرتوین وارد شدند", "ca7d1778"], "d": ["نیروهای عثمانی که در 25 مارس از مرز 1914 گذشتند، بر الویهٔ ثلاثه که برست-لیتوفسک مرز پیش از 1878 را بازگردانده بود لشکر کشیدند و در 28 مارس 1918 به آرتوین وارد شدند. آرتوین به‌عنوان بخشی از سنجق باتومی در 1878 به روسیه واگذار شده بود؛ مدخل آرتوین در TDV بازگشت را تنها «مارس 1918» می‌نویسد، روز را مصطفی ساری می‌دهد.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["اردهان به دست ارتش ترک افتاد", "7fd9e3db"], "d": ["در عملیات الویهٔ ثلاثه، سپاه عثمانی پس از آرتوین، اردهان را در 3 آوریل 1918 گرفت؛ اردهان در جنگ نود و سه در 1877 سقوط کرده و در 1878 به روسیه واگذار شده بود. قارص یک ماه بعد، در 25 آوریل، گرفته می‌شد.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["بازپس‌گیری باتومی", "d37a1a0d"], "d": ["پس از کناره‌گیری روسیه از جنگ با پیمان برست-لیتوفسک، سپاه عثمانی که به‌سوی شرق پیش می‌رفت، بندر باتومی را که در 1878 از دست رفته بود پس از چهل سال بازپس گرفت. این بندر در انتهای شرقی دریای سیاه، خروجی دریایی نفت باکو بود. این دستاورد تنها هفت ماه پایید؛ پس از متارکهٔ مودروس منطقه تخلیه می‌شد.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["الویهٔ ثلاثه: قارص به اداره عثمانی درآمد", "02cbf0b3"], "d": ["در برست-لیتوفسک بازگرداندن سه سنجقی که با پیمان برلین 1878 از دست رفته بود — قارص، اردهان و باتومی — مقرر شد؛ سپاه عثمانی در 3 آوریل به اردهان، در 14 آوریل به باتومی و در 25 آوریل 1918 به قارص وارد شد و اداره عملاً برقرار گردید. این سرزمین‌ها که به نام «الویهٔ ثلاثه» یاد می‌شود، جبران زیانی شمرده می‌شد که از جنگ نود و سه (Doksanüç Harbi) ادامه داشت. پس از متارکه دوباره از دست می‌رفت و تنها با پیمان قارص 1921 قطعاً به ترکیه می‌پیوست.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["تصرف ایغدیر — پیشروی در دره ارس", "87ebf4d3"], "d": ["در چارچوب عملیات پیشروی که در فوریه 1918 آغاز شد، نیروهای ترک در سردارآباد در شمال ارس نیروهای ارمنی را شکست دادند و ایغدیر را در 20 مه 1918 تصرف کردند. ایغدیر جزو الویهٔ ثلاثه نبود و ناحیهٔ سورملی از گوبرنیای ایروان بود؛ پس از حدود 180 سال نخستین اداره عثمانی در منطقه برقرار شد.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["درگذشت محمد پنجم رشاد و جلوس محمد ششم وحیدالدین", "d302ba07"], "d": ["محمد پنجم رشاد که سلطنت نه‌ساله‌اش با جنگ‌های طرابلس غرب، بالکان و جهانی گذشت، در بحرانی‌ترین دوره جنگ درگذشت و برادرش وحیدالدین با نام محمد ششم بر تخت نشست. پادشاه تازه کوشید از قیمومیت کادر اتحادی رها شود؛ چهار ماه بعد که آتش‌بس امضا شد ناگزیر می‌شد اداره برچیده شدن امپراتوری را برعهده بگیرد. او سی و ششمین و واپسین پادشاه دودمان عثمانی بود.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["رسیدن ناوگان ائتلاف به برابر استانبول و اشغال عملی شهر", "d10cb14d"], "d": ["پس از آتش‌بس مودروس ناوگان متحدان مرکب از بیش از شصت کشتی انگلیسی، فرانسوی، ایتالیایی و یونانی در برابر دلمه‌باغچه لنگر انداخت و استانبول عملاً به اشغال درآمد. پس از چهارصد و شصت و پنج سال پایتخت نخستین بار زیر نظارت سربازان بیگانه رفته بود. سخنی که روایت می‌شود مصطفی کمال پاشا همان روز با پیاده شدن در حیدرپاشا و دیدن منظره گفت، یعنی «همان‌گونه که آمده‌اند می‌روند»، یکی از جمله‌های نمادین نبرد ملی می‌شد.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["عقب‌نشینی در منطقهٔ ارس: ایغدیر تخلیه شد", "57572ab4"], "d": ["بر پایهٔ حکم عقب‌نشینی به پشت مرز 1914 در متارکهٔ مودروس، یعقوب شوکی پاشا با فرمان 21 نوامبر دستور داد نیروهای بیرون از مرز برست-لیتوفسک تا 4 دسامبر عقب کشیده شوند؛ ایغدیر و پیرامون آن در این تاریخ یکسره تخلیه شد. سپس دولت ارس-ترک در اواخر دسامبر 1918 به دست ارمنی‌ها برانداخته شد.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["انگلیسی‌ها در آرتوین مستقر شدند", "e2cb3153"], "d": ["چون متارکهٔ مودروس در 30 اکتبر 1918 عقب‌نشینی سپاه عثمانی به پشت مرز 1914 را شرط کرده بود، آرتوین تخلیه شد و در 17 دسامبر 1918 به دست انگلیسی‌ها اشغال گردید. بر پایهٔ مدخل آرتوین در TDV اشغال انگلیس تا آوریل 1920 ادامه یافت.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["اداره بریتانیا در باتومی پس از مودروس", "9dd768fc"], "d": ["بر پایهٔ متارکهٔ مودروس در 30 اکتبر 1918 دولت عثمانی ناگزیر از ترک باتومی شد؛ شهر در 24 دسامبر 1918 به دست نیروهای بریتانیا گرفته شد. باتومی که در آوریل 1918 مرکز سنجقی مستقل شده بود، از این تاریخ تا ژوئیه 1920 زیر نظارت انگلیس ماند.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["اردهان به سلطهٔ گرجی‌ها درآمد", "97cf47f6"], "d": ["اردهان را که پس از مودروس تخلیه شده بود، نیروهای گرجی در روزهایی که انگلیسی‌ها دولت قفقاز جنوب‌غربی را منحل می‌کردند، در 20 آوریل 1919 اشغال کردند. سلطهٔ گرجی تا 23 فوریه 1921 ادامه می‌یافت.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["پرستون اداره قارص را به والی ارمنی سپرد", "efa81cb0"], "d": ["پرستون، فرمانده انگلیسی که در 12-13 آوریل 1919 دولت قفقاز جنوب‌غربی را منحل کرد، دولت شورایی موقت را در 30 آوریل 1919 ملغی ساخت و اداره شهر را به کارگانوف ارمنی که والی قارص شده بود سپرد؛ دورهٔ اداره ارمنی در قارص آغاز شد و تا پیروزی کاظم قره‌بکر در 30 اکتبر 1920 ادامه یافت.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["کنگره ارزروم: تصمیم مقاومت ملی ولایات شرق", "41ef0457"], "d": ["کنگره‌ای که انجمن دفاع از حقوق آناتولی شرقی گرد آورد، پس از به تأخیر افتادن با فشار انگلیس با پنجاه و شش نماینده گشوده شد و مصطفی کمال پاشا که از نظامی‌گری استعفا داده بود به ریاست آن برگزیده شد. کنگره اعلام کرد که در مرزهای ملی میهن یک کل است، قیمومت و حمایت پذیرفتنی نیست و در صورت فروپاشی دولت ملت سرنوشت خود را به دست خواهد گرفت. این تصمیم‌ها شش ماه بعد هسته متن میثاق ملی را می‌ساخت.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["کنگره سیواس: یکی شدن مقاومت ملی زیر یک سقف", "0e9ad36b"], "d": ["کنگره‌ای که در 4 سپتامبر 1919 در سلطانی سیواس کار خود را آغاز کرد، انجمن‌های دفاع از حقوق را در سراسر کشور با نام انجمن دفاع از حقوق آناتولی و روم‌ایلی یکی کرد و هیئت نمایندگی برگزید. پیشنهاد قیمومت آمریکا پس از گفتگوهای دراز رد شد. با اعلامیه‌ای که در 11 سپتامبر منتشر شد، نبرد ملی به جنبشی سیاسی با یک مرکز و مشروع بدل شد و کشمکش آشکار قدرت با دولت استانبول آغاز گشت.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["پروتکل آماسیه: گفتگوی دولت استانبول با هیئت نمایندگی", "40e6a6ab"], "d": ["پس از سقوط داماد فرید و برپایی دولت علی‌رضا پاشا، وزیر دریاداری صالح پاشا برای گفتگو با هیئت نمایندگی به آماسیه فرستاده شد. با پروتکل‌هایی که به دست آمد دولت استانبول عملاً وجود جنبش آناتولی را پذیرفت؛ گرد آمدن مجلس مبعوثان، آزاد بودن انتخابات و حفظ مرزهای ملی پذیرفته شد. این نخستین دستاورد رسمی سیاسی نبرد ملی در برابر استانبول است.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["پذیرش میثاق ملی در واپسین مجلس عثمانی", "6322865e"], "d": ["متن پیمان ملی که 121 نماینده در واپسین مجلس مبعوثان عثمانی امضا کردند، یکپارچگی تقسیم‌ناپذیر سرزمین‌هایی را که درون خط مودروس مانده و اکثریت مسلمان-ترک در آن زندگی می‌کند، همه‌پرسی در ولایات عربی و تراکیه غربی، برچیدن کاپیتولاسیون‌ها و استقلال کامل سیاسی-مالی را شرط می‌کرد. متن در 17 فوریه 1920 به اتفاق آرا پذیرفته و به جهان اعلام شد. این اعلامیه همان‌قدر که برنامه سیاسی نبرد ملی بود نقشه مرزهایی بود که در لوزان از آن دفاع می‌شد؛ علت بی‌واسطه اشغال رسمی استانبول به دست دولت‌های ائتلاف در 16 مارس شد.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["آرتوین هنگام عقب‌نشینی انگلیسی‌ها در گرجستان ماند", "6d086b06"], "d": ["بر پایهٔ مدخل آرتوین در TDV اشغال انگلیس تا ماه آوریل 1920 ادامه یافت؛ انگلیسی‌ها هنگام عقب‌نشینی شهر را به گرجستان واگذاشتند. آرتوین تا اولتیماتوم مجلس بزرگ ملی ترکیه در 23 فوریه 1921 در دست گرجستان ماند.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["باتومی به اداره گرجی واگذار شد", "6523d095"], "d": ["واگذاری رسمی باتومی از سوی انگلیسی‌ها به گرجی‌ها در 7 ژوئیه 1920 انجام شد (مدخل باتومی در TDV تنها «ژوئیه 1920» می‌نویسد). دولت آنکارا در 25 ژوئیه این واگذاری را به‌عنوان «اشغال» اعتراض کرد.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["پیمان گومری: نخستین پیمان بین‌المللی دولت مجلس ملی بزرگ", "9232c690"], "d": ["چون سپاه جبهه شرق به فرماندهی کاظم قره‌بکیر ساری‌قمیش و قارص را بازگرفت، ارمنستان صلح خواست و با پیمانی که در گومری امضا شد پذیرفت که سور را نمی‌شناسد و از خواسته‌های سرزمینی خود در شرق چشم می‌پوشد. این نخستین پیمانی که دولت آنکارا امضا کرد، نخستین سند بین‌المللی شد که سور را عملاً رد می‌کرد و راه شناخته شدن حقوقی را بر مجلس ملی بزرگ گشود. مرز شرقی بدین‌سان ایمن شد و جابه‌جا کردن نیرو به جبهه باختر ممکن گشت.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["نبرد نخست اینونو: نخستین پیروزی سپاه منظم", "4add3719"], "d": ["سپاه منظم نوبنیاد، نیروهای یونانی را که از سوی بورسا پیش می‌آمدند در مواضع اینونو متوقف کرد و به عقب‌نشینی ناگزیر ساخت. این موفقیت که از نظر نظامی در مقیاسی محدود بود، از نظر پیامدهای سیاسی بسیار بزرگ بود: دولت آنکارا به کنفرانس لندن دعوت شد، راه پیمان مسکو با روسیه شوروی گشوده شد و قانون اساسی تشکیلات پذیرفته شد. اعتماد افکار عمومی درونی به سپاه منظم نیز با این پیروزی استوار شد.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["نبرد دوم اینونو: شکسته شدن حمله یونان برای بار دوم", "a974521c"], "d": ["سپاه یونان که از کنفرانس لندن نتیجه‌ای نگرفته بود از سوی بورسا و اوشاک به حمله‌ای تازه دست زد، اما دوباره در پشته‌های اینونو متوقف شد و ناگزیر عقب نشست. تلگرافی که مصطفی کمال پاشا به عصمت پاشا فرستاد، یعنی «شما آنجا نه تنها دشمن را بلکه بخت شوم ملت را نیز شکست دادید»، پس از این پیروزی نوشته شد. نبرد اعتبار بین‌المللی نبرد ملی را بالا برد و روند عقب‌نشینی ایتالیا از آناتولی را شتاب بخشید.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["موافقت‌نامه آنکارا: صلح با فرانسه و بسته شدن جبهه جنوب", "35fc32db"], "d": ["با موافقت‌نامه‌ای که پس از پیروزی ساکاریا در آنکارا با فرانسه امضا شد جنگ در جبهه جنوب پایان یافت؛ نیروهای فرانسوی چوکوروا و جنوب‌خاوری از جمله آدانه، عینتاب، مرعش و اورفه را تخلیه کرده و به مرز سوریه عقب نشستند. یکی از دولت‌های ائتلاف بدین‌سان دولت آنکارا را عملاً شناخت و نخستین شکاف در جبهه سور گشوده شد. سلاح‌هایی که از مناطق تخلیه‌شده گرفته شد و یگان‌های آزادشده در تدارک حمله بزرگ نقشی حیاتی ایفا کردند.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["آتش‌بس مودانیا: واگذاری بی‌جنگ استانبول و تنگه‌ها", "ac0d9baf"], "d": ["پس از حمله بزرگ، چون سپاه ترک در چاناق‌قلعه و ایزمیت با نیروهای انگلیس رودررو شد، کنفرانسی که در مودانیا گرد آمد پس از یازده روز چانه‌زنی سخت به آتش‌بس انجامید. تخلیه تراکیه شرقی تا مریچ ظرف پانزده روز به دست یونان و تحویل آن به اداره ترک و نیز تسلیم استانبول و تنگه‌ها با پیمان صلح پذیرفته شد. بدین‌سان مرحله مسلحانه نبرد ملی بی‌شلیک گلوله‌ای با پیروزی دیپلماتیک بسته شد و دروازه لوزان گشوده گشت.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["ترک استانبول به دست محمد ششم وحیدالدین و برگزیده شدن عبدالمجید افندی به خلافت", "8ab0e847"], "d": ["محمد ششم وحیدالدین، واپسین پادشاه که پس از برچیده شدن سلطنت منزلتش بحث‌برانگیز شده بود، در بامداد جمعه 17 نوامبر 1922 با زره‌پوش انگلیسی مالایا از استانبول رفت و به مالت رسید. مجلس ملی بزرگ دو روز بعد، در 19 نوامبر، عبدالمجید افندی را به‌عنوان خلیفه‌ای بی‌اختیار سیاسی برگزید. فرمانروایی دودمانی عثمانی که ششصد و بیست و سه سال ادامه داشت بدین‌سان عملاً پایان یافت؛ خلافت پانزده ماه دیگر نمادین ماند. وحیدالدین که به مالت و سپس ایتالیا رفت، در ویلا نوبل در سن‌رمو اقامت کرد؛ از درخواست‌هایی که برای پذیرفته شدن در کشوری مسلمان کرد نتیجه‌ای نگرفت و در 16 مه 1926 همان‌جا، با تکرار اینکه هرگز از حقوق سلطنت و خلافت چشم نپوشیده، درگذشت.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["درگذشت واپسین پادشاه، محمد ششم وحیدالدین، در سن رمو", "7149ed0e"], "d": ["محمد وحیدالدین، واپسین پادشاه عثمانی، که پس از ترک استانبول در شهر سن رمو در ایتالیا ساکن شده بود، در 16 مه 1926، بی‌آنکه خبر برگزاری کنگرهٔ خلافت (13 مه 1926) را بشنود — کنگره‌ای که او اعلام کرده بود هرگز از حقوق سلطنت و خلافت صرف‌نظر نکرده است — درگذشت. او دچار تنگدستی سختی بود؛ به بازاریان سن رمو 60.000 لیره بدهکار بود و طلبکاران پس از شنیدن مرگ او اثاث خانه‌اش را توقیف کردند.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["فتح ناحیهٔ بولو از سوی قونورالپ — مودورنو، قونورابا و بولو", "e245cd27"], "d": ["قونورالپ، از فرماندهان اورخان غازی، به کوهستان‌های شرق ساکاریا روی آورد و ناحیهٔ مودورنو، قونورابا و بولو را به اداره عثمانی پیوست؛ شهرکی در دشت دوزجه به نام او یاد شد. تاریخ دقیق فتح معلوم نیست؛ روایت بر نقل عاشق‌پاشازاده استوار است. منطقه در آن زمان سرزمین مرزی‌ای بود که میان جاندار‌اوغولاری و بیزانس دست‌به‌دست می‌شد؛ فتح، عثمانی را نخستین بار به ساحل باختری دریای سیاه نزدیک کرد. پس از نبرد آنکارا ناحیه دوباره به جاندار‌اوغولاری می‌رفت، اما در دورهٔ فاتح قطعاً بازپس گرفته می‌شد.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["تصرف شهرک‌های بیزانسی جنوب مرمره — میخالیچ، کیرماستی، گولیازی", "9c61b8d4"], "d": ["پس از گرفته شدن ایزنیک و ایزمیت، شهرک‌هایی که در باختر دشت بورسا در دست بیزانس مانده بود یکی‌یکی به اداره عثمانی درآمد. گولیازی در پیرامون دریاچهٔ اولوآباد، کیرماستی در کنار رود سوسورلوک و میخالیچ راهرویی را که ساحل جنوبی مرمره را به سرزمین‌های قره‌سی می‌پیوست تکمیل کردند. این شهرک‌ها مدتی دراز بی‌آنکه محاصره ببینند، با بریده شدن پیرامونشان تسلیم شدند؛ حضور بیزانس در منطقه بدین‌سان به خلیج گملیک فشرده شد.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["گوردوس (کورنت) به دسپوتنشین موره رسید", "392495eb"], "d": ["کورنت که از 1358 تیمار وابسته به شاهزاده‌نشین آخائیا از خانوادهٔ فلورانسی آچایولی بود، در 1395 به دست تئودوروس، دسپوت موره از بیزانس، افتاد. شهر از این پس تا فتح عثمانی زیر اداره دسپوتنشین ماند.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["الحاق بیگی حاجی‌امیراوغولاری — اوردو و اونیه", "c064f07f"], "d": ["بیگی ترکمنی که بایرام بی پیرامون اوردو بنیاد نهاده و پسرش حاجی امیر در دههٔ 1350 گسترده بود، دولتی ساحلی کوچک اما راهبردی با مرکز در اسکی‌پازار امروزی بود: تنها حوزهٔ فرمانروایی مستقل میان سامسون و طرابزون بود. امیر سلیمان در 1398 در عملیات جانیک یلدرم بایزید بیعت خود را اعلام کرده بود، پس از نبرد آنکارا بیگی دوباره آزاد شده بود. در دورهٔ مراد دوم، همزمان با برچیده شدن تاج‌الدین‌اوغولاری، سرزمین‌های بیگی مستقیماً به اداره عثمانی پیوست و ساحل دریای سیاه از سامسون تا گیرسون در یک دست گرد آمد.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["فتح گوردوس (کورنت)", "87a2bc59"], "d": ["در لشکرکشی موره فاتح، قلعهٔ آکروکورنت سه ماه محاصره شد و سرانجام از راه صلح تسلیم گرفته شد. کورنت‌ی که دروازهٔ موره شمرده می‌شد بدین‌سان به عثمانی رسید.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["پیوستن مونته‌نگرو به اداره عثمانی — ستینیه", "7fdb7cc8"], "d": ["چون دودمان چرنوییچ که بر زتا فرمان می‌راند در 1496 فرمانروایی را رها کرد، منطقهٔ کوهستانی مونته‌نگرو که حیاط خلوت شکودر بود مستقیماً به اداره عثمانی درآمد و نخست سنجقی جداگانه و سپس بخشی از سنجق شکودر سازمان یافت. صومعهٔ ستینیه به‌عنوان مرکز دینی منطقه به جای خود ماند. به سبب سختی جغرافیا اداره در آنجا هرگز مانند دشت‌ها سخت‌گیرانه عمل نکرد؛ دو سده بعد اداره ولادیکا که از همین صومعه برآمد هستهٔ استقلال عملی می‌شد.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["پذیرش سلطهٔ عثمانی از سوی قلعهٔ بایزید در لشکرکشی عراقین", "f29e2e17"], "d": ["هنگامی که صدراعظم ابراهیم پاشا در لشکرکشی عراقین به پیرامون بینگول آمد، قلعه‌های وان، توپراق‌قلعه، آونیک و بایزید همراه با بسیاری از عشایر کرد منطقه راضی شدند که به سلطهٔ عثمانی درآیند. بایزید در 1514 در لشکرکشی یاووز به عثمانی پیوسته بود، اما چون سپاه بازگشت صفویان منطقه را بازپس گرفته بودند.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["بازگشت تبریز به صفویان — بازگشت عراقین", "80b8b761"], "d": ["در لشکرکشی عراقین سپاه به تبریز وارد شده بود، اما چون هدف اصلی بغداد بود، پادگانی پایدار در شهر نگذاشته شد. هنگامی که سپاهی که زمستان را در بغداد گذرانده بود به باختر بازمی‌گشت، شاه طهماسب دوباره به آذربایجان تخلیه‌شده وارد شد و تبریز را بازپس گرفت. این الگوی تکراری جنگ‌های عثمانی-صفوی بود: تبریز پنج بار گرفته شد و هر پنج بار نگاه داشته نشد؛ شهر تنها در 1585 صاحب پادگان عثمانی درازمدت می‌شد.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["افتادن وان و ارجیش به دست طهماسب (موضع عثمانی در 1534-35 پایان یافت)", "cb93d561"], "d": ["در منطقه‌ای که وان را در 1534 به سلطهٔ عثمانی داده بود، اولاما پاشا در قلعهٔ وان در برابر محاصرهٔ صفوی ایستاد؛ قلعه به دست صفویان افتاد، نیروهای صفوی که ارجیش را محاصره کرده بودند نیز با یاری عثمانی عقب کشیده شده بودند. هنگامی که قانونی به اخلاط رسید (23 سپتامبر 1535) وان دیگر در دست طهماسب بود. وان تا 1548 صفوی ماند.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["گذشتن سنجق بایزید به سلطهٔ صفوی (وان و ارجیش در 1535 پیشتر صفوی بود)", "806a2cf1"], "d": ["سنجق بایزید که در میانهٔ مرز عثمانی-صفوی بود دوباره به دست ایران افتاد (Kaya 2017 این را «همراه با وان و ارجیش» یاد می‌کند؛ اما وان و ارجیش بر پایهٔ Karataş 2025 و TDV در 22 سپتامبر 1535 به صفوی بازگشته بود — نک. مادهٔ پیشین)؛ در این دست‌به‌دست شدن، برخی جاهای سنجق ویران شد. سنجق تا ربع پایانی سدهٔ 16 میان دو دولت بارها دست‌به‌دست شد.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["گذشتن دوبارهٔ سنجق بایزید به عثمانی در لشکرکشی نخجوان", "cf0171fa"], "d": ["در سومین لشکرکشی ایران (نخجوان) قانونی، سنجق بایزید دوباره به اداره عثمانی درآمد. در لشکرکشی 1554 بایزید پایگاه مهمی برای سپاه شد؛ سنجق در 1578 قطعاً به حاکمیت عثمانی درآمد.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["از دست رفتن ایروان به شاه عباس", "34413cf2"], "d": ["در سال‌هایی که شورش‌های جلالی آناتولی را قفل کرده بود، جبههٔ شرق بی‌دفاع ماند و شاه عباس که سپاه خود را به شیوهٔ اروپایی از نو سازمان داده بود به حمله پرداخت. قلعهٔ ایروان که فرهاد پاشا در 1583 ساخته بود پس از هفت ماه محاصره تسلیم شد. نخستین حلقهٔ خط قفقاز که با پیمان فرهاد پاشا به دست آمده بود گسسته بود؛ ظرف سه سال پس از آن همهٔ قفقاز جنوبی از دست می‌رفت.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["از دست رفتن تفلیس و گنجه", "3fb51753"], "d": ["پس از سقوط ایروان، سپاه صفوی در امتداد دره کُر پیش رفت؛ گنجه، مرکز قره‌باغ، و تفلیس، پایتخت گرجستان، پشت سر هم از دست رفت. دولت عثمانی همزمان جنگ درازِ سیزده‌سالهٔ جبههٔ اتریش را پیش می‌برد و در آناتولی با جلالی‌ها دست‌وپنجه نرم می‌کرد؛ نیرویی برای فرستادن به شرق نبود. بدین‌سان نظم گستردهٔ ایالت‌های قفقاز که با پیمان فرهاد پاشا در 1590 برپا شده بود عملاً پایان یافت.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["از دست رفتن شیروان — شماخی، باکو و دربند", "81beab11"], "d": ["ایالت شیروان در ساحل خزر که با لشکرکشی‌های عثمان پاشا اوزدمیراوغلو در 1578-1585 به دست آمده بود و به‌عنوان منبع اصلی تجارت ابریشم درآمد قابل‌توجهی برای خزانهٔ عثمانی فراهم کرده بود، با عملیات شاه عباس که به شمال روی آورد و شماخی، باکو و دربند را پیاپی گرفت برچیده شد. زیان تنها سرزمین نبود: راه ابریشم ایران که از راه عثمانی به اروپا می‌ریخت از کنترل بیرون رفت و دولت صفوی بازاریابی ابریشم را از راه اقیانوس هند آغاز کرد.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["از دست رفتن تعز", "65f20d53"], "d": ["عثمانی‌ها در 1038 (1629) همراه با سلطهٔ یمن که به اداره قاسمی در صنعا واگذاشته شد، تعز را نیز رها کردند — نخستین گام بزرگ در فرایند بازپس‌گیری یمن درونی از سوی امامان زیدی.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["از دست رفتن یمن — سلطهٔ امامان قاسمی", "49e83e3c"], "d": ["یمن از 1538 ایالت عثمانی بود؛ اما مقاومت امامان زیدی هرگز قطع نشد. قیامی که امام قاسم آغاز کرده بود در دورهٔ پسرش المؤید محمد به سراسر کشور گسترد و پادگان‌های عثمانی یکی پس از دیگری محاصره شد. در سال‌هایی که مراد چهارم بر بغداد و ایروان متمرکز بود، نیروی کمکی فرستاده نشد؛ تعز در 1629 از دست رفته، مخا نیز در واپسین مرحلهٔ همین فروپاشی در 22 اکتبر 1635 تخلیه شده بود. در 1635 واپسین نیروها در صنعا و زبید نیز یمن را تخلیه کردند. بدین‌سان ساحل شرقی دریای سرخ دویست و سی و هفت سال بیرون از امپراتوری ماند و تنها در 1872 توانست بازگردانده شود. لحج (الحوطه) بر پایهٔ دانشنامهٔ اسلامی TDV تا 1635 در دست عثمانی‌ها بود؛ از آن تاریخ امامان زیدی مؤثر شدند.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["تخلیهٔ مخا", "c6b3061a"], "d": ["مصطفی بی در 10 جمادی‌الاولی 1045 (22 اکتبر 1635) با نیرو و سلاح باقی‌مانده مخا را تخلیه کرد؛ سپس حسن بن قاسم، پسر امام قاسم، کسان خود را در زبید و مخا گماشت و در ساحل تهامه نیز کنترل قاسمی را برقرار کرد.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["از دست رفتن احساء به امارت بنی‌خالد", "a9b6131a"], "d": ["احساء ایالتی بود که در 1550 برای بستن ساحل باختری خلیج بصره به روی پرتغال برپا شده بود؛ اما از استانبول بسیار دور و در انتهای یک راه بیابانی بود. در سال‌هایی که محاصرهٔ کریت منابع را تهی کرده بود، قبیلهٔ بنی‌خالد در منطقه به رهبری براک بن غریر پادگان عثمانی را بیرون راند و امارت خود را برپا کرد. ساحل باختری خلیج یک و نیم سده در امارت‌های قبیله‌ای ماند؛ در 1795 به سعودی‌ها و در 1871 دوباره به عثمانی می‌گذشت.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["از دست رفتن پروزه و ووینیتسا به ونیز — گشوده شدن ساحل اپیروس", "1201204c"], "d": ["ونیز که به اتحاد مقدس پیوسته بود، پیش از آغاز لشکرکشی موره دو قلعه‌ای را که دهانهٔ خلیج آمبراکیا را در اختیار داشت گرفت: پرِوزه و ووینیتسا در ساحل مقابل. در همان تابستان ایامائورا (لفکاده) نیز سقوط کرده بود. این سه موضع ورود ایمن ناوگان را از دریای ایونی به درون یونان ممکن کرد و پایگاه عملیات موره شد که سال بعد آغاز می‌گردید. پروزه و ووینیتسا در پاساروفچا نیز در دست ونیز ماند؛ تنها در 1798 به اداره عثمانی بازمی‌گشت.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["از دست رفتن سولنوک — گسستن خط تیسا", "51c2c8ef"], "d": ["پس از سقوط اویوار در ماه اوت، سپاه هابسبورگ به جنوب برگشت و سولنوک، سرپل رود تیسا، را گرفت. شهر تنها گذرگاه ایمن میان بودین و ترانسیلوانیا بود؛ از دست رفتنش به معنای گسسته شدن قلعه‌های عثمانی در نیمهٔ شرقی مجارستان از یکدیگر بود. قطع شدن راه تدارکات در محاصرهٔ بودین در سال بعد تعیین‌کننده شد.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["از دست رفتن مودون به ونیز", "114c9cc0"], "d": ["مودون در جنوب‌غربی‌ترین نقطهٔ شبه‌جزیرهٔ موره، بندری بود که ونیز سه سده پیش از دست داده بود و آن را «یکی از دو چشم دولت» می‌نامید. قلعه که پس از سقوط کورون محاصره شد، همزمان از خشکی و دریا کوبیده و تسلیم گرفته شد. عملیات موره به فرماندهی موروزینی بدین‌سان همهٔ ساحل باختری شبه‌جزیره را گرفت و راه به درون خشکی گشوده شد.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["از دست رفتن پچوی", "99d54cf4"], "d": ["پس از سقوط بودین در سپتامبر، نیروهای هابسبورگ در باختر دانوب به جنوب فرود آمدند و پچوی را که از دورهٔ قانونی عثمانی بود گرفتند. شهری که به مسجد غازی قاسم پاشا شناخته می‌شد، از پیشرفته‌ترین مراکز سنجق ایالت بودین بود. از دست رفتنش به معنای گشوده شدن راهی بود که به دشت موهاچ فرود می‌آمد؛ سال بعد شکست دوم موهاچ درست در همین‌جا رخ می‌داد.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["از دست رفتن سگدین", "9fbee1b2"], "d": ["سگدین در نقطهٔ پیوستگی رودهای تیسا و مارُش، دروازهٔ جنوبی دشت مجارستان بود و راه ایالت تمشوار را در اختیار داشت. قلعه که پس از سقوط بودین و پچوی در همان پاییز محاصره شد، در مدتی کوتاه تسلیم شد. از دست رفتن سه قلعه در یک فصل، نشانهٔ آن بود که ساختار اداری عثمانی در مجارستان که از 1541 برپا بود شروع به فروپاشی کرده است. اطلس در همان روز زنتا را نیز در کنار تیسا از عثمانی به سوی هابسبورگ گذشته می‌شمارد (روز تسلیم ویژهٔ زنتا در منبع خوانده نشد، روز از سگدین گرفته شد؛ TDV zenta: از اکتبر 1686 درگیری‌هایی میان عثمانی و متحدان به پیشگامی هابسبورگ آغاز شد — تقریب بیان‌شده).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["از دست رفتن بالیابادرا (پاتراس) — دروازهٔ شمالی موره", "b9cff63c"], "d": ["بالیابادرا در دهانهٔ خلیج کورنت، بندری بود که گذرگاه میان موره و روم‌ایلی را زیر نظر داشت. پس از آنکه سپاه ونیز شهر را گرفت، قلعه‌های دو سوی خلیج نیز یکی‌پس‌ازدیگری سقوط کرد و شبه‌جزیره از خشکی یکسره منزوی شد. در پایان این عملیات همهٔ موره به ونیز رسید؛ منطقه تا 1715 با نام «رگنو دی موره» اداره می‌شد.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["واگذاشتن گوردوس (کورنت) به ونیز", "9a25b6b9"], "d": ["پس از سقوط بالیابادرا، کورنت از راه صلح به ونیزی‌ها واگذاشته شد و مردم مسلمان شهر را ترک کردند. در اوت 1687 سپاه موروزینی برای لشکرکشی آتن در کورنت گرد می‌آمد.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["از دست رفتن اگری", "983391aa"], "d": ["اگری در 1596 با لشکرکشی‌ای که محمد سوم شخصاً در آن شرکت داشت گرفته شده و مرکز ایالتی به نام خود شده بود. این واپسین قلعهٔ بزرگ عثمانی در شمال مجارستان پس از شکست دوم موهاچ، یک سال کاملاً محاصره‌شده مقاومت کرد و از گرسنگی تسلیم شد. با از دست رفتنش جناح شمالی دولت عثمانی در مجارستان یکسره برچیده شد.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["از دست رفتن استولنی بلگراد — شهر تاج مجارستان", "c6147255"], "d": ["شهری که پادشاهان مجارستان سده‌ها در آن تاج می‌گذاشتند و در آن به خاک سپرده می‌شدند، در 1543 به دست قانونی گرفته شده و از مهم‌ترین مراکز سنجق ایالت بودین شده بود. حدود دو سال پس از سقوط بودین، قلعه که پیرامونش یکسره بریده شده بود تسلیم شد. با این زیان، حضور عثمانی در باختر دانوب به پیرامون سیرم و اوسیک فشرده شد.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["از دست رفتن ژیگتوار", "834910a7"], "d": ["ژیگتوار قلعه‌ای بود که سلطان سلیمان قانونی در سیزدهمین و واپسین لشکرکشی خود در 1566، هنگام محاصره، در آن درگذشت؛ از این رو در حافظهٔ عثمانی جایگاهی نمادین داشت. پس از یکصد و بیست و سه سال، پس از آنکه همهٔ قلعه‌های پیرامونش سقوط کرد، قلعه‌ای که با باتلاق‌ها محافظت می‌شد نیز تسلیم شد. آرامگاهی که اندام درونی قانونی در آن مدفون بود و شهرک پیرامونش پس از گذشتن به اداره هابسبورگ ویران شد. در همان تاریخ در اطلس سکونتگاه دیگری که از عثمانی به هابسبورگ می‌گذرد: بارچ — زنجیرهٔ ابی-مرکز ژیگتوار را دنبال می‌کند (Bánlaky 0017/1449؛ تقریب بیان‌شده).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["از دست رفتن وارد", "6cce360d"], "d": ["وارد قلعهٔ کلیدی بود که در 1660 کوپرولو محمد پاشا گرفت و مرکز ایالتی به نام خود ساخت و به ترانسیلوانیا می‌گشود. قلعه که پس از شکست سالانکامن کاملاً تنها مانده بود، پس از محاصره‌ای نزدیک به دو سال از گرسنگی تسلیم شد. با از دست رفتنش نفوذ عثمانی بر ترانسیلوانیا عملاً پایان یافت و سلطهٔ هابسبورگ در شرق تیسا مستقر شد.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["از دست رفتن یانوا — بسته شدن راه ترانسیلوانیا", "4b5e30d8"], "d": ["یانوا قلعه‌ای بود که در 1658 گرفته شده و پیوند میان وارد و تمشوار را نگاه می‌داشت. بلافاصله پس از سقوط وارد چون پیرامونش بریده شد، آن نیز از دست رفت. بدین‌سان ایالت تمشوار از شمال یکسره منزوی شد و تا کارلوفچا به‌عنوان تنها سرزمین مجارستان که در دست عثمانی مانده بود به هستی خود ادامه داد.", "67168a2e"]}
});
